/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20191007-4","meetingId":"r01-c-settlement","date":"2019年10月7日","dateIso":"2019-10-07","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度品川区一般会計歳入歳出決算","agenda":"平成３０年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"ページ２７１、定期予防接種から風しん第５期定期接種について、順次お尋ねしていきたいと思います。麻しんについてお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"１０月４日時点で都内４人、都外６人、合わせて１０人の患者の発生を確認しております。近くの人には感染拡大がある可能性を考えまして、事前に住所地の保健所に連絡をしてから医療機関を受診するようにというお願いをしているものです。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"確認","question":"弊社本社内（東京都品川区東品川四丁目１２番２号品川シーサイドウエストタワー）にて麻疹の感染発症者が複数確認されましたことをご報告申し上げま…この部署は１００人ほどの社員が働いており、保健所の指導でその日のうちに症状の確認などが行われました。","respondent":"鷹箸保健予防課長","answer":"その後、患者が増え続けまして、現在までの間に都内外合わせて４３の保健所に対して、現在２９７名の方に対して健康監視の実施をお願いしております。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"川崎市のお話が出たのですけれども、実は川崎市のホームページとかを見ますと、それから中目黒駅などの区間をたびたび電車で移動しているようです。これは外国から輸入された外国で感染した麻しんのようですが、この五反田近辺での麻しん発生例についても、追加でご説明お願いします。","respondent":"鷹箸保健予防課長","answer":"麻しん患者との接触歴を伝えた上で医療機関を受診するようにということで、今急ぎ指導と、連日監視をしています。","id":"exchange-003"},{"speaker":"鈴木（博）委員","kind":"質問","question":"なぜ麻しんという病気がこれほど恐れられ、厳重な封じ込め対策が行われているのでしょうか。麻しんという病気の説明と感染対策が厳重に行われる理由について、いま一度ご説明をお願いいたします。","respondent":"鷹箸保健予防課長","answer":"発熱、発疹といった特徴的な症状に加え、脳炎などを合併して死亡することもまれではございません。一たびこの感染が治ったとしても、１０年以上経ってから重篤な脳炎を改めて起こして亡くなることもある、そういった意味では本当に重篤な疾患です。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"麻しんは今なお先進国でも１,０００人に１人は死亡すると言われるほど、軽視できない恐ろしい感染症なのです。このＳＳＰＥについて、改めてご説明お願いします。","respondent":"鷹箸保健予防課長","answer":"小児期に麻しんに感染して一度治ったと思ったのに１０年以上、急に表情が乏しくなるといった、気がついたら体が徐々に動かなくなる。その間、治療法がありませんので、大変残念なことですが、そのまま死を待つ状態になるという非常に恐ろしい、後発で起きてくる合併症です。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"日本でも今年感染者が２０１４年の４６２人を突破して、ここ１０年で最悪の流行になっております。品川区は現在の麻しん集団発生に対し、今後どのような対応をとっていくおつもりなのか、最後にお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"生後６カ月以上であれば、残念ながら今回は接触後３日以内を過ぎてしまっているので、それも現時点では間に合わないということ。とにかく未接種の方に確実にワクチンを接種していただくことが非常に重要だと考えております。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、麻しん同様、現在もわが国で流行が続いている風しん対策についてお尋ねいたします。２０１８年から２０１９年の本シーズンにおける先天性風しん症候群の赤ちゃんの発生についても一緒にご報告お願いします。","respondent":"鷹箸保健予防課長","answer":"昨年７月以降、前の年の実に３１倍に当たる数ですが、今年につきましては９月２１日までに２,１９６人もの患者が報告されております。今回の流行によりまして、先天性風しん症候群の赤ちゃん、今年の６月までですが３例、東京、埼玉、大阪で報告されております。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"常に流行の温床となっている３０代～５０歳代の男性に、風しんに対する免疫をつけるために、現在風しん第５期定期接種が今年の４月から始まりました。この事業の内容と現状について、簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"４月から始まった風しん第５期は、これまで風しんの予防接種の機会がなかった、今年４０歳～５７歳の男性を対象とした予防接種です。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先天性風しん症候群の赤ちゃんをなくすためには、３０代～５０代の風しんに対する免疫を持たない成年男性にいかにワクチンの接種を受けてもらうか。このことに関しましては、もう時間がありませんので、今後一般質問等でさらに続けていろいろご質問してご協議していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問","question":"一般質問でも申し上げました早期療育について伺ってまいります。この人数は多いとお考えでしょうか、少ないとお考えか尋ねました。","respondent":"仁平品川保健センター所長","answer":"経年を見てみますと、極端に下がったり減ったりということはございませんで、発見率は同じ形で推移していると認識しています。お母さんのお話とか子どもの様子から気になる場合には、その後心理の健康診査というのもございまして、個別に対応していく形になっております。","id":"exchange-010"},{"speaker":"西村委員","kind":"質問","question":"次に伺います。小学校入学前の段階、就学相談で、手挙げ式ではない進学前健診を行うことはできないか尋ねました。","respondent":"大関教育総合支援センター長","answer":"小学校あるいは義務教育学校前期課程入学前の就学前の段階のお子さんの就学相談に関しましては、教育総合支援センターで本人・保護者からお申込みいただいた方を対象に行っているのが現段階の実情です。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問","question":"母子手帳などの連携ができれば、もう少し早く早期発見につなげてあげられると思うのですが、いかがでしょうか。区の考えを説明を求めました。","respondent":"仁平品川保健センター所長","answer":"保護者の方がやはり納得しないとか、そういうふうに考えたくないという、これはお気持ちはわかります。保健師が丁寧に、勧奨を図りながら、子どもの将来のためにということで引き続き指導に当たってまいりたいと考えております。","id":"exchange-012"},{"speaker":"西村委員","kind":"提案","question":"一般質問でかおＴＶの導入を提案させていただきました。続きまして、武蔵小山創業支援センターのあり方について伺いますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"武蔵小山創業支援センターで行っている施設利用者に対しての起業に向けてのさまざまなサービスを提供するということで、事務の方でありますとか。スタッフとしましては、所管としましたら、適正な人数で適正なサービスを行っているかと思っているところです。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問・要望","question":"区外の方たちを表彰し、グランプリ３０万円、優秀賞１０万円が支給されています。幅広く募集するものと思われますが、ウーマンズビジネスグランプリの開催意図と目的を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの方々の創業に向けての計画について、コンテストを通じていろいろブラッシュアップをするような機会というようなことで実施しています。いろいろな形で連携、コラボしながら、最終的には区内の起業率を高めるということを目的にしています。","id":"exchange-014"},{"speaker":"西村委員","kind":"質問","question":"ＭＵＳＡＫＯトライアルマーケットに関しましては、出店者、集客ともに苦戦をしていたと伺っております。実際にはいかがでしたか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"例えば武蔵小山創業支援センターを利用して起業に向けた勉強をされたり、あるいは１階にはチャレンジショップというショップもあります。外から来た人も武蔵小山創業支援センターで登記をして区内企業に切り替わって、ご理解をよろしくお願いしたいと思うところです。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"１分になりましたので、まとめさせていただきたいのですけれども、センター自体の集客が認知にも直結すると考えております。１０年経っておりますので、運営の仕方を変化、転換させていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"新妻委員","kind":"提案","question":"一般質問でもお聞きいたしました妊産婦、乳児に特化した救護所の設置についてと、液体ミルクについてお伺いをいたします。文京区の事例を示して要望、提案をいたしましたところ、支援体制を検討するとの温かい前向きなご答弁をいただきましたとの意見を述べました。","respondent":"高山健康課長、仁平品川保健センター所長","answer":"妊産婦の救護所の設置です。これから考えられる検討の内容といたしましては、現在分娩キットということで、そうした備蓄品の見直しについても検討すべきと考えております。 現在のところ、保健センターに直接そのリーフレットの紹介というのは届いていないと承知しております。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひご確認をいただいて、やはりママ・パパの中では、正しい知識を持って使っていただくということの周知をしっかりと進めてほしいと求めました。あわせて、特にこの妊産婦・乳児の救護所には液体ミルクの備蓄をしていただきたいということを改めて要望しますが、いかがか尋ねました。","respondent":"中島防災課長","answer":"液体ミルクに関しましては、何らかの形で災害時に活用できないかというのは検討しています。販売店とも協力して協定とかいう形もできないかというのも含めまして、引き続き可能性を探っていきたいと考えています。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"特に、また改めてこの東京都のリーフレットと動画は確認を進めてほしいと求めましたので、よろしくお願いいたします。何か取り組みができるのかどうか、２０１９年度の予算の中では、お伺いをいたします。","respondent":"小林環境課長","answer":"委員からご紹介がありました食品ロス削減法に関する１０月の取り組みですが、ポスターの作成等につきましては、今年度の事業の中で進めるところです。来年度につきましても、この月間に見合うような事業展開は引き続き検討していきたいと考えているところです。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、現在この「“もったいない”推進店」、１３４店舗と確認をしておりますが、目標１５０店舗までの見通しをお聞かせください。新しく庁舎の食堂の事業者が変わりましたが、ここの食堂もしっかりもったいない推進店の一員としてほしいと求めましたが、いかがか尋ねました。","respondent":"小林環境課長","answer":"引き続き２０２０年という目標感は持っているところですが、それ以降も引き続き継続して行ってまいりたいと考えているところです。しっかり１５０店舗達成できるように進めてまいりたいと思っているところです。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"本年３月の予特でも、この環境未来館でフードドライブの常設を要望いたしましたが、今後の展開を判断していくとの答弁にとどまっております。実践できるようお願いをいたしますが、現段階でのこのフードドライブの常設に関してはどのようにお考えか、お伺いをいたします。","respondent":"小林環境課長","answer":"フードドライブですが、昨年以上に集まったところで非常に関心が高まりつつあるというところは認識しています。その中身、手法につきましては、今委員からご紹介ありました週１回の開催を含めて、今後も引き続き検討を深めてまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"２９１ページの商店街振興事業より、商店街支援と買い物支援に関連して移動支援としてのコミュニティバスについても伺いたいと思います。品川区では、店舗が減り、高齢者が買い物をするのが困難な地域について、その調査や把握はどのようになっているのか、伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"そうした部分につきましては、毎年々の商店街のイベント事業に対して補助事業をというようなお話し合いなどがあります。各商店街の会長さんなどに直接やり取りする場合と、活動状況を一般的な部分も把握しているというようなことで対応しているという状況です。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、商店が減り、商店街の姿そのものが大きく変わっている地域を品川区はどのように調査、把握をしているのかと伺いました。商店への支援について、品川区はどのような手立てを考えているのか、伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"こういうところに地域インフラとしての区の取り組みを、その商店街のフィールドで行う意味合いというのはそこにあるだろうと考えています。こうしたエリアといいますか面的な視点で、商店街振興施策も一つ考えていく余地はあるかと感じているところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、近所で買い物をしたり、毎日の生活をするという意味では近くが不便だという話もよく伺います。今バス路線の検討も始まっておりますが、こうした視点でも検討してほしいと求めましたが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"コミュニティバスのご質問をいただきましたが、現在コミュニティバスにつきましては導入に向けて協議会を立ち上げ、検討を開始したところです。今後この分析の検討を含めて第２回、第３回で具体的な地域、ルートについてお示ししながら検討を進めていくという状況です。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう要素もコミュニティバス路線の検討の中に入れてほしいと求めましたので、改めて伺いたいと思います。買い物の移動支援としてのコミュニティバス路線を検討の要素として入れてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今いただきました買い物が不便だというところ、これは定量的に示すというのはなかなかデータ上分析することは難しいと思います。逆を言いますと、しっかり皆さんが使っていただけるようなバスルートに向けた検討をしていけるかというところで、しっかり検討していきたいです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして２７９ページ、そして時間があれば２９５ページ、プレミアム付区内共通商品券発行助成についてお伺いをいたします。しながわ健康プラン２１が策定から５年目を迎えまして、取り組み、そして今後の意気込みを説明を求めました。","respondent":"高山健康課長","answer":"そして食を通じた健康づくりを推進するといったところの取り組みが、新たな後期５年に向けて施策を組み立ててまいりたいと考えております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"意見","question":"しながわ巡り」というのを広報広聴課でつくられているのですが、私は２つともインストールしたのですけれども、まずウォーキングマップと「わ！しながわ巡り」、これに似たような項目というか使い方があるのですが、その違いについてお知らせくださいとの意見を述べました。","respondent":"高山健康課長","answer":"「私の散歩道」との連携も図っておりまして、そうした楽しみながらまちを歩くことで、知らぬ間に歩数を稼げるといった相乗効果を狙うものです。で、広報広聴課のほうで実施しているアプリにつきましては、ないしは両方ともご使用いただくといった選択もあろうかと思います。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"ウォーキングイベントが平成２８年、イベントが２０１６年の１回きりになっておりますし、これはどういうことなのかということを感じております。これは一本化したらいかがかと考えているのですが、その点、区のお考えはいかがか尋ねました。","respondent":"高山健康課長","answer":"イベント化、さまざまなそうしたイベントに捉われずに区民が継続的にウォーキングなどに取り組めるような仕組み、事業については。予防接種アプリとか、統合みたいなものはなかなか難しい部分もありますので、当面はこのような形で進めさせていただければと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。こういう活用方法についての解説や解説動画というのをぜひ配信していただきたいと考えております、それについてどうお考えか尋ねました。","respondent":"高山健康課長","answer":"アプリを大変大事に思ってくださるといったご意見かと思います。ＱＲコードなどでこうしたダウンロードがより一層進むような形で、このアプリが活用されるように努めてまいります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"せっかく税投入をしているのですから、まさに情報発信の改革、周知の改革というのをぜひ行っていただきたいと考えております。ぜひやっていただきたいと考えているのですが、そうしたインターネットの活用をしての講演会の公開について、いかがお考えなのか尋ねました。","respondent":"高山健康課長","answer":"一つの新しい情報発信の手法としてインターネットというのは無視できない存在ではあります。どのような形が身近に健康づくりを考える上で、引き続き研究した上で、映像などの情報発信につきましては工夫してまいります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"４０歳代以降の方はどういう食生活をしたらいいのかというのを知りたいので、ぜひ４０歳代以上の情報も載せていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"高山健康課長","answer":"そうしたいわゆる多世代にわたります食に関する情報発信については、今後も拡充に努めてまいりたいと考えております。健康プランの見直しの中でも、その点の着眼点を外さないように、しっかりと見直しを図ってまいりたいと考えております。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"消費生活教室なども一生懸命やられているのですが、見ますと参加人数が１６人だとか、人数が少ないのが見受けられます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"２８３ページの同じく３項１目清掃費のリユース（再利用・再生）促進事業について伺います。この品川子育てストーリー、産後すぐのサポートについても的確な記載がされるべきと考えますが、見解を伺います。","respondent":"仁平品川保健センター所長","answer":"そういう提出のない方に対しても助産師から直接ご家庭に電話等で退院後の状況等を確認して支援に当たっているところですし、退院してきた場合には。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"私が伺ったのは、情報提供なのですけれども、産前についての情報提供は重要と考えているとご答弁をいただいています。重要と考えていらっしゃるのであったらどのような工夫がされているのか、その辺について伺ったのですが、改めて伺います。","respondent":"仁平品川保健センター所長","answer":"こちらに参加していただくことによって、出産から産後に向けた保健指導等といいますか、母親になるべく学んでいただいているところです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"そこから自然エネルギーを購入して区内の学校や公共施設で使うことに取り組めないかという提案をしたところ。品川区も踏み込んだ政策をとるべき時期と考えますが、現在の状況を伺いますとの意見を述べました。","respondent":"品川財政課長、小林環境課長","answer":"今回の成果報告書につきましては、それぞれの課の中とか区の重点施策とか、そういうところを中心として３６事業挙げしています。その辺の判断の中から、少し該当する事業については入っていなかったというような結果となっているです。予算書上というところでは、平成３０年度におきましても、発生抑制の観点から使い捨てプラスチックを極力使用しない取り組みを続けてきたところです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"見解を伺います。啓発にリデュース促進事業が必要と思うのですけれども、リデュース促進事業についての啓発の実績があれば、それを伺いたいと思います。","respondent":"小林環境課長、工藤品川区清掃事務所長","answer":"次年度予算の編成におきましても、ワンウエイプラスチック、使い捨てプラスチックを極力使用しないというところで取り組みが進められるです。引き続きしっかり各課と共有しながら、この取り組みを進めてまいりたいと考えているところで… 発生抑制が一番に取り組むべきものということで、間口からの削減という部分を強調してお伝えしております。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"第９期の区長からの諮問への答申をまとめるときにも、その答申案を読むと、リデュースの視点を強く盛り込むべきと意見を申しました。もっと庁内で連携をとりながらリデュースを中心に考えるべきだと思いますが、見解を伺います。","respondent":"工藤品川区清掃事務所長","answer":"発生抑制へのさらなる取り組みをです。今後も発生抑制に向けて啓発の強化、区民の理解を図り、区民の生活様式の変容という部分を図るよう努めてまいりたいと考えています。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"啓発はどんどん進めてほしいと求めました。そういうことを具体的に始めるべきではないかと思うのですけれども、次年度に向けてその辺の見解があればもう一度伺いたいと思います。","respondent":"小林環境課長","answer":"ペットボトルにつきましても、例えば今現在紙でできたカートカンと言われているような新たな製品も開発が進んでいるです。引き続きそういった品物の導入も含めて、関係課と調整し合いながらしっかりと見える形で啓発を進めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"やはり実際に自分たちも取り組んでみせるということでの啓発はすごく大きいと思います。ぜひ前向きに検討していただきますようお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問","question":"庁内での緊急協議会と理事者・担当者を一堂に集めた会議は行われましたでしょうか。区民に重要な情報を発信する必要がある区議会議員にすらこの情報が伝わっていないということはなぜなのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"１０月２日の時点で問題が起きてすぐに区長、幹部にお知らせするということで、まず私どもがお知らせしました。庁内全体での情報共有あるいは緊急対策会議については、現在のところでは開催してございません。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"では、重要性として低いので、区議会議員に連絡が来てなかったということなのでしょうか。もう一度ご答弁をお願いします。","respondent":"鷹箸保健予防課長","answer":"そのために区議会議員の皆様にそれだけお知らせするということでしょうか。ホームページの掲載でまずは区民の方に第１報を差し上げた、その区民の方というのは区議会議員の方も含めてという意味で私どもは考えております。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問","question":"今回ツイッターで情報発信がされなかった状況について広報広聴課の課長は把握なさっていましたでしょうか。こちらの情報を発信するべきというふうに思っていましたか尋ねました。","respondent":"木村広報広聴課長","answer":"ホームページの記載につきましては把握をしておったところです。それから、ツイッターその他で発信をしていないというところも把握しておりました。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"ただ、同じように、区のほうに問い合わせ等ありましたでしょうか。問い合わせの件数と問い合わせの内容をお尋ねします。","respondent":"鷹箸保健予防課長","answer":"区内の医療機関からは、会社が全額出してくれるということで抗体検査を受けたいという事案はあるのかといったお問い合わせはありました。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"同じ敷地内にあるところでも感染する可能性があるのかどうか。例えば品川シーサイド、あちらのビル、そこの敷地内での集団感染というのは特に全く考えていませんか尋ねました。","respondent":"鷹箸保健予防課長","answer":"はエレベーターの中ですとかトイレとか、そういったところにも張り紙を既にしていただいているのですが、それ以外のビルに対して今までのところ保健所の方から情報発信したことはございません。","id":"exchange-044"},{"speaker":"くにば委員","kind":"質問・要望","question":"引き続きまして、緊急性が高い情報だったのでこちらについての質疑をしたのですけれども、残り、粗大ごみの事業について端的に伺いたいと思います。現在、品川区で粗大ごみはおおむね回収までに２週間ぐらいかかるのですけれども、そちらに関して対応策はいかがお考えか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"それで、今年度新たに１台を追加したものです。申し込みから回収までの期間等、十分に把握しまして、区民の粗大ごみの回収を区民サービスの観点から支障がないように円滑に進めてまいります。","id":"exchange-045"},{"speaker":"せお委員","kind":"質問","question":"２６９ページ、不妊治療助成事業についてお聞きします。平成３０年度決算が３,７００万円なのですが、平成３０年度から新しく助成金が増えたのに支出が減っているというのはどのような理由なのか尋ねました。","respondent":"高山健康課長","answer":"開始した初年度ということで、予定する件数には達しませんでしたけれども、今年度は基本的に８月末現在で順調に申請が伸びております。こうした件数の申請の推移について見ていきたいと考えております。","id":"exchange-046"},{"speaker":"せお委員","kind":"質問・要望","question":"そこで質問いたします。特に顕微授精を行った方、若い世代において助成額を上げていただきたいと要望いたしますが、品川区としてはどのようにお考えか尋ねました。","respondent":"高山健康課長","answer":"これに上乗せする形で、区においては５万円という金額を上限として設定しています。少しでも利用される方の負担が減ればと考えていますが、制度発足から日も浅いのですので、金額の増額については慎重に検討してまいります。","id":"exchange-047"},{"speaker":"せお委員","kind":"提案","question":"全ての若者に知ってほしいとこちらにも書いてあるのですけれども、本当に全ての若者に読んでいただきたいパンフレットになっています。お聞きしたいのですが、今ご提案したような相談窓口やコミュニティーなど、サービスを今後品川区は行っていくご予定はありますか尋ねました。","respondent":"高山健康課長","answer":"今後、治療を受けようとする方々へのさまざまな支援というお尋ねかと思います。なかなか直ちにというのは難しいかと考えておりますが、どのような視点が適切かということは引き続き検討してまいりたいと考えております。","id":"exchange-048"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区内の大学に置いて大学生に見てもらうとか、そういった検討も必要かと思いますので、そういったことを要望したいと思います。さらに、現状よりもさらに連携できて多くの課題解決になると思うのですが、ネウボラを妊娠前からにすることについてご見解を説明を求めました。","respondent":"仁平品川保健センター所長","answer":"現在、保健センターのほうで妊娠されてから出産、育児に向けて不安なく地域生活がおくれるようにということで支援をしています。現在、具体的には事業を行っていませんけれども、その辺、助産師関係を活用した講座とかができないかどうか考えてまいりたいと考えています。","id":"exchange-049"},{"speaker":"小芝委員","kind":"質問","question":"こちらは隣の次のページの２７１ページにも受診数が記載されておりますが、これまでの受診率の推移と区のご所見をお伺いします。昨年から胃がんの検診で内視鏡検査が導入されたことを踏まえまして、こちらのほうのご所見もお伺いします。","respondent":"高山健康課長","answer":"肺がんにつきましては、そうした点を踏まえまして、今年度もがん計画をつくる過程で受診率の向上などについても検討してまいりたいと考えております。","id":"exchange-050"},{"speaker":"小芝委員","kind":"質問","question":"がん検診ですが、国の指針で定める５つのがん検診以外に前立腺がん、そして喉頭がんの検診が行われておりますが、こちらはどのような経緯でこの２つの検診を対象にしてきたのか尋ねました。","respondent":"高山健康課長","answer":"前立腺がんにつきましては、平成１８年度から導入されておりまして、喉頭がんについては平成２０年度といった時期です。平成２０年度、特に男性では５０代より急激に増加するということである一方、当時として導入を判断したものです。","id":"exchange-051"},{"speaker":"小芝委員","kind":"質問","question":"国立がん研究センターの予測では、罹患者数では喉頭がんよりも５倍多い、おおよそ年間で約２万３,０００人程度の数が予測されております。そこで、口腔がん検診に対するこれまでの品川区の取り組みについてお聞かせ願えますか尋ねました。","respondent":"高山健康課長","answer":"区の取り組みという点ですと、先ほど申しました７つのがん以外には、区の検診としては実施しているものはございません。そうした支援の状況などは、引き続き情報収集してまいりたいと考えております。","id":"exchange-052"},{"speaker":"小芝委員","kind":"質問","question":"ちなみに、区内の歯科医院で口腔がん検診を実施している歯科医院は大体どのくらいあるかというのはわかりますか尋ねました。","respondent":"高山健康課長","answer":"区内の歯科クリニックでの対応状況という点につきましては、区では残念ながら把握していない状況です。近隣の港区などでは数カ所あるということは承知しております。","id":"exchange-053"},{"speaker":"小芝委員","kind":"質問","question":"この口腔がんの検診をされている歯科医院をぜひお調べいただきまして、その上で、成人歯科健診が今行われています。その際、例えば受診券のところに口腔がんの検診をされている歯科医院の一覧表を添えるのもいいと思いますが、いかがお考えか尋ねました。","respondent":"高山健康課長","answer":"先ほど申しました歯科医師会の取り組みの中で、来月１１月にもそのようないわゆる集団の検診の機会を設けるというようなお話も伺っております。これを健診のご案内に載せるのが現段階で時期尚早か、あるいは適当かどうかというのは慎重に判断させていただきたいと考えております。","id":"exchange-054"},{"speaker":"小芝委員","kind":"質問","question":"平成３０年度ではカラスの巣の排除はどの程度あったのでしょうか。この巣の排除が集中する時期というのはあるのか尋ねました。","respondent":"小林環境課長","answer":"巣の撤去の件数ですが、平成３０年度、区全体といたしましては約１７０件程度あったとカウントしたところです。","id":"exchange-055"},{"speaker":"小芝委員","kind":"質問","question":"そういったものは夜行性ですのでなかなか対策が難しいと思います。区もこれまで対策されてきたと思いますが、ご所見をお伺いできればと思います。","respondent":"小林環境課長","answer":"アライグマ、ハクビシンにつきましても、引き続き箱ワナの設置等を含めて目撃情報を勘案しながら努力してまいりたいと考えております。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"関連してですけれども、昨年の第２回定例会の一般質問で、品川区版のがん対策推進計画の策定というものを要望させていただきました。策定委員会を立ち上げるというお話を伺っていたのですが、ここは質問なのですけれども、これからの計画策定までのスケジュールを説明を求めました。","respondent":"高山健康課長","answer":"したがいまして、今後ですが、パブリックコメントなどを予定しておりまして、年度内に完成を予定するものです。要旨なのか全文なのか、その辺のところは考えしていますが、その作成の経過も表にしていきたいと考えております。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"確認","question":"長計の素案を読みましたら、今、パブコメをやっていますけれども、この中にも位置づけられているということも確認をさせていただきました。この点について、今策定中であるがん対策推進計画の骨組みというかコンセプトというものが、どのようなことをイメージすればいいのか説明を求めました。","respondent":"高山健康課長","answer":"そして、段階的には、科学的根拠に基づく検診の実施、これには精度管理を含むものです。がんになった後の支援ということで、患者やその家族への支援といったものを、できるだけ品川らしさを出していきたいと考えております。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"課題はあるということですから、できないにしても、計画の中にはしっかり位置づけをしていただきたいということが一つです。しっかりと民間の機関と連携をしていくということも、一つそういう形もあるのではないかと思うのですが、これについてのご意見を伺いたいと思います。","respondent":"高山健康課長","answer":"１点目の目標値という点におきましては、５年間でこれを達成できるかどうかというところをしっかりと見ていきたいと考えております。マギーズ東京も含めた民間との連携強化、現在は江東区との連携というのは聞いているのですけれども、今後取り組んでまいりたいと考えております。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"続きまして、がん教育のことも伺わせていただきます。お考えになっていらっしゃるのか、がん教育というのは義務教育に位置づけられましたけれども、そこについて端的に教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"なお、学習指導要領が完全に中学校版が実施される令和３年度より、全中学校でのがん教育において医師等を活用するという目標を持っております。品川区はそれに先んじて、既に今年度５校行いまして、令和３年度を待たずに、もっと拡充していきたいと考えております。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう少し掘り下げたいのですが、時間がないので、環境のところで伺いたいと思います。これを公募なり何なりして、誰もが行きやすいような愛称をぜひつけてほしいと求めましたが、いかがか尋ねました。","respondent":"小林環境課長","answer":"子ども向けのＳＤＧｓに関する講座を開く予定にしておりますので、そういった動向を踏まえながら進めてまいりたいと考えています。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"既に我が党の鈴木ひろ子議員が２定の一般質問にて要望したところですが、障害者手帳を持たれている方への助成制度だけで十分だというものでした。聴力レベル何デシベル以上の方、あるいはわかりやすく言えば、どの程度の日常会話が理解できるような方なのでしょうか、お伺いいたします。","respondent":"松山障害者福祉課長","answer":"聴覚障害の程度ということのお話ですけれども、両方の耳の聴力レベルがそれぞれ、２級の方で１００デシベル以上の者という形で、２級から６級まです。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"もう一つお伺いします。ＷＨＯ（世界保健機関）では、何デシベル以上に補聴器をつけるということが奨励されているか尋ねました。","respondent":"松山障害者福祉課長","answer":"申しわけありません、存じておりません。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問","question":"そこでさらに伺います。お伺いいたします。","respondent":"松山障害者福祉課長","answer":"手帳の等級は身体障害者福祉法の施行規則ということで、国で客観的な基準に基づいて行っております。補聴器のみの解決でいくのか、それとも客観的な基準が必要なのかなど、さまざまな面から研究していかなければならないと考えております。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問・要望","question":"改めて、高齢者への定期的な聴力検査をすべきだと考えますけれども、いかがでしょうか。お伺いいたします。","respondent":"高山健康課長","answer":"高齢者に対する定期的な聴力検査の実施の必要性というご質問かと思いますが、現在のところ、実施をする考えはございません。","id":"exchange-065"},{"speaker":"おくの委員","kind":"質問・要望","question":"必要性は、今、るる述べてきたところでおわかりだと思います。導入を再検討されることを求めて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"松本委員","kind":"質問","question":"本日は決算書２８３ページの一般廃棄物処理業許可事務費に関連して、先日もお伺いした遺品整理について伺いたいと思います。許可の種類としては、事業系・家庭系という区分けは基本的にはないという理解なのですけれども、それでよろしいか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"一般廃棄物処理業の許可につきましてのお尋ねです。許可事業者に関しましては、特別区の場合には事業系一般廃棄物の処理という考え方です。","id":"exchange-067"},{"speaker":"松本委員","kind":"質問","question":"では、まちなかで軽トラックとかで不用品の回収をやっている業者があろうかと思いますけれども、ああいった業者というのは、どのような許可が必要になるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"どのようなものを積んでいるかというのはわかりませんが、基本的には許可を受けた会社につきましては、車両に許可番号等が記されております。それ以外の車につきましても、一概に違法とは言えませんで、例えば古物、有価物等を運搬している実態があろうかと考えています。","id":"exchange-068"},{"speaker":"松本委員","kind":"質問","question":"ここは明確にしておきたいのですけれども、有価物ではなくて廃棄物の場合は、やはり一般廃棄物収集運搬業の許可が必要という理解でよろしいか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"廃棄物に関しましては、許可が必要になってまいります。","id":"exchange-069"},{"speaker":"松本委員","kind":"質問","question":"先ほどの２３区、特別区としては、こことの関係というのはどうなるのですか。このあたりの関係性というのはどうなるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"先ほど申し上げましたように、許可事業者につきましては、あくまでも事業系ごみです。家庭から廃棄されるごみにつきましては、市区町村の責任で、自治体で対応するです。","id":"exchange-070"},{"speaker":"松本委員","kind":"質問","question":"結構ここは法律上、難しいところもあって、おそらく事業系で許可を受けた人たちが家庭ごみを回収しているという事例はあるのではないかと思います。この方針によってやらないと書かれておりますので、基本的には新規の一般廃棄物収集運搬業の許可は、現在はおりないという理解でよろしいか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"一般廃棄物の処理の許可につきましては、２３区の中で共通で試験を実施しております。許可がおりないというわけではなくて、年度によって、需給バランスの中で試験を実施するです。","id":"exchange-071"},{"speaker":"松本委員","kind":"質問","question":"ここ５年ぐらいでいいですけれども、５年ぐらいで許可がおりた業者というのはありますか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"近年の状況ですけれども、ここ５年ということで、平成２６年度が合格が２事業所、平成２７年度が２事業所、平成２８、２９、３０年度は試験を実施しましたが、合格事業者は出ていないという状況です。","id":"exchange-072"},{"speaker":"松本委員","kind":"質問","question":"遺品整理について伺っていきたいのですけれども、廃棄物の運搬をワンストップで行う遺品整理業に対する需要が高まっていると言われています。そういうのを２週間も待たずにワンストップでやってくれるという業者、行政としては認識されているのでしょうか、お願いします。","respondent":"工藤品川区清掃事務所長","answer":"近年、高齢化の中で、そのような遺品整理その他の家財処分等々の需要は高まっていると認識しております。","id":"exchange-073"},{"speaker":"松本委員","kind":"質問","question":"もっと問題なのは、古物商許可事業者が一旦買い取る形にして、それを自社の事業ごみとして廃棄しているケースがあるという話も伺うのです。これは法律が想定しているのかなというところで、これが合法なのかというところをお伺いできればと思います。","respondent":"工藤品川区清掃事務所長","answer":"厳密に申し上げますと、買い取ったものを廃棄物として処分する場合には、許可が必要になってあります。","id":"exchange-074"},{"speaker":"松本委員","kind":"質問・要望","question":"遺品整理に関して言うと、福岡市が７月に、遺品整理に限定した一般廃棄物収集運搬の許可を２社に認めたという話があります。これはかなり細かい条件を定めて、ぜひとも品川区もいろいろ検討していただければと思って、要望として申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"松澤委員","kind":"質問・要望","question":"人生１００年時代に向けて健康長寿を実現するためには、栄養、運動、社会参加を促す各種施設の充実が求められております。設備改修等の工事として約６,７００万円の金額がありますが、この概要についても説明を求めました。","respondent":"高山健康課長","answer":"１点目の健康センターの設置の目的です。施設を安定的に運営していく上では、こうした金額は毎年一定程度負担していく必要があるものと考えております。","id":"exchange-076"},{"speaker":"松澤委員","kind":"質問","question":"フリー利用、コース型など、利用実績は平成３０年では品川・荏原の両健康センターで年間３０万人以上になると推計しております。そこで、健康センターを運営していく上での今後の課題について、お伺いいたします。","respondent":"高山健康課長","answer":"年間利用者の３０万人というのは、ほぼ上限に近い状況です。安全な運用の面から、入場をお待ちいただくなど、現場における工夫なども今後必要になってくると考えております。","id":"exchange-077"},{"speaker":"松澤委員","kind":"意見","question":"４００円、５００円と利用金額に差をつけることで、荏原地域の皆さんも大変喜ばれると考えています。さまざまな検討が必要とは思いますが、区民のさらなる健康推進に向けて、今後の施設のあり方についてお考えを説明を求めました。","respondent":"高山健康課長","answer":"委員ご紹介のとおり、荏原は品川の大体５分の１程度ということで、これ以上の施設内での拡張というのはなかなか難しい現状があります。施設の改修、そして公共施設の再配置などさまざまな検討の中で、こうしたことは課題提起していきたいと考えております。","id":"exchange-078"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、健康づくり支援事業の中で、公衆浴場支援調査委託についてお伺いいたします。そこで、まず、この公衆浴場支援調査委託の概要についてお教えください。","respondent":"高山健康課長","answer":"区内の公衆浴場が減少する中、区としてさまざまな支援策をこれまで講じてまいりましたが、抜本的な解決というのはなかなか難しい状況にございました。そして浴場経営者からのヒアリング、調査分析など、各種活性化に関するさまざまなご提案をいただいたところです。","id":"exchange-079"},{"speaker":"松澤委員","kind":"提案","question":"見守り支援員銭湯派遣事業というのが平成３０年８月にありまして、これは、銭湯に見守り支援員を置くといった事業でありました。こういう関連を持たせる事業を一つの提案といたしまして、これまでの公衆浴場に対して、今後ともさらに支援の輪を広げていただけたら幸いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"質問","question":"ページが前後しますが２７７ページ、２７５ページ、２８７ページの景況調査委託費等について質問します。決算額を引くと約３３５万円の不足額があり、この２年で約６００万円の縮小があるように思いますが、成果とともに教えていただけたらと思います。","respondent":"山崎商業・ものづくり課長","answer":"平成３０年度につきましては、はがきによる架空請求の部分が急増しているということが、一つ特徴かなです。解除できた金額というところでは、これは内々の数字ですけれども、５,０００万円ほどの成果を出していると捉えているところです。","id":"exchange-081"},{"speaker":"湯澤委員","kind":"質問・要望","question":"録音機を余すことなく区民へ貸与されますよう、地域活動課とともに商業・ものづくり課でも努めていただきたいと考えています。まだ消費者被害に関心の少ない新成人に対し、関心を持つような政策が必要であるかと思いますが、区の見解を聞かせてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"消費者センターでも相談を受けて、所管におつなぎしながら、配付希望者に適切につなぐということをやらせていただいております。その辺は力を入れてやってまいりたいということと、さまざまな啓発も工夫の上、しっかり対応してまいりたいということで考えるところです。","id":"exchange-082"},{"speaker":"湯澤委員","kind":"質問・要望","question":"いよいよ来年が１０年目になりますが、目標が達成できそうでありますでしょうか。成果と、また今後の課題があれば教えてほしいと求めました。","respondent":"小林環境課長","answer":"こちらの計画では、２０２７年度までに２０１３年度比で約３３％の温室効果ガス削減というところを目標に、進めているところです。計画に向けて、今、着実に削減が進んでいると捉えているところです。","id":"exchange-083"},{"speaker":"湯澤委員","kind":"質問","question":"それに基づく職員の指導や、都や国との調査、報告といった連携はできているのでしょうか。今回はできていたか、そちらも教えてほしいと求めました。","respondent":"小林環境課長","answer":"このヒアリの発見の前というか、そういったところがない中でも、東京都あるいは国と連携を図って連絡会議を継続的に行っているところです。今後も引き続きこういった会議を開きながら、都と国と連携しながら対策を進めていくです。","id":"exchange-084"},{"speaker":"湯澤委員","kind":"質問","question":"環境課ではそういったマニュアルのようなものがあって、職員の皆さん等には周知徹底されているのか尋ねました。","respondent":"小林環境課長","answer":"マニュアルですが、これも国や都がつくりましたヒアリの見分け方とか、どういったところに生息しやすいかというところがマニュアルとして整備されているところでございまして、そういったものを用いながら、職員同士の情報共有あるいは研修を進めているです。","id":"exchange-085"},{"speaker":"湯澤委員","kind":"質問・要望","question":"危険が伴うお仕事だと思いますけれども、ぜひ発見時には迅速かつ的確な対応をお願いしたいと思います。せめて白い雲にしていただくとか、そういう対策をしていただければと、要望として伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした決定に抗議をして撤回を求めたいと思いますけれども、品川区が公の場で計画に発言する場が、７月３０日の関係区市連絡会でした。伺いますけれども、なぜあの場で区議会決議と同様に、区も容認できないと表明しなかったのか、紹介にとどめたのはなぜか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２０１５年の国から当計画が示されて以降、騒音環境の軽減の取り組み、さらには区民への丁寧な周知・説明を継続して求めてまいりました。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを、再三の全会派からの要請があったにもかかわらず、区が容認できないという表明を行わなかったのはなぜかということを聞いています。当日発言した桑村副区長に、ぜひその辺を説明してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"重ねてのご答弁になりますが、３月の全会一致の前提が、区民不安の払拭につながる取り組みがまだされていないです。事業の実施は事業主体である国の判断、責任において実施されるです。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ表明しないのか、私は、何か容認できないと表明できない理由でもあったのかと疑いたくもなります。区議会決議というのを軽く見ているといいますか、勝手に解釈するのはやめていただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"事業主体である国が、しっかり責任を持って進めていただく。その中で我々が、区がすべきことは、区民不安の払拭につながる取り組みを、継続してしっかり国に伝えていくです。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはどうなのですか。伺いますけれども、桑村副区長はなぜ「固定化することがないよう」などと、重大な点だと思いますので伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"固定化することがないような取り組みは、区民不安の払拭に向けた取り組みと並行して、しっかり検討していただきたいと。それは国が説明会の場でもかねがね、継続して行っていくというところは発言してございましたので。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、この決定的な場面で、７月３０日の関係連絡会で、固定化することがないようという意見に、改めて向こうから回答がありました。どうでしょうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"具体化協議会の中でも国の航空局長が、今後の決定時期については国で検討していくというところを伝えてあります。したがいまして、そういう案内通知もございません。","id":"exchange-091"},{"speaker":"安藤委員","kind":"質問","question":"なぜ飛ばしてもいいですよととれるような発言をしたのか、一緒にゴーサインを出したという責任を、品川区は感じていないのですか。これを改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"５月の区議会、常任委員会でも区としての考えをお示しし、国にしていくというところでご報告差し上げたところです。決定に際しての責任は、当然ながら国が持つという内容です。","id":"exchange-092"},{"speaker":"安藤委員","kind":"質問・要望","question":"都が新ルートの推進を要望する意見案を出しているのに、容認できないと決議を挙げた品川区議会に背信する行為という認識はないのでしょうか。なぜ意見なしと、それは背信だと思いますけれども、いかがでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"それは東京の副知事としての発言ですので、区が意見を差し挟むというところではございません。連絡会で整理した品川区の意見という形で、固定化しない意見というところがしっかり入ってございましたので、意見なしという形で返したところです。","id":"exchange-093"},{"speaker":"あべ委員","kind":"質問","question":"２８９ページの就業支援費、２７７ページの環境調査測定費に関連して、羽田新ルート計画についてお伺いしたいと思います。母子保健指導なのですけれども、母子手帳の経費と１冊当たりの価格を説明を求めました。","respondent":"高山健康課長","answer":"母子手帳は１冊当たり１０８円の単価でございまして、毎年５,０００冊を印刷しています。","id":"exchange-094"},{"speaker":"あべ委員","kind":"質問","question":"父親の記入欄を設けていくことで、父親もともに健康観察、健康管理の主体としての意識を涵養するということはいかがでしょうか。いかがか尋ねました。","respondent":"高山健康課長","answer":"そのような２段構成となっているところですが、多くの自治体では大体、統一的な様式を一括して購入して使っているという現状かと思います。","id":"exchange-095"},{"speaker":"あべ委員","kind":"質問","question":"次に、就業支援なのですけれども、多様な雇用の創出という視点からお伺いします。障害者雇用義務のない４５.５人以下の企業というのがほとんどを占めると思いますけれども、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"２０名以下の小規模事業所が８５％以上ですので、法的な義務づけという方向性では、働きかけというのはまだまだ進んでいない状況ではあります。多様な人材の雇用という意味では、経営者の方に啓発事業などを通じて訴えているという状況です。","id":"exchange-096"},{"speaker":"あべ委員","kind":"質問","question":"ショートタイムワーク制度というのを構想し、実際に今、川崎市では既に小規模企業約６０社に広がっております。中小零細企業の人手不足解消と、多様な雇用の創出の２つの課題への対応策として、ぜひ品川区でも検討されてはと思いますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"２０名以下の事業所が約８５％ということは、人１人を雇用するというのは、すごく判断が必要なところです。そうしたことを活用しながら、挑戦といいますか、検討してまいりたいと思っているところです。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問・要望","question":"羽田空港についてなのですけれども、先ほどから出ております、ルートを固定化することのないよう求めていく。これは、品川区として本気で取り組んでいくつもりがあるのかどうか、改めてお伺いします。","respondent":"鈴木都市計画課長","answer":"国からは、騒音環境の軽減の観点から、引き続き検討していくという回答もいただいてあります。区としては国としっかりと調整をして、協議をしていきたい、要望していきたいです。","id":"exchange-098"},{"speaker":"あべ委員","kind":"質問","question":"私も今回の本会議一般質問の中で、きちんと伝えることによって、今の方向をぜひ見直してほしいと。その意味では、飛び始める前からそうした収集をすべきだと思いますが、改めてお伺いします。","respondent":"鈴木都市計画課長","answer":"第一には、調査等については国にしっかりやっていただくというところで、区民の声もあわせて、しっかり国に届けていきたいです。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２６７ページ、妊婦・産婦歯科健診、２６９ページ、健康診査費、２７３ページ、こころの健康づくり事業をお伺いしたいと思います。本当に大事であるということがわかりますけれども、区の認識としては、こういう点はどのように捉えておりますか尋ねました。","respondent":"高山健康課長","answer":"妊娠期、それから産後の母親の口腔内の環境変化という点でのお尋ねかと思います。区ではご紹介のとおり、そして産後に１回の歯科の健康診査の機会を設けておりまして、口腔内の変化に早く気づいていただきたいと考えているものです。","id":"exchange-100"},{"speaker":"こんの委員","kind":"提案","question":"それと同時に、あえて口腔内のケアをきちんとするというところをきちんと捉えて、歯のクリーニングということが大事であると捉えております。","respondent":"高山健康課長","answer":"継続しているものでございまして、これも一つの魅力として、受診率向上に寄与すればということで続けているものです。で、治療につなげていっていただきたいという趣旨のものでございまして、導入については現状のところは考えていないです。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"５０歳以上の女性が骨折する確率は３人に１人、男性では５人に１人であり、骨折後に歩行状態まで回復しない割合は４０％と伺いました。１年以内の死亡率は２０％にもなるとお聞きし、骨粗しょう症への対策は喫緊の課題と捉えておりますが、区のご見解を説明を求めました。","respondent":"高山健康課長","answer":"骨粗しょう症検診を実施していたものではありますが、その後、平成１５年度に本事業を廃止したものです。さらに検討が必要になるものと考えておりますので、運動習慣を身につけるといったものを用いて、健康長寿を実現していくべきものと考えております。","id":"exchange-102"},{"speaker":"こんの委員","kind":"意見","question":"今現在、そのようなご説明をしてくださった状況で、対応もしてくださっていることがわかりました。どれぐらい自分の体の骨がどうなっているのかというところは、検査の必要性を感じますけれども、さらにご答弁があればお願いしたいと思いますとの意見を述べました。","respondent":"高山健康課長","answer":"注意すべき血圧だとか、その他健康にかかわるさまざまな関心を持つということは、大変重要だと考えております。これまでも健康課としても続けてまいりましたので、ご自身の健康はご自身で守るといったことで、取り組みを進めていただければと考えております。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"病状不安定な精神疾患の患者や措置入院の患者などに対し、精神保健相談員による個別支援などを行う事業であると伺い、大変に期待をしております。保健師の今の人数といった体制は大丈夫でしょうかということを、現状はどういった状況でしょうか、お知らせください。","respondent":"榎本荏原保健センター所長","answer":"メンタルチームサポート事業を開始いたしまして、保健師が連携しまして、事業を進めているところです。保健師とほかの職種と連携をしながら、さまざまな事業の充実を今、進めているです。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうか必要な場所に必要な人を配置していただく行財政改革を、品川区としては行っていただきたい。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問・要望","question":"まさか自分がこころの病にかかっているとは、誰が感じるのでしょうか。夫婦だからこそわかる部分というのでしょうか、旦那からの声というものが一番多いのではないかと思いますけれども、いかがか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"保健センターにおいてのこころの健康づくりのご相談の中におきましても、ご夫婦の間でのご相談も入ってきております。離婚にかかわるような、身近な相談相手であり、また家族関係の変化によってはゆがみが生じてしまうということもあるという関係だと認識しております。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"早目の発見が何よりも大事でありますけれども、年間どれぐらいの相談件数があったり、また治療が行われているのでしょうか。そして、治療すれば多くの人々が完治をするのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"所内相談ですと１,４１１件、家庭訪問につきましては１,８３８件、電話相談は７,７４９件ということで、ご相談に応じている状況です。もしくは医療機関にかかって完治した方の割合というところにつきましては、医療機関にかかった後ですので、こちらではわかりかねるです。","id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"品川区においても、過去１０年間に自殺によって失われた命は約７００人弱ぐらいでしょうか、区内の交通事故死の約１０倍に当たるそうです。どんどん開発や研究が進んでいるのでしょうけれども、全ての人が快方へと向かうわけではないと思いますが、その辺はいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"国が示している基本施策に加え、品川区独自の重点施策などを設けて、今年度末までに品川区の地域に根差した自殺対策計画を策定する予定です。来年度以降は、今年度計画を策定します自殺対策計画に基づきまして、さまざまな事業展開に新たに取り組めたらと考えているところです。","id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたします。気になるところはどのようなところか、最後に説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"こころの相談窓口といたしまして、保健センターでは専門医の相談もありますが、保健師や心理職などによる直接的なご相談も応じております。","id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２６３ページ、２８０ページの中から何点か、２８９ページあたりからお聞きしたいと思います。この辺の大まかな状況を教えてほしいと求めましたので、お願いいたします。","respondent":"高山健康課長、工藤品川区清掃事務所長","answer":"こちらの区との連携という点でのお尋ねですが、都知事からの依頼に基づきまして、現在１４名の方に委員を務めていただいているものです。区の支援としましては、そうしたものの事務を事務局的に補助していくという形で… 人口が増えておりましても、１人当たりのごみ量というのが確実に減っておりますので、このような数字が出てあります。昨年がトンでいいますと１,４６９トン、今年が１,５９３トンということですので、わずかに増加しているです。","id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺を検討していただけないかどうか、まず１点、教えてください。来年の３月いっぱいで品川区として自由に使える状況にある中で、区の方向性が固まったのかどうか、その点を説明を求めました。","respondent":"高山健康課長、柏原企画調整課長","answer":"冒頭ご説明しましたように、東京都の事業に対する区としての協力ということで、これまでご期待に必ずしも応え切れなかった部分はあろうかと思います。他団体との連携とかにつきましては、どのような連携が望まれているかという点も含め… 来年の３月で用途制限が終わるという中で、今、全庁的なところでの活用の検討を行っているところです。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういうところが東京都の部分ですから、どこか対応する場所を見つけて、ぜひ区の中で処理をしてほしいと求めました。逆に区で処理した場合と、直送した場合というのは、金額的にどのような傾向になるのか、その辺を教えてほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"私ども清掃事務所といたしましても、この土地が別の活用を検討されているということで、粗大ごみの中継のあり方について、今、鋭意検討しています。中央防波堤に持ち込むのかという２つで、メリット・デメリットを洗い出し、検討しています。","id":"exchange-112"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この点については要望します。ですから、今の２３区間の傾向と、どうなっているか説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"２３区が進めておりまして、新しい考えで、今後この負担の公平制度をどうやって決めていくのかというのを議論している最中です。そういった議論にしっかり入りながら、２３区の中で全ての区が合意して、この制度が引き続き継続的にされるように考えているところです。","id":"exchange-113"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それと、お答えいただけるかどうかなのですけれども、先日、品川区の中小企業支援策のご案内というパンフレットを見させていただきました。先ほど零細企業が８５％というお話があった中で、零細部分に対しての支援がどうしてもしにくいし、との意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"小規模な企業が多くて、技術がたくさんあります。そうした区内企業間の取引マッチングなどの創出といった、具体的なことをしていければいいかなということで、努めてまいりたいと思うところです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"平成３４年ですから、令和４年になるのでしょうか、数値目標がいろいろ掲げられております。非常にその辺は報告を見ると、本当ですかと疑問視するのですが、いかがか尋ねました。","respondent":"高山健康課長、仁平品川保健センター所長、小林環境課長、山崎商業・ものづくり課長","answer":"１点目の数値の目標という点で申しますと、健康プラン２１の中におきまして、そうした指標・目標を定めているところです。… 心理士等がここにかかわっているのですけれども、保護者の方とのお話の中で、状況によっては療育機関へ紹介状を発行するような対応をしております。… 私からは、戸越で建設を予定しております環境学習施設についてのご質問にお答えいたします。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな経緯を含めて、将来に向けてのサポートという体制をとっていただく仕組みをつくっていただきたいと、要望したいと考えています。最後に口腔保健支援センター、もう一言お願いしたいと思います。","respondent":"高山健康課長","answer":"さまざまな支援という形で、保健センターと連携して……。","id":"exchange-116"},{"speaker":"石田（ち）委員","kind":"質問","question":"１室からでも旅館業が可能で、こうした無人のホテル・旅館が、この区内にどれだけあるのか伺いたいと思います。条例で施設内への常駐者を置くことと定めていますけれども、こうした区は２３区内でどれくらいあるのか把握されているでしょうか、伺います。","respondent":"鈴木生活衛生課長","answer":"１点目の、その後の届け出いただいたものに関しては、区内で１８軒のみということになっております。２３区で、墨田区、荒川区の５区と認識をしております。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問","question":"法改正後ということで、軒数が１８軒ということでしたけれども、無人で、要は常駐者なしで運営されているホテルや旅館は、１８軒ということでよろしいのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"基本的に、常駐する場合には、ＩＣＴ等の機器は必要ありませんので、ＩＣＴ等による受け付けをするというように変更届をいただいているものが、１８軒です。","id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"質問","question":"常駐者を置くこととしている区が１５区あるという中で、なぜ品川区は常駐しなくてもいい、無人で運営できるということにしてしまったのでしょうか。なぜ品川区は常駐しなくていいとしたのか、伺います。","respondent":"鈴木生活衛生課長","answer":"管理者の常駐を義務づけている区が１５区というお話ですが、そのときには、それ以外の１５区については状況を把握しておりません。品川区をはじめ、都の基準に沿った受託の業務を同じ形で実施しているという形で、常駐の義務化をかけていないというのが現状です。","id":"exchange-119"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして区議会はどうなっているのか、なぜこんな条例にしてしまったのかという、怒りにも似た問いも飛びました。自治体としてそうした条項が入れ込めるわけですから、こうした条項に変えていくべきではないでしょうか、伺います。","respondent":"鈴木生活衛生課長","answer":"品川区でもかけておりますので、その上で、基本的には安全が確保できるというのが前提と考えております。実際に緊急対応や危険な状態がある場合には、当然、対応できる状況は区でも整えておりますし、事業者にもそれを求めるところです。","id":"exchange-120"},{"speaker":"横山委員","kind":"質問","question":"私からは、２７３ページ、こころの健康づくり事業についてと、２９１ページ、産学連携推進事業についてをお伺いいたします。１点目は、こころの健康づくり事業についてお伺いいたします。","respondent":"榎本荏原保健センター所長","answer":"１０代から３０代ぐらいの女性についてですが、パニック発作や夫のアルコールといった、さまざまなご相談を受けているという傾向があります。相談をなるべく今後もわかりやすく、目に触れるような形で行っていく必要もあると感じているところです。","id":"exchange-121"},{"speaker":"横山委員","kind":"質問・要望","question":"性被害などの犯罪などに巻き込まれないためにも、若年女性に特化した支援のあり方というのを今後検討してはいかがでしょうか。若年女性に特化した問題に詳しい職員の配置や研修を実施してほしいと求めましたが、区のご見解を説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"こころのケアの分野におきましては、最近、民間やＮＰＯの団体も非常に増えてきていると認識しております。相談内容に応じては、女性の相談センター、児童相談所、警察や、ほかの部署などにも連携を図ってやっていきたいと考えています。","id":"exchange-122"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、産学連携推進事業についてお伺いいたします。多様な機会を通じて、今後どのようにきっかけづくりを進めていくのか、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"昨年度からこうした具体的な支援メニューにつながる前段として、小さな規模の中小企業が、産学連携の情報交流会というのを創設しています。平成３０年度には、３カ所に参りまして、有益な関係を創出してまいりたいと考えるところです。","id":"exchange-123"},{"speaker":"横山委員","kind":"意見","question":"品川区における課題、企業と大学の研究内容とのマッチングを進めていきたいと思いますが、簡単にお願いしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"区全体で連携しているＣＳＲの活動も含めまして、今例示をされました、いいマッチングができるアンケートなども含めて、検討してまいりたいと考えているところです。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一つは、２６２ページの健康推進費の中で、受動喫煙についてお尋ねいたします。健康課として、何かこういったスローガンのようなものがありましたら説明を求めました。","respondent":"鷹箸保健予防課長、高山健康課長","answer":"ご案内のとおり、今年から品川区独自の対応といたしまして、１回１,０００円のインフルエンザの費用の助成という新規事業を開始しました。それを使って接種していただくということで、小児と６５歳以上で少し制度が変わっておりますが… 屋内外の取りまとめの検討という点で申しますと、７月１日から第一種施設ということで、おおむね３００を超える施設の区分があります。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"これがスローガンとは言いませんが、法にもこれは明記されておりますので、そこはくれぐれも据えて進めてほしいと求めました。この法にのっとって、健康課は事業を今年度、来年度、進めていくと理解をしておりますので、ここで一言、決意を述べてほしいと求めました。","respondent":"高山健康課長","answer":"健康増進法のカバーするところとしては、屋内が中心となってまいります。しっかりとした閉鎖型の喫煙所を設置するなどといった形で、屋外においても取り組みを進めるべく、庁内関係機関と協力して進めてまいります。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということで、区が技術者を求める地元の企業とモンゴルの高専の学生をつなぐ事業で、正規雇用として採用した第１号ということです。簡単にこれまでの経緯と今後の採用といいますか、就職に関する見通しについてお尋ねします。","respondent":"山崎商業・ものづくり課長","answer":"１カ月間にわたる長期インターンシップ事業を通じ、区内企業の技術者不足への対応として、事業を行ってきたです。来年度につきましては、さらに人数を拡大しまして、８名から１０名ほどを目標に、区内での活躍を期待するという状況になっているところです。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"今後の展開もさらに広がっていくという見込みを、今お聞きしました。今後の課題もあると思いますが、その点についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"今年度予定している先ほどの３名につきましては、いわゆる中堅中小ということで、その会社に社員寮が完備されているといった条件がございました。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話があったように、住まいについては本当に、住み慣れたところでない外国に来てお仕事をされるということですから、当然大きな問題となります。解決されていない場合は、どのような形でクリアされて今回の就労に結びつけたか、お願いします。","respondent":"山崎商業・ものづくり課長","answer":"そうした居住支援の中で、区全体の部門と連携して対応していけたらいいなと思っていまして、そのように進めたいと考えています。支援をするＮＰＯ団体などと区が後ろ盾になるような形で連携をして、その事業をＰＲする中で、一つ大きかったかなと考えています。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"４年制大学に行かれる方がたくさんいらっしゃり、今お話があったように、なかなか理解していただくのが大変だったとお聞きしています。それらのことも鑑みて、モンゴルの高専卒業生に関する就業支援について、改めて今後の意欲といいますか、取り組みをお話しほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"今回第１号の正規雇用が生まれまして、行政としてどこまで中小企業に実際につなげる支援、フォローというのはあると思います。小さな企業の中で十分発揮していっていただくことを期待しながら、定着支援など必要な事業について取り組んでまいりたいと考えるところです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"モンゴルという遠い国とのこのような交流を、ぜひ拡大していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"本多委員","kind":"質問","question":"初めに、２８５ページの東京二十三区清掃一部事務組合分担金について伺います。２３区で協議をしてきたところですが、今年度から２３区と一部事務組合で防止を図るとしていますが、その点について説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"そういった中、今、不適正搬入物につきましての取り組みを強化しているです。一組でも取り組みを強化しまして、委託によりまして、常時そのような不適正搬入がないかどうかというのを確認するといった取り組みをしています。","id":"exchange-132"},{"speaker":"本多委員","kind":"質問・要望","question":"毎年２３区が負担をしている分担金で賄えればいいけれども、今現在の取り組みについて、さらに強化をしていただきたいと考えています。もしなってしまったときの経費のかかり方に、何か削減できるような工夫とか、そういったものというのがおありかどうか、説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"近年は平成２９年に板橋清掃工場が停止して以来、工場の水銀混入がないです。その前に自動的に、強制的に清掃工場をとめて、長期間の停止を免れるようなノウハウもかなり確立されてきたです。","id":"exchange-133"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ、本当に数本の体温計で、また工場がとまってしまいますので、その危機管理意識だけは持って取り組んでほしいと求めました。し尿処理について伺いますが、４つに分かれますけれども、品川区内の状況を説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"品川区内での状況ですけれども、現在、平成３０年度は世帯数６件です。年間の収集量は７.１６トンという実績があります。","id":"exchange-134"},{"speaker":"本多委員","kind":"質問","question":"６件、わかりました。平成２９年度が２億１００万円余ということで、それで合っているのでしょうか、説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"し尿の部分というのはわずか１０％という構成比になっていまして、それ以外が先ほどお話ございました浄化槽汚泥や、し尿まじりのビルピットです。昨今の人件費等の上昇によりまして、２億１,０００万円余、経費がかかっているです。","id":"exchange-135"},{"speaker":"本多委員","kind":"質問","question":"例えば夜間収集など、時間を今までと違う時間にするようなことは考えられるのか、教えてください。歳入のところで臨時収集４３６件とあるのですけれども、従来と同じなのか、何か変化があるのか説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"引き続き、期間中に確実な収集運搬ができるように、今後検討をし、今後の策を決めてまいりたいと思ってあります。こちらのほうも、確実に収集ができるように対応を図ってまいりたいと考えています。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２７９ページ、アスベスト対策事業、２８１ページ、資源ステーション回収について質問します。区は独自で平成３０年度からアスベスト分析調査助成等、現在の相談件数はどれぐらいあるのか、まず教えてほしいと求めました。","respondent":"小林環境課長","answer":"平成３０年度で申し上げますと、約１５０件程度が相談として来ているところです。アスベストにつきましては、法令・条例に基づく手続きがあるというところから、特に手続きに関する内容がほぼ半分を占めているといった状況です。","id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１５０件あるという中で、まだまだアスベストを使用している店舗、そして住宅も相当数あると思います。そんな中、先ほど申しましたように、助成がいろいろあると思うのですけれども、助成内容も教えてほしいと求めました。","respondent":"小林環境課長","answer":"１点目は、その分析をするための費用として助成を行っているというところが、まず１点目です。もう１点目につきましては、上限２００万円として助成を行っているといった、２つの事業を進めているところです。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"助成の２００万円という枠の中で、解体業者が違うレベルの申請を出して、そのまま解体をしてしまう。申請を出したところの確認に行かれると思うのですけれども、どのようにお考えになっているのか、お知らせほしいと求めました。","respondent":"小林環境課長","answer":"工事が始まる前につきましては、区の職員がその申請どおりに工事とか対策が進められたかどうかを目視で把握して、安全性は確認しています。工事が終わった後につきましても、書類の提出を求めて写真の確認等を行って、安全性を確認しているといったところです。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"非飛散というのは、昭和３０年代ぐらいからあったＰタイルとか、それも非飛散性の床材だと思うのです。その非飛散性に対する今後の取り組みをお知らせほしいと求めました。","respondent":"小林環境課長","answer":"その中で、国はこれらの法改正を来年度に向けて進めるというところが、今示されているところです。そういった動きを区もしっかりと把握した上で、これらの事業を進めてまいりたいと考えています。","id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、２８１ページ、資源ステーション回収についてお伺いをいたします。その内容について教えてほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"内容ですけれども、回収品目を定めまして、事業委託によりまして、週１回の回収を行っております。回収につきましては、委託事業者にお願いしているものです。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、事業所から排出される資源処理についての考え方も、あわせてお知らせをしてほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"事業所から排出される資源処理につきましての考え方ですけれども、事業活動により排出されたということで、事業所みずからの責任で処理をするです。したがいまして、清掃事務所に出す場合には、事業系の有料ごみ処理券を貼付していただいて、排出をしていただく形になります。","id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは事例なのですけれども、例えば土曜日に会社がお休みのところが、今、多いと思われますけれども、会社の休みの土曜日、そのエリアが資源回収日になっている場合の対応、曜日等の変更は可能なのか、教えてほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"変更につきましては、なかなか難しい状況があります。そのような理由からです。","id":"exchange-143"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。変更が困難であることは理解できたのですけれども、そのほか考えられる対応策はあるのかどうか、お知らせほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"区では平成２３年度から、事業系リサイクルの支援をしております。具体的には、利用者が品目別に資源を集めていただきまして、一定数以上回収量が見込まれましたら、回収に伺うというシステムです。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"私は２８４ページ、産経費全般についてお伺いしたいと思います。今回の消費税１０％の増税開始と、これはスムーズにいっているのでしょうか、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"例えば食料品を扱って、必要に応じて、軽減税率に対応した複合レジが必要になってくるという見立てで推計をしております。区としましても、そういった状況にはあるかなと捉えているところです。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"実質、今回新型レジを導入した中小零細企業も、約半分以上は９月３０日に間に合わなかったという記事まで出ています。その辺について説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"政府のほうも、９月３０日の設置あるいは支払い完了ですとか、これから対応も少し進んでいく部分はあるかなと期待しているところではあります。","id":"exchange-146"},{"speaker":"須貝委員","kind":"意見","question":"これはおかしくありませんか。見解を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"そういったロジックのお話かなと思っています。価格表示の方法でありますとか、そういったことも含めて、経営相談の中でご相談を受けて対応しています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"これは筋が通らないのではないですか。もし国ができないなら、東京都なり区なりでしっかり補助するというのが、自治体としての役割だと私は思うのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"それから、それに対応したレジにつきましても、新しいものに今回のことをきっかけに切りかえていこうというところです。どんな状況であれ、しっかり対応していくということで、日ごろ業務をさせていただいているところです。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問・要望","question":"このお店はどうなのか、それから製造業はどうなのか、しっかり見ているわけです。そして今後の品川区の発展に寄与していただくように、私は、これからも頑張って支援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"のだて委員","kind":"質問・要望","question":"区有施設への太陽光発電などの再生可能エネルギー設備の設置をさらに進めてほしいと求めましたが、いかがでしょうか。あわせて、太陽光発電システム設置助成のこの間の推移と、助成額の拡大を求めますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"太陽光発電の区有施設への設置についてですが、現在３７施設で太陽光発電設置が進められているです。助成額を上げたことで太陽光発電システムの設置数が伸びたというところは、助成額の変更につきましては、機器の価格の動向とか。","id":"exchange-150"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後の進め方といいますか、どこまで広げていこうと考えていらっしゃるのか、地域センターや学校などあると思いますけれども、伺いたいと思います。区としては何を考えていらっしゃるのか、助成額の増額は有効だと思いますけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"そういうところを鑑みながら、可能な限り設置については進めていきたいというところで、可能な限りの設置を進めていきたいと考えているところです。","id":"exchange-151"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区全体として、区有施設に再生可能エネルギーで、使用電力を何割賄っていこうという方針は持っていらっしゃるのでしょうか、伺いたいと思います。ぜひ進めていくという立場で引き続きやってほしいと求めましたので、課題などを、ぜひ整理していってほしいと求めました。","respondent":"小林環境課長","answer":"方針として、難しいかと考えていますが、基準年からしっかりと削減していこうというところは計画の中で示したところです。それの解決策の一つとしましては、効果としてあらわれてくる部分ですので、そういうところをしっかりと進めてまいりたいと考えているところです。","id":"exchange-152"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校などを対象とする再エネ１００宣言、英語ではＲＥ Ａｃｔｉｏｎといいますが、この仕組みがつくられました。品川区も再エネ１００宣言への参加検討を求めますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"今、せんだって開設が行われました品川区立障害児者総合支援施設でも、そういったところからのエネルギーの導入というのを進めているところです。みずからつくり出すということも考えながら、両軸で考えていきながら事業を進めてまいりたいと考えているところです。","id":"exchange-153"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後もそれを引き続き進めていってほしいと求めましたが、キャンペーンなどの対応を優先的にとることを宣言しているというところもあります。品川区でも、こうした気候非常事態宣言をすることが必要ではないかと思いますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"最新のデータであります平成２８年度の状況に行きますと、約１０.４％削減が進んだというところで、傾向としては減少傾向で進められているです。これらの減少傾向の推移を十分注視しながら、今後の検討については進めてまいりたいと考えているところです。","id":"exchange-154"},{"speaker":"のだて委員","kind":"質問","question":"地球温暖化対策に向けても、再開発事業はやめるべきではないかと思いますが、いかがでしょうか。一定規模の企業やビル建設には太陽光発電など、自然エネルギー導入を義務づけるべきだと思いますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"そういったところを考えていきますと、一定規模の建物については、一定の省エネに対する配慮がなされていると判断しております。そういった中で、さまざまな取り組みが進められている中で、自主的な太陽光発電システムの設置等についても進められていると認識しています。","id":"exchange-155"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に、廃プラスチックの問題も伺いたいと思います。使い捨てプラスチックをなくしていくきっぱりとした姿勢を示していくことが必要だと思いますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"廃プラスチックの関係ですが、さまざまなイベント、特にエコにかかわるイベントを通じて啓発を進めております。引き続き、可能な限りの対策は進めてまいりたいと考えているところです。","id":"exchange-156"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この中に休日診療に関しての医師賠償責任保険というのが計上されていると思いますが、その内容と金額を教えてほしいと求めました。昭和３７年から昭和５４年生まれ、昭和４７年から昭和５４年生まれの方にということだそうですが、説明を求めました。","respondent":"高山健康課長、鷹箸保健予防課長","answer":"私からは、前段の休日・夜間に係る医師賠償責任保険の中身、内容と金額というお尋ねのほうでお答えをします。緊急処置などの費用と、金額につきましては、休日歯科と休日医科と合わせて３１万６,３００円の予算を組んでいるところです。 このうち、８月末までの間で抗体検査は１,４９８名の方がお受けになりまして、麻しん風しんＭＲワクチンを接種された方が２７５名です。検査の受検率は全体から６.１％という状況です。","id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いろいろ団体の懇談会の中で要望も出ておりましたけれども、平成２５年に両医師会と品川区で、そこについての見解を教えてください。新聞等では１割にも満たないということで、１割にも満たない状況になっていますけれども、さらにプッシュをしていくのかというのを説明を求めました。","respondent":"鷹箸保健予防課長、中島防災課長","answer":"８月に対象職員に抗体検査を、区役所の中で検査を受けることができるという、追加の対策を実施したところです。今の時点で１８.１％ということがわかっておりますので、そういった体制を… 委員からご紹介のありました医師会との協定に基づくところですが、内容につきまして、費用負担等の扶助費の記載はありますが、その具体的なところにつきましては、国、都、あるいはほかの自治体の状況を踏まえながらと考えております。","id":"exchange-158"},{"speaker":"たけうち委員","kind":"意見","question":"両方抑えられるということですが、そこはしっかりやっていかなければいけないのかなと思うので、ぜひよろしくお願いします。どうするのか、明確にしてもらいたいということだと思うので、もう一回お答えをお願いしますとの意見を述べました。","respondent":"中島防災課長","answer":"答弁漏れでございまして、先ほどの賠償責任につきましては、災害時にそのような保険対応が可能なのかどうかも含めて、ほかの事例等も含めまして研究等をさせていただきたいと思います。","id":"exchange-159"},{"speaker":"石田（秀）委員","kind":"質問","question":"わかりやすさもあるではないですか。この辺のところをどうやって捉えて、どのようにわかりやすさを訴えていくのかというところを説明を求めました。","respondent":"高山健康課長","answer":"したがいまして、今回検討を進める中では、今後５年間で５％程度の改善が見られるものを、一つ成果ととっていこうと考えているところです。","id":"exchange-160"},{"speaker":"石田（秀）委員","kind":"質問","question":"健康長寿の３要素は運動、これはこれで頭にぱっと入るから、いいではないですか。特に健康なのだから、そういう考えを持っていらっしゃると思うのだけれども、その辺のお考えを聞かせてほしい。","respondent":"高山健康課長","answer":"先ほどもう少しご説明を加えるべきところだったのですが、対象を明確にした健康づくりへの支援という中で、新たな項目として追加いたしました。これを一つ、対象を明確にして、委員がご指摘になるような介護予防の視点なども踏まえた目標設定をしてまいりたいと考えております。","id":"exchange-161"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最後はお願いになりますけれども、今、品川区でも２年に１回、世論調査等もかけて、項目の中でもこの部分はあるではないですか。だから、その辺はもう少し強く健康課で、介護予防を含めて健康づくりをやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"２８７ページ、中小企業事業資金融資あっせん、それと時間があれば２９３ページ、商店街関係を伺いたいと思います。平成２６年度から平成３０年度で激減をしているのですけれども、まず、これの理由を教えていただきたいのが一つ。","respondent":"山崎商業・ものづくり課長","answer":"景気動向によって上げ下げしますが、今、平均的には２００とかという数字に落ちついているです。そういう意味で、平成２８年度から事業承継の問題について、品川区は取り組んだということです。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問","question":"既に５年、６年前から高齢化が始まっていて、今に始まったことではない。平成２８年度当時は高齢化も始まっているわけで、なぜその前に、そこを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"みんなで考えるべきことと、それぞれの企業の持つ問題については、そういった領域の中で支援をしていこうという必要性が高まった時代背景があるです。国よりも東京都よりも、いち早く手がけているのが品川区です。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問","question":"平成３０年度に至っては２９件になっていますので、それは何でしょうかということで質問させていただいたのですけれども、わかりますか。「費」というお金の項目を表示するのはいただけないような気がするのですけれども、そこのところはどのようにお捉えになっているか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"先ほどの不況業種認定に係る相談のことということで、トレンドが減っていますということでご理解をいただけたらと考えています。ご意見を参考にさせていただいて、いろいろ事業名称の表記など、工夫してまいりたいと感じたところです。","id":"exchange-165"},{"speaker":"大沢委員","kind":"質問","question":"これで質問を終わらせていただきますが、商店街のほうは、また改めまして質問します。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/955943?Template=document&Id=1474#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":118408,"voices":374}},{"id":"r01-20191008-4","meetingId":"r01-c-settlement","date":"2019年10月8日","dateIso":"2019-10-08","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件整理しています。","topics":[{"id":"topic-01","title":"◯大倉委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成３０年度品川区一般会計歳入歳出決算","agenda":"◯大倉委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成３０年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"は避難所管理費から避難所のあり方、プライバシー問題、ペット問題についてお伺いいたします。避難所に対する品川区のご見解を説明を求めました。","respondent":"中島防災課長","answer":"やはりまず直接的な生命を守るというところも、十分、重要視して取り組んでおります。備蓄やトイレなど、もろもろ総合的に取り組んでいるところです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"教育委員会の管理施設かと思いますが、教育関連の事業が優先となるために、災害対策関連の事業が進まないなどの記載も見つけました。品川区ではどのようになっているか尋ねました。","respondent":"中島防災課長","answer":"現状でも、それがやはり一番効果的かと考えて、学校避難所を中心に進めているところです。なので、そういう意味で、学校の活用について、より一層進めてまいりたいと考えています。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"ということは、別に、教育委員会の管理施設だから災害対策が進まないといったことはないということでよろしいでしょうか。どのような内容で、進み具合といいますか、そういうものはいかがなものなのか尋ねました。","respondent":"中島防災課長","answer":"それを一定程度高めるような支援を行いまして、さまざま課題はありますが、そのようなところについてレベルアップを図っているところです。今後もそのような取り組みは進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、避難所運営マニュアルというのは統一ではなく、やはり地区ごとにマニュアルというものを考えられているといったものなのか尋ねました。","respondent":"中島防災課長","answer":"避難所運営マニュアルは、区民避難所の設備の状況や収容人数等にもよりますが、やはり地域によって多少は差があるものです。それが統一的になるように共通化を図ったものを、標準マニュアルとして示させていただいているところです。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"要は自分たちで守らなければならない。現状、地域の意識は低く、相互理解が得られていないように思いますが、品川区との連携ということも含めて、お考えがありましたら説明を求めました。","respondent":"中島防災課長","answer":"あるいはその前段の家庭での備え、自助という観点も含めまして、自助・共助をベースとして考えております。相互理解が深まるような訓練を通じて、相互理解を深めるようなところを、区としても支援してまいりたいと考えています。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"私も先日、荏原第五地区の総合防災訓練に参加させていただきました。ＪＴの社宅跡地ですか、そういった大規模な訓練というものを、区と連携してやるということは可能なのか尋ねました。","respondent":"中島防災課長","answer":"１カ所で大規模というのは難しいですが、時期を合わせた区内一斉防災訓練というものをやっているところです。なので、周辺地域との関係などというところも、そういうところで生まれると思いますので、そういう形で進めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"ペット対策についてのお考えが１点。品川区では、災害時に仮設トイレの設置などは、どういったマニュアルになっているのか尋ねました。","respondent":"中島防災課長","answer":"少しずつではありますが、同行訓練も行ってみようかという避難所も出てきておりますので、そういう流れで進めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"これは５日で５,０００枚の約束ということでした。このようなよい事例がある中、品川区では、このような取り組みと連携するというお考えはありますか尋ねました。","respondent":"中島防災課長","answer":"不足しているような状況でございまして、今、やむを得ず協定という形でやらせていただいております。畳や間仕切り、段ボールベッドみたいなものは協定先から送られるような形で、協定を締結しています。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"そういった施設にも避難ができるよう望みまして、この質問を終わらせていただきます。あまり参加がないように感じますが、団友会へのお願いといったものは品川区からの要請でやるのか、それとも東京都からの要請なのか尋ねました。","respondent":"大森災害対策担当課長","answer":"消防団ＯＢを中心として３団体が結成されており、団操法大会の指導などで、現職の消防団員指導の活動に当たっていただいていると。区といたしましても、このように認識しています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"平日に呼ばれることも大変多く、消防団の中には会社員の方が大変多いので、なかなか平日に集まることが不可能に近いということがあります。団友会の方をしっかりと防災対策の一組織と考えていただいて、地域の防災リーダーとして確立してほしいと求めましたが、いかがか尋ねました。","respondent":"大森災害対策担当課長","answer":"現職の消防団の要請に基づいて消防団の活動を支援していると理解しておりまして、東京都という位置づけになるのかと考えているところです。区といたしましては、そういった議論の結果等を踏まえまして、消防署と連携しながら考えてまいりたいと考えております。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"そこでお聞きいたします。品川区における無電柱化の計画は、現在はどのように進んでいるか尋ねました。","respondent":"多並道路課長","answer":"無電柱化推進計画につきましては、現在、これから１０年間に整備する無電柱化の計画について検討しています。交通安全などを基本方針として、１月には素案をつくって、進めているところです。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、２９７ページ、駅周辺等放置自転車対策事業、シェアサイクル事業、それから３０１ページ、災害時消えない街路灯設置についてお尋ねします。そこで、まずこの事業内容と実績を説明を求めました。","respondent":"古郡交通安全担当課長","answer":"これについては、自転車への警告札の取りつけや、あとは放置者への声かけということで、警備員に委託して実施しているものです。撤去管理返還業務と保管費用徴収委託ということで、放置自転車の撤去・移送・保管・返還業務、そして保管料の徴収等を行っているものです。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問","question":"これは、駅周辺の駐輪場が満車になってしまうため、放置自転車とならざるを得ない数字だということでしょうか。そちらにつきましても教えてほしいと求めました。","respondent":"古郡交通安全担当課長","answer":"駐輪場の利用率については、全体では７０％前後ということですので、駐輪場にとめるのではなく、やはり駅の近くにとめたいということで、自分の意思でとめている方が多いのかと認識しています。","id":"exchange-013"},{"speaker":"湯澤委員","kind":"質問","question":"ちなみに、満車になってしまっている駅と、すかすかの駅というのはあるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"利用状況につきましては、非常に高いのが、大崎駅や五反田駅、大井町駅です。少ないところは、下神明駅とかです。","id":"exchange-014"},{"speaker":"湯澤委員","kind":"質問","question":"駅周辺で空きスペースのある企業などにお願いしたり、また現在ある駐輪場におきましては２階部分を増設したりするのはいかがかと思います。場合によっては撤去回数を増やすことも必要かと思いますが、その辺はいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"そういったものへの対応をしておりますので、利用者が利用しやすい環境というのを、引き続き整備してまいりたいと考えております。それを３台にするとか、そういった考え方もありますので、そういった形でしっかりと撤去対策を引き続きやっていきたいと思います。","id":"exchange-015"},{"speaker":"湯澤委員","kind":"質問","question":"こちらは既に別の款でほかの委員が質問される部分もあったかと思いますが、改めて事業内容と利用実績を教えてください。シェアサイクルが放置自転車の解消につながるかどうかも、あわせてご見解を説明を求めました。","respondent":"今井土木管理課長","answer":"シェアサイクル事業につきましては、平成２９年から、東京オリンピック・パラリンピックを見込みまして、観光などの視点から始めたものです。","id":"exchange-016"},{"speaker":"湯澤委員","kind":"質問","question":"ただ、区内競技場周辺に利用が集中する可能性があるのではないかと思いますけれども、そもそも区内競技場には十分な駐輪スペースがあるのでしょうか。競技会場周辺にシェアサイクルポートの新設または増設を予定しておりますか尋ねました。","respondent":"今井土木管理課長","answer":"今、ポートを開設しておりまして、そこは規制外です。こちらにつきましては、今年度、利用状況を見まして、今、１０台から２０台へ増設を進めたところです。","id":"exchange-017"},{"speaker":"湯澤委員","kind":"意見","question":"充電が切れてしまうと、坂道なども上れないぐらい重くなってしまうと思うのですが、その辺はどうなのでしょうとの意見を述べました。","respondent":"今井土木管理課長","answer":"現在、充電器につきましては、災害時対策、そして区役所の法人利用も含めて、区役所内に設置しています。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問","question":"３０７ページ、時間がありましたら３１１ページ、八潮地区の将来像検討経費についてお伺いたします。８団地７５８戸、そしてこの空き部屋のうち何部屋がすぐに入居することができるのか、その数をまずお知らせください。","respondent":"森住宅課長","answer":"８月末現在の建設型区民住宅の空きについてですが、現在、９８戸、空きがある状態です。原状回復等々を行っているところもありますが、基本的にはほとんど、すぐに入れるかとは感じているところです。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"９８戸、ほぼ即入居可能と確認させていただきました。品川区では、そういう区民がいらっしゃった場合の対応はどうされているのか、お伺いいたします。","respondent":"森住宅課長","answer":"罹災証明書の発行件数ですが、９月末現在で２９件と確認しております。ソレイユ戸越の１室を２日間、それから、罹災証明書で被害程度が半壊以上であった場合には都営住宅をご紹介するという形でやっているところです。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"罹災証明書が２９件発行されているということが確認されました。そういう対応もしていただきたいということを非常に深く思ったところなのですが、このことについてはいかがか尋ねました。","respondent":"森住宅課長","answer":"東京都が５０戸、今、やられていると聞いております。災害の大きさや、あとは建物の損壊の程度など、さまざまな状況に応じて判断してまいりたいと考えております。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう一点、罹災証明書について確認なのですが、品川区が発行する罹災証明書は、一部破損ということで発行されております。「一部破損」と、「一部損壊」というのは、同じ意味なのかということを確認させてほしいと求めました。","respondent":"中島防災課長","answer":"内閣府の基準に基づきまして判定等を行っておりまして、基本的に一部損壊というものは、やはり一定程度の割合のもので損壊されたものでございまして、一部破損というのはそれ以下ということですので、必ずしも一緒ではないかとは思っております。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問","question":"恐れ入ります。再度ご答弁いただけますか尋ねました。","respondent":"長尾建築課長","answer":"一方で、一般的には「一部損壊」という言葉も使われております。同義の言葉として、証明書発行に当たっては調査を行っているところです。","id":"exchange-023"},{"speaker":"新妻委員","kind":"確認","question":"一部破損、一部損壊、同じ意味であるということが確認されました。続いて、水辺ライトアップ整備工事についてお伺いいたします。","respondent":"松本河川下水道課長","answer":"全体の設置数ですが、目黒川につきましては、全体で１０カ所に設置する予定としております。あわせて、京浜運河で２カ所、天王洲南運河で１カ所、あと目黒川の護岸でライトアップをする予定としております。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問・要望","question":"この１０月の５・６日でしながわ水辺の観光フェスタがあり、地域の自治会を中心に若い方がこのイベントを盛り上げました。オリンピック・パラリンピックの開催という位置づけをいたしまして、住民参加で大々的に開催してほしいと求めましたが、いかがか尋ねました。","respondent":"松本河川下水道課長","answer":"点灯式につきましては、地域の要望も伺いながら、実施する方向で、今、検討しています。オリンピック・パラリンピック準備課と、どのような取り組みができるのか、協議を重ねていきたいと考えております。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"区内にエスコートゾーンは何カ所設置され、区内全部の横断歩道に対する整備率は今どれぐらいになっているのでしょうか。お伺いいたします。","respondent":"古郡交通安全担当課長","answer":"エスコートゾーンにつきましては警視庁で設置しているのですけれども、区内で１１カ所設置しています。全体の横断歩道に対しての割合については承知しておりません。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問・要望","question":"これはかなえられているのでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"設置に関するところは、警視庁の公安委員会です。社会福祉協議会の前にエスコートゾーンが設置されたところもありますが、すぐ、間を置かずにというところにはつながっていないところがあります。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問・要望","question":"こういうささやかな要望が、もう何年もの間、かなえられていない。なぜ一向にかなえられないのか、その辺をどうお考えになっているのか、もう一度ご答弁ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"エスコートゾーンの設置について、非常に通るときの音がうるさいということで、なかなか地域の理解も得られないという箇所もあるとは聞いてあります。","id":"exchange-028"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこでもう一度お伺いいたします。そういう問題も背景にある以上、非常に品川区としても、要望する場合に、より強い姿勢で臨まなければいけないということがあるのだと思うのです。","respondent":"鈴木都市計画課長","answer":"視覚障害者団体からいただいている設置要望箇所については、複数いただいてあります。東京都、その設置要望箇所の中でも優先順位というのをお聞きして、一つでも二つでも設置の実現に向けてしっかり要望していきたいです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"時間があれば３１０ページ、都市計画費から、羽田新飛行ルートについてお伺いいたします。多くの皆様が本当にやはり電柱をなくすべき、無電柱化の必要性を感じたのではないか尋ねました。","respondent":"多並道路課長","answer":"特に台風第１５号の被害について、これまでも震災を特に中心に考えていたところではありますけれども、改めて認識したところです。震災を考えれば病院へのアクセスの道路など、１０年間でやるべきところということで検討し、進めていきたいと考えているところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"いつ起きるかわからないと言われている状況ですから、東京都と連携をとりまして、しっかりと進めていっていただきたいと考えております。続いて、燃料備蓄についてお伺いいたします。","respondent":"中島防災課長","answer":"区といたしましては、まず基本的には５２の避難所に、約１７０リットルの軽油を積んだディーゼルエンジン発電機を持っております。そのほかに、今年度からは、ポータブル発電機用といたしましてガソリンを備蓄しておりまして、合計で４８０リットルの備蓄をしています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"では、基本的に避難所に置いてあるということで、ほかの倉庫などには置いていないのか尋ねました。","respondent":"中島防災課長","answer":"学校は、発電機そのもの、タンクの中に軽油が入っておりますので、備蓄というのは、そういう形で、すぐ発電できるような状態を意味しております。そのほかについては、学校というよりも、区の備蓄倉庫で保管しているという状況です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"現在、品川区の備蓄燃料の使用期限が過ぎていないか、ちゃんと使えるのかどうか。いざ地震のときに使えるかどうか、いま一度点検していただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中島防災課長","answer":"異常時には緊急に対応しているところですが、基本的にはそれほど異常は発見されていないところです。消費した燃料についてはしっかり補充していますので、そのような形で循環もきちんとしておりますので、適切な管理に努めていきたいと思っています。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"引き続きしっかりと点検していただいて、震災時等に非常用発電機がちゃんと動くように、引き続き丁寧なチェックをお願いいたします。それについていかがお考えなのかということと、ＬＰガスを燃料とする非常用発電機の発電のご検討というか、それに対してのお考えはいかがか尋ねました。","respondent":"中島防災課長","answer":"説明の中等において、適宜紹介等も考えられるかと考えていますので、そのように対応させていただきたいと思います。現状、区民避難所に設置した発電機等で運用しているところでございまして、ＬＰガスについては今のところ検討はしていないところです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"比較的古くに建設されたので地下に発電機があるようなマンションの地下にある発電機を上げていくというような支援というか助成というのはお考えなの…発電機を地下から、浸水しない位置に上げるような支援というか助成をぜひ検討していただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中島防災課長","answer":"地下に発電機があるマンションというのがあるですが、それを上に上げる補助というのは、なかなか金額的な面からも難しいのかというところはあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"いざというときに隣近所、ぜひマンション自主防災組織の横のつながり、連携体制というのをとっていただきたいと考えております。ぜひ行っていただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"中島防災課長","answer":"基本的にはマンションの自助・共助というところもありますが、やはりそういう横のつながりということも、長い災害対応には重要かと考えています。かねてから実施しておりますので、住宅課とも連携いたしまして、交流が進むような形の取り組みに努めてまいりたいと思います。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたマンション防災についての取り組みも、ぜひ積極的に行っていただきたいと考えていますので、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"確認すると、４７ページ、「地域の下水道に使用制限がかかっていないか確認する。下水道使用制限をどこで確認できるのか、発災時に排水設備業者は点検が可能なのか、それぞれ伺います。","respondent":"中島防災課長","answer":"なかなか、災害時の点検というのは非常に難しいところですが、下水道局の示している手法等をお伝えするような形で取り組んでいきたいと考えています。やはり、基本的には、そのために自助としてトイレの備蓄等をあわせて啓発してまいりたいと考えています。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"今後のハンドブックの改訂では、そのような丁寧な記載をしていただきたいと思うのですが、見解を伺います。下水道使用制限の確認方法などを補足し、掲載していただきたいと求めますが、いかがか尋ねました。","respondent":"中島防災課長","answer":"マンションについては、１階から点検をしていくなどという方法はありますが、しながわ防災ハンドブックにも記載させていただいているところです。追加で下水道局と相談しまして、ハンドブックのページにリンクを貼るなど、そのようなところは検討してまいりたいと考えています。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"私が求めているのはマンションに限ったことではなくて、住民の方がどのように確認できるのかということを聞いております。現在、何かそのことに対して対策は考えられているのか伺います。","respondent":"中島防災課長","answer":"そのあたりの出し方については検討が必要ですが、既存の専門機関が出している情報をしっかりと伝えるようなことで対応してまいりたいと考えています。台風第１５号により長期間の停電等ございまして、その辺のところを含めまして、引き続き考えてまいりたいと考えています。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"さまざま研究していただき、早急に対策がされるよう求めます。再生可能エネルギーの促進とともに、在宅避難のメリットにもつながる蓄電池の設置について、現在、区ではどのような検討がされているのか伺います。","respondent":"小林環境課長","answer":"そういった都や国の動向をしっかり見据えながら、区としての役割を果たしてまいりたい。周知等につきましては連携を図りながらしっかりとやっていきたいと考えているところです。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"議事録では、区は避難所の改善の必要性を認識していることを確認しています。スフィア基準が求める被災者の権利、内閣府のガイドラインで求める避難所の質の向上へつながる取り組みとして、現在。","respondent":"中島防災課長","answer":"作成の運営を支援いたしました避難所運営マニュアル、その品川区の標準版につきましては、内閣府あるいは東京都の指針等に従いまして作成しています。それを実施に移すところを、避難所連絡会議等で働きかけているところです。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"これからは、説明会の実施時期を早め、住民の声を聞きながら調整ができる時期に説明会を実施することを求めますが、見解を伺います。全ての説明会において、説明会資料と議事録の公開を実施することを求めますが、見解を伺います。","respondent":"森住宅課長","answer":"こちらにつきましては、区内で一定程度規模以上の建築が行われる際については、説明会の実施や周辺の周知などを求めているものです。１回のみということではなくて、その中で事業者への指導ということについても進めていきたいと考えております。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"住民が理解を示す丁寧な周知・説明が行われるように求めていきたいのです。そして、あと議事録は全て公開していただきたいのですけれど、いかがか尋ねました。","respondent":"森住宅課長","answer":"説明会につきましては、説明会実施後に、区に説明会の報告というのをいただいております。説明会の議事録が見たいということを区に申される方もおられますけれども、出せるようにというような指導も加えてしています。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、どこの説明会でもきちんと議事録を公開するように再度求めますが、見解を伺います。子ども中心の、子どもにやさしいまちづくりを求めますが、見解を求めます。","respondent":"稲田都市開発課長","answer":"説明会当日、地域住民の方に２回、権利者の方に２回等やってきました。公園をつくったり広場をつくったりというところでやってきているところで、そのように子どもへの対応も考えているというところです。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、その子どもたちはどこで遊ぶのですか。子どもたちのこともきちんと考えられたまちづくりを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"くにば委員","kind":"質問","question":"私は３１１ページ、八潮地区の将来像検討経費と、２９７ページ、シェアサイクル事業の２点について伺います。初めに３１１ページの八潮地区の将来像検討経費についてですけれども、貨物ターミナル、現在構想中の将来の八潮地区について概要をお知らせください。","respondent":"鈴木都市計画課長","answer":"検討といいますか、いろいろ意見交換をさせていただいているエリアにつきましては、八潮地区の団地のエリアです。あるいは団地・マンションを所有する事業者の方々と意見交換なども行いながら、今、そうした機運醸成の取り組みを行っているというようなところです。","id":"exchange-047"},{"speaker":"くにば委員","kind":"質問","question":"この高齢世帯流入に関しての見解をお知らせください。そして、また子育て世帯の転入促進のためにどのような施策を考えておりますか尋ねました。","respondent":"鈴木都市計画課長","answer":"さまざまな各部署、そうした取り組みを行っていますが、地域の中で高齢者も元気に活動あるいは過ごしていただけるような取り組みもしております。そうした総合的な取り組みの中で、長期的にはなりますが、しっかり考えていきたいです。","id":"exchange-048"},{"speaker":"くにば委員","kind":"質問","question":"今のご答弁を伺った次第では、そういった福祉、高齢者に関しての記載しかないのです。明らかにバランスが悪いまちになってしまうのですけれども、今申し上げました、若者向けの転入促進の施策はありませんか尋ねました。","respondent":"鈴木都市計画課長","answer":"さらに八潮に住んでいただくというところ、やはりこれは、都市計画一手でこの施策を進めるというのはなかなか難しいというところはあります。","id":"exchange-049"},{"speaker":"くにば委員","kind":"質問","question":"さらに、いわゆるカラオケ等の娯楽施設も全くありません。兼ね合いもあると思うのですけれど、区全体として俯瞰で捉えて、そちらに関しては何か事業者と話し合いをしたりしているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした施設が先行するのか、あるいはそうした消費が見込まれるので先行して乗り込んでいただけるのかというところは、いろいろあるかと思います。将来像の検討をしている中で、魅力の創出につながるかというのは、この検討の中でしっかり検討していきたいです。","id":"exchange-050"},{"speaker":"くにば委員","kind":"質問・要望","question":"税収を高め、それをさらなるまちづくりに活かしていただくよう要望して、次の質問に移ります。設備投資や運営費など、ドコモ・バイクシェアとの分担はどのようになっておりますか尋ねました。","respondent":"今井土木管理課長","answer":"運営収入で１,０００万円程度、赤字を見込んでいるというのが、ドコモ・バイクシェアの今の想定です。検討を進めているところで、特に１０区と連携しての運営事業ですので、１０区との共有も図っていきたいと考えています。","id":"exchange-051"},{"speaker":"くにば委員","kind":"質問・要望","question":"１,０００万円の赤字ということですけれども、区民サービスの利用を促進していただきますよう、こちらもよろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問","question":"２９７ページ、お時間がありましたら３２７ページ、コンクリートブロック塀等安全化支援についてお聞きいたします。そこで、ユニバーサルデザイン遊具等検討費とは具体的にはどのような費用なのか、内訳をお教えください。","respondent":"溝口公園課長","answer":"平成３０年度に行いましたユニバーサルデザイン遊具等の検討です。ユニバーサルの遊具にどのようなものがあるのかといったところを、先進事例を含めて調査検討し、先行して委託業務を発注したものです。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"今お話がありました、そこでお聞きしたいのが、こちらはどのような児童を対象にしていますでしょうか。スペシャルニーズのある児童も含まれておりますか尋ねました。","respondent":"溝口公園課長","answer":"小学生を対象にしたワークショップですが、区立小学校・義務教育学校の３年生・４年生を対象にワークショップの募集をかけたところです。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問","question":"全６回のワークショップの説明文の中には、インクルーシブな公園について知ろうと。事前に、スペシャルニーズがある方への合理的配慮に関するサービスを行えるように、それは予算には組み込まれていなかったか尋ねました。","respondent":"溝口公園課長","answer":"今回、ワークショップの運営ですとか企画、またワークショップ当日の体制といったものを全て含めて委託業務の中に入れております。スペシャルニーズと言いますと、さまざまな方への対応といったところは、そういった経費を見込んだ中で全て委託しているというのが現状です。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひ品川区で検討していただいて、そのような状況を想定して予算を組んでいただいて、委託業者に適切な委託をしていただきたいと要望いたします。そうしますと、スペシャルニーズがある方には別の機会にお話を聞くということでよろしいか尋ねました。","respondent":"溝口公園課長","answer":"そういった中でいきますと、そういったスペシャルニーズを持った子どもたちの意見も聞きながら進めていきたいとは考えております。お互いに意見交換をするとか、ご意見を聞きながら、今後に活かせるような子どものアイデアといったものをつくっていきたいと考えているところです。","id":"exchange-056"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらは要望いたします。この交通安全啓発費の中に、特に高齢運転者に対して働きかける費用というのはどのようなものが含まれていますか尋ねました。","respondent":"古郡交通安全担当課長","answer":"高齢者をターゲットにしてやっているのは、高齢者の交通安全講習会ということで年４回実施しているもので、２９万４,８００円という額です。","id":"exchange-057"},{"speaker":"せお委員","kind":"提案","question":"こちらの安全運転支援装置ですが、私からは、東京都の補助金以外の残り１割の部分を品川区で助成することを提案いたします。改めて品川区のご見解を説明を求めました。","respondent":"古郡交通安全担当課長","answer":"動機づけについては９割補助すれば十分ということで区としては認識しているところで、補助する必要性は認められないと考えております。高齢者に関して、安全講習会や「お元気だより」など、さまざまな機会を捉えて、直接的に安全運転について指導しています。","id":"exchange-058"},{"speaker":"せお委員","kind":"質問","question":"重大事故が起きてからでは遅いので、ぜひご検討をお願いいたします。コミュニティバスは今検討していただいていると思うのですが、これらも有効かと思いますが、ご見解はいかがか尋ねました。","respondent":"鈴木都市計画課長、古郡交通安全担当課長","answer":"コミュニティバスの導入に向けた検討を行っておりますが、区民の方の移動の利便性を高めるという意味合いで、非常に有効な取り組みです。一方で、充実した区内の公共交通を補完する意味合いもありますので… 運転免許証の自主返納に関してタクシー代の補助をですけれども、区としては、自主返納については一定程度、周知が進んでいると判断していますので、そういったところは現在は考えておりません。","id":"exchange-059"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひ前向きに、先ほどの１割補助と、あとタクシー代の補助も考えていただきたいと要望いたします。決算書にあります工事費助成の除却５件、フェンス設置２件というのは、他の自治体に比べて多いのでしょうか、少ないのか尋ねました。","respondent":"長尾建築課長","answer":"昨年の１２月から開始しましたブロック塀等安全化支援事業についてです。少なくはないとは感じておりますが、今後も周知をしっかりと継続して行いながら、安全に向けて進めていきたいと考えております。","id":"exchange-060"},{"speaker":"せお委員","kind":"意見","question":"所有者も何かご事情がおありかもしれませんが、こちらは通学路になっています。児童の命を守るためにも、何とかほかにアプローチの方法はないかと考えますが、ご見解を説明を求めました。","respondent":"長尾建築課長","answer":"建物の所有者が登記簿で確認がとれない場合は、土地の所有者の方にご協力いただけるようにお手紙を送ったりする場合もあります。さまざまな形でアプローチしていきたいと考えております。","id":"exchange-061"},{"speaker":"西村委員","kind":"質問","question":"２９７ページ、時間が許せば３１９ページ、公園・児童遊園整備費について伺ってまいります。このような点におきまして、新しくできる大井町駅前公衆便所改築に関してはどのような配慮をされているか尋ねました。","respondent":"溝口公園課長","answer":"防犯カメラを設置して、公園全体を含めて、そういったところに防犯カメラを設置することでの安全対策といったものを図っていきたいと思っているところです。","id":"exchange-062"},{"speaker":"西村委員","kind":"意見","question":"もしわかれば、防犯カメラが何台ぐらい、どのような場所につくのかと、あと入り口の部分が暗いのか明るいのかなど、そういったつくりによっても変わってくると思いますので、わかる範囲でお知らせくださいとの意見を述べました。","respondent":"溝口公園課長","answer":"今現在ですと、やはり２方向から映すことが必要だと考えておりますので、最低２つは設置する形で考えております。設置というか、今後建設が進んでいく中で、必要なものは整備していきたいと考えているところです。","id":"exchange-063"},{"speaker":"西村委員","kind":"質問","question":"区内の公共トイレの防犯性能はいかがでしょうか。区の考えと取り組みを説明を求めました。","respondent":"溝口公園課長","answer":"場合によっては目隠しを設置したり、そういった対応もしているところではあります。皆さんが快適にご利用いただけるようなトイレの整備といったものには、今後も引き続き心がけて取り組んでいきたいと考えております。","id":"exchange-064"},{"speaker":"西村委員","kind":"質問・要望","question":"男の子のトイレは、おしっこをしている姿が見えてしまうということで、セクハラトイレなどと言われ工事をしたという話も伺ったことがあります。特に犯罪のあったトイレなどは、防犯カメラの設置やその他対策がすぐにとられるのかどうか、説明を求めました。","respondent":"溝口公園課長","answer":"さらに昨年度より、品川区内に２６８ある全ての公園に防犯カメラを設置していくという。そういったことを継続してやることによって、トイレも含めまして、安全に公園をご利用いただけるような対策というのはとっているところです。","id":"exchange-065"},{"speaker":"西村委員","kind":"質問","question":"緊急安全点検を、警視庁、行政、園の先生などが一緒に、保育園の散歩ルートを一件ずつ歩いて点検していただいていると伺いました。点検の対象になっているのは何件ぐらいになるか尋ねました。","respondent":"古郡交通安全担当課長","answer":"区の所管で５５園、都の所管で３８園中１５園ということで、区は３０日までに全て点検が終了しています。そういった箇所については、いろいろな啓発看板などを設置したり、安全対策を今後していく予定です。","id":"exchange-066"},{"speaker":"西村委員","kind":"質問","question":"行政側で一緒に同行してくださっているのは区役所職員の方でしょうか。それとも地域コミュニティー団体のようなところの方か尋ねました。","respondent":"古郡交通安全担当課長","answer":"区では交通安全係と、道路管理者の道路課、警察と園の方、あと委託業者がいますので、一緒に回って全て点検したところです。都の管轄では、警視庁本部と、都の福祉保健局の方に来てもらっております。","id":"exchange-067"},{"speaker":"西村委員","kind":"提案","question":"こちらはご提案ではありますが、この点検に区民も参加することは可能でしょうか。さすがに全ての箇所では難しいと思いますが、いかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"現在、緊急的に実施するということで、全ての園が実施していて、既に終わっていますので、区民が参加するというのはできないです。通学路の安全点検も実施していまして、ＰＴＡや地元町会の方に来てもらい実施しています。","id":"exchange-068"},{"speaker":"西村委員","kind":"質問・要望","question":"区民にもぜひ知っていただきたいという気持ちが強くありまして、ツイッターなどでも、ぜひ現在の進捗状況のアップをお願いしたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"提案","question":"間仕切りの協定について、それから３３７ページ、集中豪雨等対策費から罹災証明書について伺いたいと思います。今定例会の一般質問で、区民の自助・共助の意識を高めるために、品川区独自の防災憲章の制定をご提案させていただきましたとの意見を述べました。","respondent":"中島防災課長","answer":"さきの定例会で防災区民憲章についての区の考え方を述べさせていただいたところです。品川区災害対策基本条例の次の段階といいますか、そういうものをさまざま検討する中の一つとして、さきのような答弁をさせていただいたところです。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＮＰＯなど、半年から１年ぐらい検討して、私たちの憲章ということで制定したという経緯を確認させていただきました。ぜひ品川区民のための区民憲章、品川区民のものである区民憲章を策定していただくような手続を踏んでほしいと求めましたが、いかがか尋ねました。","respondent":"中島防災課長","answer":"防災訓練やしながわ防災学校等で研修等も行っておりますので、さまざまな機会を捉えて、自助・共助の意識の醸成を継続してまいりたいと思います。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょうど１年前の決算特別委員会で、自民党の芹澤副委員長とともに、行政書士会との防災協定の締結を求める質問をさせていただきました。品川区については、このような簡易手続、簡易判定についての情報というのはありますか尋ねました。","respondent":"長尾建築課長","answer":"円滑に進めていけるようにということで、ご自身で写真を撮っていただいて、それを申請書に添付していただくというところも示されております。そういったところも含めて総合的に勘案しながら、こういった手法も今後検討していきたいと考えております。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"提案","question":"当然、罹災証明書の発行は区役所の業務ですから、そんなことはできないのですけれども、どういうお手伝いをすればいいのかというところ。１年に１回とは言いませんので、これはやはりボリュームに応じてどういうことが考えられるのかということを、いかがか尋ねました。","respondent":"中島防災課長","answer":"委員にお話しいただいたとおり、罹災証明書の発行・申請業務、その際の相談あるいは申請手続にご協力いただくようなことを考えてあります。連絡先等は当然、交換していますが、内容についても共有を図ってまいりたいと考えています。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"最後に、段ボールによる間仕切りの協定について伺います。ですから、何か工夫をお願いしたいのですが、いかがでしょう。","respondent":"中島防災課長","answer":"平成２９年に、協定に基づいて届けてもらうということをきっちり周知することも含めまして、展示のあり方について検討していきたいと考えています。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に要望ですけれども、これは私も、地域の防災の会議などに出るとお願いするのですが、防災訓練の際に、順番でいいので、そういうものの使用というか展示もお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"３１４ページ、都市開発費、大崎駅周辺地区再開発事業について、東五反田二丁目第３地区再開発について伺います。参加者から出された、計画に対する変更を求める意見について、準備組合からはどのような報告が区にあったのか説明を求めました。","respondent":"稲田都市開発課長","answer":"事業者説明会と通称で呼んでおりますけれども、事業者が地域の皆様方に再開発の説明をしたです。今、議事録を読んでいる段階ですので、今後、説明会の内容等を準備組合と調整をしていきたいと考えています。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"住民参加のまちづくりという発想からは、これは真逆だと私は思うのですけれども、これでよいと思っているのでしょうか。区の考えを伺います。","respondent":"稲田都市開発課長","answer":"準備組合が設立してから３年程度たつのですが、いろいろと話し合って、まちづくりを考えてきているという状況のものです。この地区のまちづくりをやるというところにおきましては、このような建物の大きさや、まちづくりの方針に合った建物等を建てていくです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを、住民参加のまちづくりという点から、これでいいのですかと伺ったので、それについては後でちゃんとお答えほしいと求めました。伺いますけれど、なぜここの地域は、御殿山小学校、日野学園と、２つの学校がありながら、日影規制がないのか。","respondent":"稲田都市開発課長、有馬庶務課長","answer":"建物が２棟建つのですが、それから建物の幅も日陰の方向に向かって細くするというような対応もとってきたところですが、日陰はやはりできてしまう。周辺のビルの陰もあわせて、複合的な陰などにもなるのですけれども… できるだけ日陰の影響が出ないような形で、どういう形になるのかということは確認しながら、話を聞いているです。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"本当に、法に沿った形であればいいという問題ではないと私は思いますけれども、当事者の日野学園やＰＴＡ、校長や保護者、子どもたちへの説明はどのようにされているのか伺います。","respondent":"稲田都市開発課長","answer":"事前の説明は、学校等関係者におきましては、校長先生に私どもが伺って、この内容等を説明してきているというところです。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"都市計画法第１６条第１項に基づく、この原案の段階で、つまり案をつくる段階で開催すべきではないのかと思います。国土交通省の運用指針に基づいて、その開催を求めますが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"建設委員会での資料の表面の３番「今後の予定」というところで、原案の縦覧および説明会、これは第１６条、権利者へ向けての説明会。そういうことで、公聴会の開催等は、予定してございません。","id":"exchange-080"},{"speaker":"松本委員","kind":"質問","question":"私からは、決算書の３２９ページ、建設型区民住宅管理費および借上型区民住宅管理費について伺います。区民住宅については初日にもお伺いしたのですけれども、来年４月から改正民法が施行されるということで、今日もお伺いしたいと思います。","respondent":"森住宅課長","answer":"決算書の滞納委託についてですけれども、残念ながら滞納されている方、あるいは６カ月以上滞納が続いて出ていただいた方について、それぞれ弁護士等への相談であったりということの経費で計上させていただいたものです。","id":"exchange-081"},{"speaker":"松本委員","kind":"確認","question":"今、６カ月という話が出てきまして、今おっしゃったように６カ月という数字が出たかと思います。確認なのですけれど、この６カ月というのは、どの段階が６カ月という認識か尋ねました。","respondent":"森住宅課長","answer":"月１回、６カ月を待つまでもなく、それぞれ相談をお願いし意見を聞いているところです。６カ月という話になりますと、当然それまでに事情をご説明させていただいたり、明け渡し請求に踏み切るかというところのタイミングです。","id":"exchange-082"},{"speaker":"松本委員","kind":"質問","question":"では、内容証明を送るぐらいが大体６カ月と考えてよろしいか尋ねました。","respondent":"森住宅課長","answer":"そのタイミングです。","id":"exchange-083"},{"speaker":"松本委員","kind":"質問","question":"実際に明け渡し請求の訴訟や使用料請求の訴訟を提起されているのは、直近５年ぐらいでいいですけれども、大体何件ぐらいあるものなのか尋ねました。","respondent":"森住宅課長","answer":"昨年度につきましては１件ございました。","id":"exchange-084"},{"speaker":"松本委員","kind":"質問","question":"連帯保証人が資力を失う、品川区立区民住宅条例施行規則第６条２項では、使用者は新たな連帯保証人を立てることというふうになっています。区民住宅の使用開始後、連帯保証人の保証能力の調査はどうなっていますか尋ねました。","respondent":"森住宅課長","answer":"基本的には、入居されるときに連帯保証人をつけていただいて、その方の印鑑がついたもの、それから、滞納があったときにはお支払いしますというような文書をいただいているところです。","id":"exchange-085"},{"speaker":"松本委員","kind":"質問","question":"今のご答弁だと、契約のタイミングになるかと思うのですが、契約をした後には、そんなに調査をしていないという理解でよろしいか尋ねました。","respondent":"森住宅課長","answer":"基本的には連帯保証人の方に請求するタイミング以外で調査はしていないところです。","id":"exchange-086"},{"speaker":"松本委員","kind":"確認","question":"同時に保証能力はちゃんとあるのかも確認したりするのですけれども、保証能力を確認できないというようなことが起こってきて、それが１つ。例えば２年ごとに、保証意思があるのかというようなところは確認していただいたほうがいいのではないかと思いますけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"連帯保証人の資力の確認ですけれども、滞納が始まってから１カ月、２カ月とたつに当たって、連帯保証人にそれぞれ連絡しています。その際に、保証能力についても確認しながら、連帯保証人、それから使用者に対して、滞納額の納入ということをお願いしています。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、そのあたりは、できるだけ確認を、滞納が出てからというよりも、その前のタイミングで確認をとっていただきたいと、これは要望しておきます。これは、区民住宅でも同じことになってくると思うのですけれども、この極度額について、現状の検討状況等があればお伺いできればと思います。","respondent":"森住宅課長","answer":"連帯保証人のあり方といいましょうか、設定の方法について、他区の状況も確認しながら検討を進めているところです。区民住宅の使用料の適切な徴収ということを考えますと、一定程度、他区の状況あるいは都の状況を確認しながら検討していきたいと考えております。","id":"exchange-088"},{"speaker":"松本委員","kind":"意見","question":"ただ一方で民間のほうでも結構気にしているのが、極度額の定めが必要ということで、報道は多分これからどんどんされていくのだと思います。既存の連帯保証人から、極度額を設けてほしいとか、そういった対応方針などがあればお願いいたしますとの意見を述べました。","respondent":"森住宅課長","answer":"新しく契約される方に対してどのような対応をしていくかというところの検討ですが、その辺についてもどういう対応をしていくか、住宅課の中で検討していきたいと思います。","id":"exchange-089"},{"speaker":"松本委員","kind":"質問・要望","question":"経年劣化部は、改正民法では原状回復義務の範囲から外しているのですけれども、任意で原状回復義務を入れることも可能と考えられているようです。なので、これは時間がないので要望というところでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"横山委員","kind":"質問","question":"商店街などの統一された看板は２分の１の減免となりますが、商店街などというのはどのような袖看板でしょうか。平成３０年度に屋外広告物など実態調査を実施しておりますが、どのような看板などが多く、ルールが守られていない主な理由は何か尋ねました。","respondent":"今井土木管理課長","answer":"申請前は９００件程度の許可件数でございましたが、実際に区内全域で調査した結果、未申請が１,０００件程度あるということがわかりました。何らかの改善を求める必要があるということで考えておりまして、主に道路面からの高さの基準を満たしていないところがあるです。","id":"exchange-091"},{"speaker":"横山委員","kind":"意見","question":"占用料を支払っている方と、申請をせずに占用料を支払っていない方がいる現状について、公平性の観点で区のご見解をお聞かせください。袖看板の除去後の持ち主・事業者などへの対応と、不適切な状態に対する措置についても、現状と課題を説明を求めました。","respondent":"今井土木管理課長","answer":"広告物の除去をしていただいた方は既に２０名程度いらっしゃいまして、今後、除去する予定と聞いている方もいらっしゃいます。毎年、目視などをして、不必要な袖看板については撤去していただくなり対応していただきたいと考えております。","id":"exchange-092"},{"speaker":"横山委員","kind":"質問・要望","question":"道路占用許可申請の必要性があることを建築主やテナントなどに周知していただきたいと要望いたしますが、最後、お伺いいたします。大井町などの拠点性のある地域では、居住人口の集中と分散について研究を進めていただきたいと要望いたしますが、区のお考えを説明を求めました。","respondent":"今井土木管理課長、稲田都市開発課長","answer":"今、例示のありました生活衛生課を含めて、ほかに有効なＰＲの所管があれば連携して対応していきたいと考えています。 これは、この拠点の活力をつくるという意味で、さらに発展させていこうというところで進めているところです。さらにどのような方法がいいのか等を、事前に、また引き続き協議しながら進めていきたいと考えております。","id":"exchange-093"},{"speaker":"横山委員","kind":"質問・要望","question":"警察庁、まち全体を防犯に配慮した物につくりかえる絶好の機会であることから、設計段階から防犯に留意して整備することが望まれるなどとあります。まち全体を防犯に配慮したものにつくりかえる絶好の機会と捉えて、安全安心のまちづくりを進めていただきたいと考えますが、一言お願いします。","respondent":"稲田都市開発課長","answer":"市街地再開発事業を進めるに当たりましては、地域の課題が、いろいろあります。そういうさまざまな課題を抽出しながら、もちろん防犯も含めて、まちづくりを進めていきたいと考えております。","id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"３０７ページの水辺利活用事業の舟運社会実験結果検証委託に関連しまして、オリンピックに向けた水辺活用についてお聞きします。品川区も共催されていましたが、イベントを通しまして感想を一言聞かせてもらえますか尋ねました。","respondent":"古巻文化観光課長","answer":"品川区がオリンピック・パラリンピック大会の機運醸成に十分取り組んでいることのアピールができたのではないかと考えております。盛り上がっていったのかと考えていますし、また、さらに来年に向けた期待感も感じさせる２日間だったと考えております。","id":"exchange-095"},{"speaker":"小芝委員","kind":"質問・要望","question":"観光フェスタの記事が載っておりませんでしたので、早目に載せていただければと、これは要望としてお話しします。長くなりましたが、来年のオリンピック・パラリンピックに向けて、湾岸エリアの活用に向けたお考えと、そして舟運へのお考えをお伺いいたします。","respondent":"松本河川下水道課長","answer":"品川区では今、五反田地区に新しい桟橋を設置しておりまして、１２月にオープンする予定です。今、品川区観光振興協議会の水辺部会を利用して意見を聞きながら、いろいろな舟運関係者に使っていただくようなルールを策定しています。","id":"exchange-096"},{"speaker":"小芝委員","kind":"質問","question":"そこで２点質問いたしますが、まず、放流管工事の後、立会川に流れる汚水まじりの雨水の量は大体どの程度まで減るのでしょうか。工事の後の立会川の未来像をどのようにお考えかをお伺いいたします。","respondent":"松本河川下水道課長","answer":"地域住民や地域自治体、ＮＰＯとの連携に基づく、地域づくりと密接にかかわった河川整備を実施するとしています。こういった整備を進めていただくよう、区として早期実施を求めていきたいと考えております。","id":"exchange-097"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、２９７ページの交通安全啓発に関連しまして、自転車の通行の安全についてお聞きします。自転車の通行の安全対策として、現状とこれからの対策を教えていただけますか尋ねました。","respondent":"古郡交通安全担当課長","answer":"３５.２％ということで、都内より若干低いのですけれども、そういった状況です。今後も引き続き、こういった内容で、自転車の安全利用五則とか、そういったものを遵守するような形で実施していきたいと考えております。","id":"exchange-098"},{"speaker":"小芝委員","kind":"質問・要望","question":"区でもぜひとも保護者の皆様に、児童へのヘルメット着用を促していっていただきたいと考えています。これは要望としてお話しします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"３１７ページの戸越公園駅周辺まちづくり事業にかかわって、戸越公園駅周辺まちづくりビジョン基本計画編と、補助２９号線について伺います。この基本計画編のパブリックコメントの意見の数と、どういった意見があったのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"パブリックコメントの意見の通数につきましては、全部で１５５通いただいてあります。その意見には、反対、賛成の意見等もございまして、今、中身について精査しています。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"賛成・反対の数がもしわかれば教えてほしいと求めました。反対の声も賛成の声もあるということで、やはりこの住民の声を受け、どのように修正していくのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"先ほど１５５通ほどいただいたということでお答えいたしました。そのうち、意見は複数ありまして、トータルで考えますと４２３件ほどあります。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"どう反映させていくのかがよくわからないのですけれども、もしさらに答弁がありましたら伺いたいと思います。そして、自分の考えを整理することもできると思いますので、パブリックコメントを行う際に説明会の開催を求めますがいかがでしょう。","respondent":"東野まちづくり立体化担当課長","answer":"パブリックコメントを行う際の説明会の開催ですが、その中で、この基本計画編についてご説明したところです。その際には、地域の町会長、それから地域センターの所長などもお呼びしまして、トータル的に説明を行ってまいりました。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"計画の中身について伺います。対象エリア全体が再開発エリアになってしまうのではないかと思いますが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"もともとのまちづくりビジョンの中におきまして、東地区、西地区、それから南地区、北地区という形で、地区を区切って計画しています。","id":"exchange-103"},{"speaker":"のだて委員","kind":"意見","question":"全体が再開発エリアではないとおっしゃいますが、計画には、戸越公園駅などの公共施設をブランドアップに利用するなどということが書かれております。品川区のまちづくりの冊子にも、この計画の範囲内はやはり再開発の対象となるのではないかと思いますけれども、いかがでしょうとの意見を述べました。","respondent":"東野まちづくり立体化担当課長","answer":"周辺の再開発の状況なども踏まえてですけれども、戸越公園周辺におきましては、現在、駅の南北での開発計画を住民が計画しています。それ以外の再開発の計画というものは、この地区では現在はございません。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"超高層ビルが建てば、逆に歩いて暮らせなくなるのではないでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発ビルにつきましては、風環境も事業者できちんと精査し計画しています。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問・要望","question":"３１１ページ、そして３１５ページ、広町地区整備検討からお伺いしたいと思います。その辺の進捗状況はどうなっているのかということも確認させてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"東京都も複数ルート化について、今後、整備方針を打ち出していくというところも出しておりますので、そうした議論は加速すると。エレベーターのかごの拡大ということになると１５人乗りということも考えられるのですが、こちらについても、委員ご指摘のとおりだと思います。","id":"exchange-106"},{"speaker":"こんの委員","kind":"提案","question":"今、私が要望したところへのエレベーター設置も模索してくださっているというご答弁を伺いましたので、ぜひ引き続きご検討をお願いしたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり利便性を考えると、今ご紹介いただいたように、阪急側の階段が非常に狭い。どういった階段、法的な位置づけになっているかということも確認しながら、これもあわせてＪＲと協議していきたいです。","id":"exchange-107"},{"speaker":"こんの委員","kind":"質問","question":"こちらは、この周辺の補助２６号線、サンピア商店街の前の道路のあり方を今後どうするのかというところを少しお聞きしたいと思います。こうしたことでの交通調査など、そうした混雑状況を調査して、実態把握はされている状況か尋ねました。","respondent":"稲田都市開発課長","answer":"広町地区の検討におきましては、委員がおっしゃるとおり交通問題もあります。そういう中におきまして、現状の交通量を調査したり、それから補助２６号線が開通したり、補助１６３号線とのつながりの関係等々、検討しています。","id":"exchange-108"},{"speaker":"こんの委員","kind":"提案","question":"いろいろな区民の方のお声が入ってくるのですけれども、１つは、ここを一方通行にしたらどうかという、すごく大胆なご意見を言われる方もいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"そして、人口に比べて集会施設が非常に少ないのもこの地域の特徴になっておりますけれども、これについて区はどのような対策をとられますでしょうか。今後、大崎エリアマネジメントとの関係ではどうなるか尋ねました。","respondent":"稲田都市開発課長","answer":"事業者説明会が行われたですが、事務所系で５,０００名から６,０００名ぐらいの通勤者が出るのではないかと、事業者は予想しています。そういうものも検討課題の一つというところだと思います。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひこのハンドブックにも、この分野も入れてほしいと求めましたが、ご見解をお伺いします。それから、下水道の破断については自治体のホームページで確認するようにと書いておりますが、品川区では対応していただけるということか尋ねました。","respondent":"工藤品川区清掃事務所長、中島防災課長","answer":"実態といたしまして、やはり交通機関等の遅れによりまして、収集の開始が３０分から１時間遅れたですけれど、何とかその日の収集を終えたです。やはりそういった気象条件等を十分に考慮しながら適切な判断をして… 仮置き場を定めていくというような地域防災計画にもなっておりますので、それに従って検討していく必要があると思います。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"これは午前中もありました、ゲストでもいいので、スペシャルニーズのある当事者を加えてはいかがかと思います。可能な限りでご答弁をお願いします。","respondent":"鈴木都市計画課長","answer":"八潮地区につきましては、昨年度、アンケートを行いまして、今年度はその結果を地域の方にお知らせし、検討を進めてまいりたいと思います。","id":"exchange-112"},{"speaker":"木村委員","kind":"質問","question":"これは、区内全域にある街路灯は何基で、うち何基が、消えない街路灯として設置されているのでしょうか。普通の街路灯と比べるとどうでしょうかということを、答えるよう求めました。","respondent":"多並道路課長","answer":"災害時にバッテリー用蓄電池で約３日間の夜間、学校避難所、建築中の避難所を除いて５０カ所に１カ所ずつ設置させていただきました。内訳としましては、製品が１基約４４万円、ポールが１６万円、それ以外の設置経費で６０万円ということで、そのような概要となっています。","id":"exchange-113"},{"speaker":"木村委員","kind":"質問","question":"消えない街路灯ですけれども、実際に役に立った事例は、いつごろありましたか。説明を求めました。","respondent":"多並道路課長","answer":"停電が発生した際は、バッテリー駆動に自動で切り替わりまして、電気がつく形になっています。他自治体で導入した事例や、その効果については、今後もまたいろいろ研究・検証はしていかないといけないかと思っているところです。","id":"exchange-114"},{"speaker":"木村委員","kind":"意見","question":"この街路灯は従来の街路灯と違って、街路灯本体にバッテリーユニットを設置するだけの工事と、ネット上で紹介されていました。経済性にもすぐれたものと言われていますけれども、そんなに簡単な工事で、消えない街路灯が設置できるのかどうかお答えくださいとの意見を述べました。","respondent":"多並道路課長","answer":"ただ、やはり一定の期間を超えた場合はバッテリーを交換しなくてはいけないなど、いろいろこれから検証も必要な部分が出てくるかと考えています。今後の整備のあり方というのは、また逐一、考えていきたいと思っているところです。","id":"exchange-115"},{"speaker":"木村委員","kind":"質問","question":"このようなことはないと思いますけれども、大雨が長く続いた場合など、これが３日間以上続いた場合には、電池というものはどうなるのか。そして、曇り空でも充電というのは可能なのかどうかというのを説明を求めました。","respondent":"多並道路課長","answer":"区道はなかなか狭いところが多いので、ソーラーパネルを置いても発電効率が少ないということから、なかなか難しい状況は確認しています。ただ、３日以上の長期間の停電という観点もありますけれども、関係部署とも連携しながら進めていかなければいけないと思っているところです。","id":"exchange-116"},{"speaker":"木村委員","kind":"質問","question":"区内の街路灯は、消えない街路灯というものは何メートル間隔で設置しているのでしょうか。消えない街路灯の弱点は、３日間の日照以外に何かありますか。","respondent":"多並道路課長","answer":"まずは区民の方が災害時でも避難所がどこにあるかというのが見えるようにということで、入り口の前に１カ所つけている状態です。いろいろな機器の状況というのは見ていかなければいけないと考えていますので、今後、検討していきたいと思っているところです。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"次に、３１９ページの上から９行目ですけれども、防犯カメラ設置費からの質問をいたします。最終的には何台が必要と考えて、今、計画しているのか尋ねました。","respondent":"溝口公園課長","answer":"今年度につきましては残りの公園全てに基本的には防犯カメラを設置していきたいということで、設計または工事といったものを進めているところです。委員ご指摘のように、防犯カメラを設置する際には、そういったものも考慮しながら設置を進めてきているところです。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その点のお考えを教えてください。現在の状況と、確かに住宅やマンションが多い中で厳しいということは十分わかっていますが、その辺の方向性と現況を説明を求めました。","respondent":"中島防災課長、溝口公園課長","answer":"区といたしましては、応援・受援という形も考えられますので、さまざまな協定等を結んできております。そういう形でしっかりと受援を受ける、あるいは応援できる、そのような協定について、これからも検討してまいりたいと考えています。古くなりますけれど、平成２６年度に、５年に１遍の、みどりの実態調査を実施しておりまして、その中では２１.４％。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その方たちは直接、２次避難所、開設等の問題もあるとは思うのですがその辺のお考えを教えてください。みどり率を確認させていただいたのは、大変かもしれないですけれど、道路の街路樹がかなり倒れているとお聞きしています。","respondent":"中島防災課長、多並道路課長","answer":"直接避難するということも、点線ではありますが、記しています。例えば避難行動要支援者の個別計画なども推進しておりますので、また、福祉部門ともよく連携を図ってまいりたいと考えています。今年度の対応といたしましては、来年度オリンピック・パラリンピックが予定されているところもありますので、対応していきたいです。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それから、街路樹だけではなく、学校の中で、かなり大きな木が倒れたということも、私は見ていないのですけれども、お話を伺いました。それで駐輪場が使えなかったなどという話もあったのですが、その辺の学校での点検というのはどうなっているのかというのも確認したいと思います。","respondent":"中島防災課長、有馬庶務課長","answer":"基本的には２次避難所という位置づけでございまして、そういう形で、状況によって対応などは考えられるかとは思っているところです。今年の２月初めてボランティアの受け付け訓練を行って、しっかりと具体化に向けて… 今回の台風第１５号による学校での倒木は、枝折れも含めて、中間の報告ですけれども２４本、その後、何本か出ているというようなことです。このうち何本かがそのような大木です。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、３１５ページの広町地区整備検討についてと、３２９ページの空き家対策事業について伺いたいと思います。委託費用、検討経費が幾らかかっているか、平成１６年度からこれまでの総額をまず説明を求めました。","respondent":"稲田都市開発課長","answer":"平成１６年から平成１８年、それから平成２５年から平成３０年度までやってきている状況ですが、総額でいきますと、区が支出したお金は１億７,３００万円余です。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、契約額なども含めてお伺いしたところ、今年度まで入れると、合計で３億円を超えるという経費になります。ＪＲと共同で行ってきた検討とは何か、また区単独で委託して検討してきたことは何か、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"平成１６年から平成１８年の３カ年におきましては、条件の整理、駅周辺の交通の計画、諸制度等の活用の検討等を行ってまいりました。測量等の実施、基盤整備検討、土地利用計画の検討。","id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１５本もの報告書が出されてきたということですけれど、庁内で、広町開発構想を検討する委員会などというのは立ち上げられているのでしょうか。途中、ブランクがあったとしても、１０年間にわたり、これだけの報告書が出されて、これをどこでどう検討されているのかについて伺いたいと思います。","respondent":"稲田都市開発課長","answer":"庁内の検討委員会があるのかです。基本的には、私ども都市開発担当がＪＲと共同検討をやってきているものですが。","id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"庁舎建て替えと開発は切り離して検討すべきだと求めてきましたけれども、先日の一般質問で、議会に提案して議論いただいたので。決定するとしたら、議会の定例会等で行う必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"立木経理課長","answer":"広町地区のまちづくりと庁舎の建て替えにつきましては、基本的には切り離して考えて、今、動いているところです。これは区としてＤ案を提案させていただいたということでございまして、経理課は事務担当をしていますが、区としての提案です。","id":"exchange-125"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、Ｄ案は、品川区として決定したということではないということなのでしょうか。そういうふうに決定したのかどうなのか、そしてまた決定するとしたら、どういう手続が必要なのか、その点について改めて説明を求めました。","respondent":"立木経理課長","answer":"まず広町地区の中で建て替えを検討していくということが、その方向性に、そちらの方向で検討していくということをご報告させていただいたです。今現在はご提案をさせていただいて、その方向で今、検討を進めているという状況です。","id":"exchange-126"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"決定するにはどういう手続が必要なのかということと、なぜ町会長・自治会長などに説明しているのかについてもお聞かせほしいと求めました。","respondent":"立木経理課長","answer":"今後は、そうした部分をしっかり検討会等で詰めてまいりまして、意思決定をしっかりとっていくという段階です。検討を進め始めたというところを、またそこで広く意見を募ることができるというところから、説明に入っているところです。","id":"exchange-127"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことも決まったかのような形で言われているので、これは、誰がいつどこでどんな検討をしたのかについてもお聞かせいただきたい。町会長にも説明しているのかについて質問したので、そのことについても説明を求めました。","respondent":"柏原企画調整課長","answer":"庁舎の検討が今、それから国際化というところに向けても、これは別の観点からトータルの中でずっと検討を続けてきたといったところです。こういった庁舎の検討、今まで検討してきたものを１つ成就させるには、１つ候補地としてなるだろうという考えを持っているというのを。","id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どう考えても順番があべこべだし、庁舎がどうあるべきなのかというのを、これをしっかりと検討していく。そのことこそ、まず第一に行うべきではないかと思うのですけれど、いかがか尋ねました。","respondent":"立木経理課長","answer":"そうした中で、広町地区で今現在動いているものがあります。検討を進めていくという、それから今後、検討会等を立ち上げていくという考え方です。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"３２４ページの建築費に関係して、東京都福祉のまちづくり条例と、不燃化１０年プロジェクトを絡めて質問いたします。その規制というのが、特定整備路線である補助２９号線、補助２８号線、放射２号線にも適用することになるのか、まず、答えるよう求めました。","respondent":"長尾建築課長","answer":"その後、国の法令、バリアフリーの概念をさらに超えてユニバーサルデザインというところを意識したものを整備していくという条例に変わっております。その中でトイレの整備についても、一定程度、整備基準というものが設けられております。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"これは建築課に尋ねたら、定まっているということで、これから指導をちゃんとしていく。不燃化１０年プロジェクト、特定整備路線のところでの、こういう規制が建築に関してかかるということをご存じだったか尋ねました。","respondent":"高梨木密整備推進課長","answer":"補助２８号線沿道では、火災に強い建物を建てていただく方に、木密整備推進課で助成金を交付しております。一般的な建築にかかわるご質問があった際には、同じフロアにある建築課をご案内するなり、そういった形というのが現状です。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"このような状況が、おそらくは木密整備の特定整備路線の中にはたくさんあるのではないでしょうか。関係しているわけですから、しっかりと説明を区民の方々に伝えてほしいと求めましたが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"そういった具体的なご相談がありましたら、建築課として丁寧に対応していきたいと考えています。必要な課との連携につきましても、今後とも引き続き意識してやっていきたいと考えております。","id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"その場合にどういう対応をされるのか。継続的に、これは品川区としての自転車の政策の中では進めるべきだと考えているのか、お答えをお願いします。","respondent":"今井土木管理課長","answer":"それから品川区としても、このシェアサイクル事業につきましては、来年の４月には社会実験から本格実施とする中で進めていきたいと考えています。そして地域交通検討会でも、そのように、区としてはシェアサイクルを新しい交通手段として運営していく必要があると考えています。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"そのときに、やはり運営をしていくのは非常に大変だと勉強させていただいたときがあります。やはりしっかり、品川区としての独自の予算も含めて、事業者の方々と協力して推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"１つは、事務事業概要には平成２６年度が約２０４メートルと整備実績が載っておりますけれども、できれば年度別に教えていただきたい。この確認をさせてください。","respondent":"松本河川下水道課長、長尾建築課長、多並道路課長","answer":"しかし、大雨が降った後には、一時的に臭気や濁りが発生していることは認識しています。オリンピック・パラリンピックを控えているということがありますの… 説明会、防災課が、そちらに同席いたしました。助成対象の中には入っておりませんでしたが、土砂災害警戒区域に関しても助成対象に入れるということで… 平成２９年度が約３４４メートル、年間１００メートルぐらいを基本としながら、道路整備の状況に合わせて点字ブロックの整備を進めているところです。","id":"exchange-135"},{"speaker":"若林委員","kind":"質問・要望","question":"まさに点字ブロックの設置は特定の方が必要とする事業ですので、そういう方のご要望にいかに応えて、かなえていっているか。このバランスというのか、どちらも優先順位が非常に高いという中で、今後、毎年ご要望が出ている。","respondent":"多並道路課長","answer":"今、委員ご指摘の視点は、大井町駅周辺のバリアフリーでの町歩きに際しても、いろいろなご意見があることは承知しています。所管課とよく連携を図りまして、効果的な場所、必要な場所ということで整備を進めてまいりたいと思っているところです。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"決算額６６万３,０００円余なのですけれども、その確認と、マンホールカードを月に何枚ぐらい配布されているのか。そして、今後のマンホールカード、そしてマンホール蓋を含めての、これからの取り組みと設置場所をお知らせほしいと求めました。","respondent":"多並道路課長","answer":"今後の整備の考え方ですけれども、今年度は大井町以外に新たに５カ所設置する予定です。それ以外にも大井町のバリアフリー工事の中で、あと２個ほど、新しく大井町についてもバリエーションを増やしていきたいと思っているところです。","id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは昭和４７年に道路として位置づけられ、昭和６１年から昭和６２年にかけて、現在の形態になっております。これから第１期工事が始まると思うのですけれども、工事の内容、最初の工事の区分というか整備内容を教えてほしいと求めました。","respondent":"多並道路課長","answer":"最初に今年度行う予定のところが第１工区で約１６０メートルで、ちょうど荏原町駅のところというか、そちら側から整備をしたいと考えています。既存の樹木を残しながらも楽しめるような空間ということで、工夫しながら進めていきたいと思っているところです。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこの現状を踏まえて、あの場所をこれからどうするのかということを１つお聞きしたいのと、あと、愛犬家の方もいらっしゃいます。当然、区としてはこれからどういう整備をやっていくのかということと、そういうものも取りつけをするのかどうかということもお聞きしたいと思います。","respondent":"多並道路課長","answer":"区としましては、今お話がありました第１工区、約１６０メートルについては、ベンチはつけないで整備する予定です。なかなか難しいところもあるのですけども、これについては細かいところを今後検討しながら、お話ししながら進めていきたいと思っているところです。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ヒカリの水辺プロジェクトは東京２０２０大会を見据えたプロジェクトだと思うのですけれども、例えば橋梁等のライトアップをしている。今度、契約締結を行ったということなのですけれども、改めてこの取り組み内容をお知らせほしいと求めました。","respondent":"松本河川下水道課長","answer":"平成３０年９月に連携協定をいたしました、今年度発生するＣＯ２の全量をオフセットするものです。９月３０日に高知県と契約締結をいたしまして、１０月１日付で高知県と同時にプレス発表いたしたものです。","id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この取り組みは２３区内で他区もあるのかどうかということをお知らせいただきたいのと、これは１年間分ですが、今後継続的に当然やると思うのですけれども、そこのところを。","respondent":"松本河川下水道課長","answer":"他区での取り組みですが、現在私のほうで把握していますと、足立区や豊島区でカーボンオフセットを実施していることは把握しています。同じように高知県と連携いたしまして、そこで排出するＣＯ２を、このクレジットを使い購入していきたいと考えております。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３１１ページ、開発環境指導要綱等改正検討委託の中で、品川区ワンルーム形式等集合建築物に関する指導要綱について質問します。ワンルーム形式等の住戸の数が１５以上ということなのですけれども、いつから要綱が改正になるのかどうか、お知らせしてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"開発環境指導要綱は昭和６３年に制定、こちらの２つの要綱について、時代の変化等を踏まえた見直しについて検討を進めているところです。検討を一定進めながら、年度内を目途に、その見直しを進めているところです。","id":"exchange-142"},{"speaker":"本多委員","kind":"質問","question":"３１３ページ、不燃化１０年プロジェクト、３２７ページのコンクリートブロック塀等安全化支援を伺います。その辺、平成３０年度の実績は成果報告書でわかりますので、それ以降の取り組みに何か変化などがあったのか、状況を説明を求めました。","respondent":"鈴木都市計画課長","answer":"補助２８号線の特定整備路線３路線を東京都が事業を進めておりますが、例えば補助２８号線で言いますと２８％というところでございまして、周辺の方々も事業にご協力いただいているという結果なのだと理解しています。","id":"exchange-143"},{"speaker":"本多委員","kind":"提案","question":"新しくここに移ったらどうかという提案の場所の土地の金額査定に差額が生じたとき、あり方や総論で伺いますけれども、進めていく中でどういう扱いになるのか説明を求めました。","respondent":"多並用地担当課長","answer":"そのときに、今、ご指摘があったような代替地になる場合があります。以上が基本的な考え方です。","id":"exchange-144"},{"speaker":"本多委員","kind":"質問・要望","question":"あまりスムーズに事が運ばないのではないかと、一般論、総論で質問させていただきました。品川区が今考えているのは、幅員が６メートルの整備ですけれども、建物に影響する場合の建物の補償というところについて詳しく説明を求めました。","respondent":"高梨木密整備推進課長","answer":"今ご案内いただきましたとおり、木密地区で進めております道路整備に伴って、家屋や工作物があたる場合には、その補償を出しています。取り壊しの費用、それと、それをまた新しくつくるのにかかる費用を算定いたしましてお支払いするというような形で進めております。","id":"exchange-145"},{"speaker":"本多委員","kind":"質問・要望","question":"次に、区内の金融機関の事業所内で見かけたのですけれども、そこに木密地域不燃化１０年プロジェクトに関する相談のポスターが貼られていたのです。こうした取り組みというのは、都が金融機関と連携されているのか、区もそういった支援をしているのか、その辺を教えていただきたいのです。","respondent":"高梨木密整備推進課長","answer":"主に不燃化１０年プロジェクトでお支払いしております建物の取り壊し・建て替えに関する助成金のことで、周知徹底を一生懸命やっているところです。金融機関にまずご相談に行かれるという方をターゲットとして、特に区内の金融機関にご協力いただいて、貼らせていただいたです。","id":"exchange-146"},{"speaker":"本多委員","kind":"質問","question":"次の質問にします。品川区のほうの支援をさらにお願いしたいと思うのですが、そこの利用の仕方としてプランターを置くなどはいかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"かねてから議会等を中心にそういった声があるというお話を聞いております。そちらをうまくつなぐ役割を区役所としては担いたいと考えていますので、それを持って、東京都と積極的に協議してまいりたいと思っています。","id":"exchange-147"},{"speaker":"本多委員","kind":"質問","question":"次に、３２７ページのコンクリートブロック塀等安全化支援についてですが、昨年に補正予算を組んで、ブロック塀の除去費助成がスタートしました。第４２条１項道路と第４２項２項道路が対象になっておりますけれども、その後、何か検討などはされていないか説明を求めました。","respondent":"長尾建築課長","answer":"道路沿いのブロック塀等の安全化支援ということで、昨年１２月から、除却と、また安全に配慮した塀の新設について助成しております。道路沿いの塀を除却することとあわせた安全化や除却というところも、あわせてご相談を受けながら、情報提供もしています。","id":"exchange-148"},{"speaker":"本多委員","kind":"質問・要望","question":"そういった意味から、道路境界のみならず隣地境界も視野に入れていただきたい。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"確認","question":"これはどの程度まで浸水を防げるのかということと、周辺の区民の方のお声が区に来ていれば、それが改善されたわけですが、いかがでしょうか。これも重なるかもしれないので確認しますが、燃料が３日分とありますが、空調の利用も含めて３日分の燃料を現状で賄えているのか尋ねました。","respondent":"溝口公園課長、鈴木都市計画課長、松本河川下水道課長、中島防災課長","answer":"シルバー人材センターといったところで、高齢者の雇用というのが１つの目的にありますので、雇用形態は変えずに運営していくと聞いているところです… 今年度は、その中で特に重点的に進めていくところ、これは都の補助金をもらうために、今年度、計画の基礎的なところの検討に着手しています。… 将来的に建設局が予定しております樋門が完成するまでの間、暫定的な高潮対策をするために溢水防止板を設置するものです。高さの設定につきましては… 避難所の発電機の関係です。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"避難所ですが、体育館の空調を想定していないということは、こちらはどのような対応を今後されていくのでしょうか。その点、お尋ねします。","respondent":"鈴木都市計画課長、中島防災課長","answer":"将来的な整備検討をしていくに当たって、国の都市再生整備計画という中で、この辺の具体的な検討を今年度から行っているです。 エアコンも含めまして空調対応ということで、災害時にどこまでのことができるかというのは、検討課題が多々ありますので、今ある設備等を十分研究した上で、今後も考えてまいりたいと考えています。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問","question":"最後の避難所のところですが、もし仮に空調を動かすような発電をした場合、本当に大まかでいいのですが、学校避難所だとどのぐらいの費用がかかりそうか尋ねました。","respondent":"中島防災課長","answer":"まだ試算等しておりませんので、現時点ではわかりません。","id":"exchange-152"},{"speaker":"藤原委員","kind":"確認","question":"令和２年で一応期限は来ますけれども、これこそ続けていく支援制度だと思うのですけれども、その辺についてはいかがでしょうか。確認させてください。","respondent":"古郡交通安全担当課長、多並道路課長、高梨木密整備推進課長、溝口公園課長","answer":"信号のない交差点での優先道路の考え方ですけれども、交通安全教育だとか、そういったところで実施してまいりたいと考えております。来年度も予定していますのが、そこの空間をもう少し広げて、安全に歩ける空間と、今ご指摘があったような、横断歩道も右折するような関係になります… 東京都と連携して、今も鋭意、建物の除却、それと建て替えに対する助成という形で進めしています。","id":"exchange-153"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと不燃化１０年プロジェクトなのですけれど、これもぜひ進めてください。その地域地域で、個々に見ていただきたいと思うのですが、木密についてはご答弁いただけますか。","respondent":"高梨木密整備推進課長","answer":"東京都にもそういったところがあるといったことで、課長級で打ち合わせをするなど、話し合いは継続して東京都とも行っているところです。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、行っても体制がなければ支援は受けられませんので、どういった体制が整えられていくのか伺いたい。要援護者の方が行くわけですから、福祉避難所への備蓄というのは、どういったものがどれぐらいあるのか伺いたいと思います。","respondent":"寺嶋高齢者福祉課長、中島防災課長","answer":"備蓄品に関しましては３日分を想定しておりまして、全ての福祉避難所で受け入れが想定されている人数は約８００名ということになっております。２リットルのペットボトルで３,６００本、それから… 福祉避難所の運営体制についてですが、福祉避難所は社会福祉法人ということでございまして、既に入居等されている方もいらっしゃいます。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"避難しなくても済むように自宅の耐震化を進めていただきたいというのも以前から求めているのですけれども。災害時要援護者の把握は、今まで手挙げ方式でされてきたと思うのですけれども、現在もそうなのか、そこを伺いたいと思います。","respondent":"中島防災課長","answer":"基本的には、その後、個別支援計画等にもつなげていく関係もございまして、やはり本人の同意というのを重要視しております。平常時、訓練等を含めまして、同意をいただいた名簿を活用してまいりたいと考えています。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、個別支援等も進んでいるということですけれども、名簿作成はどれだけ進んでいるのか尋ねました。","respondent":"中島防災課長","answer":"個別支援計画は、避難行動要支援者の支援事業というものを、行っているところです。その中でモデルケースとして作成している個別支援計画につきましては、過去、昨年度までの３年間で、４２人分、作成しております。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、４２件ということでよかったでしょうか。早期に開設できない理由は何なのか、伺いたいと思います。","respondent":"中島防災課長","answer":"対象者の全体としては１万５,１０２名となっているところです。職員の対応も当然ありますし、そちらについてはよく調整して、少しでも改善できるように取り組んでまいりたいと考えています。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"確認","question":"安否確認をし、今、急速に必要だということも言われています。事前の準備、予防の観点から進めていくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"中島防災課長","answer":"先ほど申し上げた個別支援計画でありますとか、さまざまなところ、あと福祉部との連携もよく図りながら、問題については改善するほうへ調整は進めていきます。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"確認","question":"先ほどからの答弁をお聞きすると、５２カ所の避難所で設置されている非常発電機は、冷暖房は厳しいというお話がありました。学校の例えば教室１つ、部屋の１室だけでも冷房が使えるかどうかというのは、確認できていますか尋ねました。","respondent":"中島防災課長","answer":"今年度、新しく配備いたしました蓄電池はリースでございまして、そちらについてはスマートフォンの容量でございまして、部屋の空調などを賄えるような出力があるかどうかというところの具体的な検証などは、まだ実施はしていないところです。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"確認","question":"そういう危険性が出てくるという中で、今あるものが、そういう形で使えるのか、使えないのかというのを、何でこの段階で確認しないのですか。そこをどう確保するのか、もしくは確保しないのだったら、今ある品川区の設備でどこまでできるのかというのをチェックしなければだめじゃないか尋ねました。","respondent":"中島防災課長、曽田災害対策担当部長","answer":"今回の課題は空調というところがクローズアップされて、どのような形の解決策がいいのかというところは、なかなか検討が必要なところです。引き続き、スピード感を持って検討を進めていきたいと考えています。 台風第１５号から１カ月たちまして、我々もこれまでずっと検討してまいりました。電源についても何とか確保したいと、今、考えているところであります。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それで、いざというときに、どうやって確認するのか。そこにそういう内容を書いたものを別途つくってお配りするとか、そういうことをやったらどうか尋ねました。","respondent":"中島防災課長","answer":"トイレの確認方法について、さまざまあるということで、そういうものは冊子というご提案で、ちょっとすぐお答えは難しいですが、そういう形で、今、さまざまなものがあるですので、しっかりとそういうものはＰＲというか周知の中で活用させていただきたいと考えています。","id":"exchange-162"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ほとんど高齢者はもう１０分の１０で、１００％補助になっているわりには、実績はちょっと厳しいようなことも聞いています。我が会派でも要望していますけれども、もっと対象範囲を拡大したらいかがかと思うのですけれど、一応お答えいただきます。","respondent":"中島防災課長","answer":"感震ブレーカーにつきましては、今年度、簡易型を導入したところで、実績については、やはり分電盤のほうが多いところです。エリアに関しましては、引き続き不燃化特区における普及率向上に努めて、今のところ対象拡大は考えていないところです。","id":"exchange-163"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは、３１１ページ、水辺景観重点地区指定検討委託についてお話をさせてほしいと求めました。どういう規制を緩和して、いろいろな形をやっていこうとお考えになっているのか、お聞かせいただきたい。","respondent":"鈴木都市計画課長","answer":"天王洲地区の景観の取り組みですが、１０月１日から天王洲地区を、取り組みがさらに進められていくです。やはり地域のほうで一定程度の方針というか、そうしたところを、地域と一緒に今後も考えていきたいというところはあります。","id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今言った地域の許可の部分と、ここのメリットの部分はどう考えるのかということであれば、そういうほうがいいのではないのかと私は思っております。こういう形になっていくと思うので、その辺を含めてお考えをお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"いろいろなメニューも出てくるのだと思いますので、区としても地域の方の声をお聞きしながら、２件目として手を挙げするか検討していきたいです。今後、このデザイン会議を発展的にどう展開させていくかというのは、地域の方といろいろ意見交換をしながら検討していきたいです。","id":"exchange-165"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大井競馬場をうまく舟運できるように、まずこれを活用していただきたいのと、それにプラスして大井ふ頭中央海浜公園の桟橋もある。オリンピック・パラリンピックのときを１つのきっかけ、そこまで話を進めていただきたいと思うのだけれども、この考え方を。","respondent":"古巻文化観光課長","answer":"来年のオリンピックに際しての舟運の考え方ですけれども、こちらをうまくつなぐような形で舟運を何かできればいいかということは検討しておりますが、まずは期間中何ができるかということをしっかり検討してまいりたいと考えております。","id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私がいろいろな形でお話を伺っていると、議員にも聞くと、どうもみんな弱気だ。私はそう考えておりますので、その辺のお考えをお聞かせいただきたい。","respondent":"鈴木都市計画課長","answer":"３ルート、今、環境アセスメントが進められているところです。そうしたところもいろいろお聞きしながら、やはり新駅については、ＪＲに今後しっかり要望していきたい、意見交換をしていきたいです。","id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"３１４ページ、都市開発費と、３３０ページ、防災費についてお伺いします。品川区は災害時に、千葉県のような対応にならないようにしていらっしゃると思うのですけれども、そこのところの取り組みを説明を求めました。","respondent":"中島防災課長","answer":"区民の生命・身体を守るところを中心としまして、２,５００名で当初はやはり対応せざるを得ないかというところで考えております。その後、応援等も順次入ってくると思いますので、応援職員の協力も入れながら災害の対応に当たるような形で考えております。","id":"exchange-168"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは防災ですから、お伺いしたいと思いますが、先ほど来ありました停電のときにどうするかという質問をさせていただきたいと思うのですけれども。停電は７日間、おおむね３０日かかるというようなことが出ておりますが、どのような想定を役所ではしていらっしゃるのか説明を求めました。","respondent":"稲田都市開発課長","answer":"１２月には１棟完成するというところで来ておりますけれども、やはり階段や、そういうものを使わないといけないという状況は出てくると考えられます。そういう中におきましては、管理組合等々で、そういうコミュニケーション等を使う必要があるのではないかとは考えております。","id":"exchange-169"},{"speaker":"大沢委員","kind":"質問","question":"では我慢してもらえるのか。我慢にも許容限度というのがあるのですけれども、そのあたりのところをどのようにお考えになりますか尋ねました。","respondent":"稲田都市開発課長","answer":"非常電源はあるので、エレベーター等は動くのですが、長期化した場合です。そういうところにおいて、しっかりと、非常時のマンションのあり方等々は話し合っていければと考えています。","id":"exchange-170"},{"speaker":"大沢委員","kind":"意見","question":"非常用の避難通路とか非常用のエレベーターに対応するための非常用電源でありまして、一般用のエレベーターは使えなくなるわけです。そのような状況にあって、居住者の方は大変ご苦労されると思うのですけれども、それに対する対応はどのように考えていらっしゃいますかとの意見を述べました。","respondent":"中島防災課長","answer":"食料、トイレ等の備蓄を、これまでも努めてお願いしてまいりました。区としましては、アドバイザー派遣等を活用しまして、啓発を行っていきたいと考えております。","id":"exchange-171"},{"speaker":"大沢委員","kind":"質問・要望","question":"私が聞いているのは、そのときにどうするかということで、そういうときに迅速にどう対応するかということ。そこらを含みおきいただき計画を立てるなり、今後の議論の焦点にしていただきたいと思うのですけれど、どういうふうにお考えか尋ねました。","respondent":"稲田都市開発課長、中島防災課長","answer":"武蔵小山パルム駅前地区のビルの事例で、各階に居住者用の防災倉庫というのがございまして、そういう形の防災対応というところでは考えております。そこで、ある程度備蓄し、電気が来ないときにも… あくまで自助・共助というところでお願いしていますが、やはり限度があると思います。自助・共助、あと避難所という体制で、災害時の対応をしていきたいと考えています。","id":"exchange-172"},{"speaker":"大沢委員","kind":"確認","question":"自家発電機の点検を委託していて、これは必ずどこのマンションでもされていると思うのですけれど、そこの確認をさせてください。","respondent":"中島防災課長","answer":"やはり今回、台風第１５号による長期間の停電、これまで防災計画上、想定していた以上の長期間の停電という事象でございました。区としましては、新しい課題として捉えて、これまで以上の防災対策の検討を進めていくところで考えていきたいと考えています。","id":"exchange-173"},{"speaker":"大沢委員","kind":"質問・要望","question":"取り組みは再三伺っておりますけれども、どのような対策、対応を立てているのか教えていただきたいのが１つ。ごくまれですけれど、風の強い日に非常によく風が抜けるわけでありまして、そこのところは役所に情報が入っていらっしゃるかどうか説明を求めました。","respondent":"稲田都市開発課長","answer":"設計時点で風洞実験等を行いながら、防風植林等をやってきたのですけれども、今後、完成してから１年間、風をはかるようにしております。風を測定して、計画と実測が違うというところ等は対応していきたいと思います。","id":"exchange-174"},{"speaker":"大沢委員","kind":"意見","question":"最後に、これがキャッチコピーで、「日本一、感じのいいタワマンへ。このタワマンで変わる」と、３つキャッチフレーズがありますけれど、これについての感想を聞かせていただいて最後にいたしますとの意見を述べました。","respondent":"稲田都市開発課長","answer":"販売する会社がそのようなキャッチフレーズをやっているというのは知っております。そういう意味では、武蔵小山が知られていくというキャッチコピーにおいては、努力しているのかと感じます。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/955943?Template=document&Id=1476#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":115694,"voices":399}},{"id":"r01-20191009-4","meetingId":"r01-c-settlement","date":"2019年10月9日","dateIso":"2019-10-09","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件整理しています。","topics":[{"id":"topic-01","title":"◯大倉委員長 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成３０年度品川区一般会計歳入歳出決算","agenda":"◯大倉委員長 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成３０年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"まずは普通学級ですべての児童を受け入れられる態勢を、少しずつで結構ですので整えていただきたいと、まずはざっくりですが要望いたします。目標４８８人と書かれていて、念のためお聞きしますが、なるべく普通学級とは分けてという方向性であったりはしないか尋ねました。","respondent":"大関教育総合支援センター長","answer":"文部科学省では特別支援教育の在り方に関する特別委員会でこれまで議論がなされてきたというふうに認識しています。ぎりぎり検討を重ねた上で、あるいは４月になって入学をした以降も、もう少し話し合いを継続しているようなケースも中にはあります。","id":"exchange-001"},{"speaker":"せお委員","kind":"質問","question":"比較的多くの支援を必要とする児童を想定して準備していただければ、怖いものなしというか、かなり整う方向へ近づくのではないでしょうか。比較的多くの支援が必要な児童である医療的ケア児ですが、品川区での普通学級への受入状況、そして、どのように支援しているのかを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そのような形を進め、これまで９年間、通常学級で過ごしていただいたケースも本区にはあります。その場合には、学習支援員を配置したり、介助員を配置するなど可能な限りの対応を区としてはしてきているところです。","id":"exchange-002"},{"speaker":"せお委員","kind":"提案","question":"こちらを活用しつつ、看護師を配置する学校を少しずつ増やしていくというのはいかがお考えでしょうか。こちらの研修を積極的になるべく多くの職員に受けていただくというのは、今、実施されていますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"医療的ケアの対応のために、２点、お問い合わせいただきました。そちらで都立特別支援学校に看護師を配置し、さらに令和２年度より東京都立の特別支援学校は、特別支援学校に通える部分を実現しますというふうに。","id":"exchange-003"},{"speaker":"せお委員","kind":"質問・要望","question":"大人になってからそれを学ぶのは難しいです。ぜひ品川区から本当の意味のインクルーシブ教育に近づけていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西村委員","kind":"確認","question":"先日の台風第１５号での学校の緊急対応について伺います。例えば、７時を過ぎてホームページを見た保護者は、７時段階で警報が出ていたことをホームページ上で確認できない場合があります。","respondent":"大関教育総合支援センター長","answer":"金曜日あるいは土曜授業の段階で、年度の頭に保護者会等で説明をすると同時に、学校のホームページにもルールについては載っているところです。引き続き、周知に努めてまいりたいと思います。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"さまざまな自治体に確認しますと、今の体制に合わせた保護者すべてに行き届く方法をもう一度ぜひお考えいただきたいと考えています。７時ぴったりに気象庁ホームページを確認できないですとか、品川区のホームページに掲載されていることを知らなかったという親もおりますし。","respondent":"大関教育総合支援センター長、有馬庶務課長","answer":"全体の数ではございませんが、各校１名か２名はいたということで、保護者にご連絡をとらせていただくなど対応したところです。五反田と浜川にも増やしまして、３か所体制で、メニューも増やすような形で工夫をしています。 まもるっちでのメール配信ですけれども、それは現段階では難しいかと考えております。","id":"exchange-006"},{"speaker":"西村委員","kind":"質問・要望","question":"スクール・サポート・スタッフの勤務を強化する予定はあるでしょうか。現在の配置状況と取り組みの評価、次年度以降の展望を伺います。","respondent":"工藤指導課長","answer":"事業開始当初は１５校への配置でございましたけれども、３校を追加し、１８校に配置したところです。引き続き、その内容の検討に時間がかけられるなどの声をいただいておりますので、都の動きを注視しながら拡大を順次要請していきたいと考えています。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問・要望","question":"子どもに関わる大人に余裕があることが子どもの心に大きな影響を与えると思います。ぜひとも引き続き配置をしていただきながら、教職員が余裕を持って児童の対応にあたれるよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"３４５ページ、いじめ防止対策費、３５３ページ、図書館運営費からお伺いいたします。そして義務教育学校、この児童・生徒が子どもの権利条約を学ぶ機会があるのか、どういうところで学んでいるのかをお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"したがいまして、さまざまな機会を通して自分自身の権利は学んでいるところです。３年生において、これは子どもの暴力防止を目的としたワークショップですけれども、さまざまな形で学んでいるところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"何かしら目に触れているところはあるということを確認いたしましたが、子どもの権利条約を学ぶ場を今後もしっかりつくってほしいと求めました。そのことを要望いたしまして、次の質問に移ります。","respondent":"横山品川図書館長","answer":"音訳の資料であるとか、触る絵本であるとか、映像と組み合わせたマルチメディア・デイジー等の提供をいたしております。肢体不自由等身体障害のある方や、要介護等で来館が困難な方のために、自宅へ配本するサービスや郵送するサービスを行っているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"図書館に来ることが困難な方には、これらのサービスが実際に必要とされている方々にどのように周知されているのかということをお伺いすることが１点。必要としている人につながっていく、このようなことも含めて多くの方々への周知の見解を伺います。","respondent":"横山品川図書館長","answer":"製作しました資料のカタログにつきまして、特別支援学校やそのほかの施設について配布をするような形で周知してまいっております。イベントに参加して、いろいろな工作会であるとか、親しみやすいようなイベントを企画しています。","id":"exchange-011"},{"speaker":"新妻委員","kind":"提案","question":"年に２回から３回発行されている非常にセンスのいい広報誌があると思いますけれども、また、さまざまな形の周知方法があるかと思います。これらのことを提案いたしますが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"過去に、ご紹介させていただいたことがあると思います。ＳＮＳにつきましては、そちらを利用させていただき、将来的には図書館専用のアカウントをつくっての周知も検討してまいりたいと思います。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"どうぞご検討していただいて、多くの方が目に触れる場をつくってほしいと求めました。そして、図書館におけるＷｉ－Ｆｉの環境整備についてお伺いいたしますが、現状、どのような整備状況かお知らせください。","respondent":"横山品川図書館長","answer":"今、全館におきましてＷｉ－Ｆｉの設置ができるかどうかの検討をし、準備を進めているところです。近い将来、全館で配備できる可能性があります。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区の中で区が独自に小学校から一斉学力テストを実施している区はどれぐらいあるのか伺いたいと思います。品川区の中学校でも校長先生の判断で定期テストを廃止することは可能なのか伺いたいと思います。","respondent":"工藤指導課長","answer":"逆に、定期テストを行わないかわりに、単元末にそれぞれテストを行っていると伺ってあります。回数としては増えているので、そういった相談が学校からあった場合には、区教育委員会として相談をきちんとしていきたいと考えています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"子どもがなぜ勉強をするのか、私はどうして勉強をするのか、こんなにつまらない話はないと考えています。勉強がテストのためという子どもの勉強の捉え方、これは小学校からの毎年の一斉学力テストがつくっていると思いますが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"まだ不十分であることを認識しながら、またそれを教師が把握し、また必要に応じては補充していくことが可能になるというふうに考えてあります。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"私はよくないと思うのです。一斉学力テストがそれをつくり出している、こう思うのですが、改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"もちろん定着していなければ、学年進行すると次の学年になっておりますが、それは同時に、その前の学年のところがやはり指導の検討ができる。そういったところで学力定着度調査は必要であるという認識です。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、勉強はテストのためにあると、そう捉えさせていることが問題ではないのかと指摘をさせていただきました。学校で獲得すべき学力とは、テスト勉強では学力はつかないと思いますが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"平成３０年度に行いました児童・生徒アンケートでは、仲良くすることができている」という項目に対して、肯定的な回答は８９.７％でございました。年１回という実施回数を含めても、私どもとしては児童・生徒への過度な負担になっているということは考えてございません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"なぜ半径掛ける半径掛ける３.１４で円の面積が計算できるのか、どうすれば円の面積が解けるのか、そこを考える好奇心。だから一斉学力テストはやめるべきだと考えていますが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"ですから、他者とか他校との比較をする、それを意図しているものではないですので、その点は、私ども、そのように認識して行っているものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"年に１回の一斉学力テストでは、その対応ができません。結局、子どもたちをテストの獲得競争に巻き込んでいく、こうした学び方は抜本的に改善すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"筒井委員","kind":"確認","question":"一般質問で、港区への確認をお願いしたところ、石垣の一部に劣化や破壊が生じている状況にあるという認識であると。その後、まだ時間は間もないですけれども、港区との連絡などはあったのか尋ねました。","respondent":"有馬庶務課長","answer":"あそこは区の管轄外ということで、なかなか品川区から何かをしてほしいというような要望を出すことは難しいという史跡です。従来どおりの方法で確認をしてまいりますというふうにお答えをしたつもりでして、今すぐ何か行動をして何か確認したというようなことではありません。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"港区側から何かアプローチがあった場合は、品川区としてはそれには応じるというお考えでよろしいか尋ねました。","respondent":"有馬庶務課長","answer":"そういったことの情報交換の中で何かあればというようなことでは、対応は全然しないというわけではなく、何があればというようなことでの話ということになってくるかと思います。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"仮に崩落したとしたら、どうやって区民、そして子どもたちに説明していくのでしょうか。そして国に対し９３年前の史跡指定、協議会を立ち上げて取り組むべきだと考えておりますけれども、いかがお考えなのか尋ねました。","respondent":"有馬庶務課長","answer":"先ほども申し上げましたとおり、そこの部分について、品川区が何か行動を起こすということは非常に難しいというふうに考えております。したがいまして、港区と何か協議会を設けるというのは、史跡の所在地が違うので、それ自体は難しいかと考えています。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"難しいお立場はあるかと思うのですけれども、ぜひそうしたことは前向きに検討していっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"３５９ページ、２項学校教育費１目学校管理費、学校図書館経費について伺います。区教育委員会のこれまでの説明だと、これからも市民科の評価方法、指導方法は変わらないという認識でよろしいのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今回、国が道徳を特別の教科として教科化する際にも、その根本となった１つのモデルが本区の市民科であるというふうに認識しております。将来的に、教育課程特例ということでこれまで市民科を続けてまいりましたので、本区の必要な教育を推進していく考えに変わりはございません。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"評価方法も変わらない、その変わらないということを改めて明文化して行政文書として残しておいてほしいと求めましたが、その見解を伺います。保護者や住民、教育委員会でのチェックや採択はあるのか、お知らせください。","respondent":"大関教育総合支援センター長","answer":"さらに進めるため、主権者教育などについても新たな単元を教科書のページとして加えるような予定もありますので、進めているところです。１ページ、１ページ取り扱って、今後も適宜進めてまいりたいと考えています。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"市民科の策定過程が外からも見える仕組みを求めますが、見解を伺います。そして、市民科を進める区教育委員会の目的を改めて確認したいと思います。","respondent":"大関教育総合支援センター長","answer":"やはり平成１８年度より実施してきている中で、自分自身の課題を子どもがしっかりと考える、その上で取り組むことが大切である。自身の生き方にまた生かしていく、そういったステップを大切にしていくという部分を大切にするための教えやすい教科書に改訂を進めているところです。","id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"懲戒について、区として事例を把握していますでしょうか。懲戒と体罰の線引き、境についてもあわせて伺います。","respondent":"工藤指導課長","answer":"質問紙調査に合わせながら、学校管理職、私どもでこの体罰に関する本調査において把握していないものはないという認識です。学校のほうで複数の児童等にも伺った上で、これはそれに当たらない、これは叱責であると認識をされているという報告は受けているところはあります。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"区の体罰、暴力の定義を改めて伺います。その周知方法、範囲を伺います。","respondent":"工藤指導課長","answer":"それら対応によっては、具体的に言いますと、傷害行為、危険な暴力行為、暴力行為に分類されるものです。やはり体罰と同様に、それは教育上、不適切な行為であり許されないものという認識ではあります。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"２３区内の自治体と品川区を比べてどうでしょうか。区教育委員会の認識を伺います。","respondent":"横山品川図書館長","answer":"こちらにつきましては、各校に、司書の資格がある者が大体９割以上派遣されているような形で、１週間当たり１５時間配置されております。スタッフがいない時間についてもケアがされないということではなく、学校図書館を有効に活用していただくような形で配備しています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"週５での配置を求めますが、見解を伺います。区として公開の方向性があると認識していますが、教育委員会でも傍聴者への資料提供を求めますが、見解を伺います。","respondent":"横山品川図書館長","answer":"さまざまな方が子どもたちに関わるという場も大切だという認識がありますので、これからより充実させていきたいと考えています。子ども読書活動推進計画策定委員会につきましては、ホームページ等で議事録の公開をする形で周知させていただいているところです。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"私からは、３４１ページ、クラブ・部活動指導員経費について伺います。区内の学校についてお伺いします。","respondent":"大関教育総合支援センター長","answer":"これは学校教育法施行規則第７８条の２に基づく学校のスタッフの一員として、非常勤職ですが、雇用をするという形で配置をしています。一部の私立学校においては、これまでも特定のスポーツに関して、元プロの指導者を指導者として迎えている例などがあるというふうな認識です。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問・要望","question":"今おっしゃいましたけれども、学校からの意見、あとは要望について、どのような声があるか、今後のことも踏まえてお聞かせください。実態として、教職員の負担が減ったかどうか、そのデータとして、例えば労働時間が減少したであるとか、そういった報告がもしあればお知らせください。","respondent":"大関教育総合支援センター長、工藤指導課長","answer":"先ほど、何とかうちの学校にも配置できないか、実は文化部で指導者が困っているというご相談を７月にいただいたというケースがあります。そういった資質という部分を見なければならないので、誰でもいいわけではなくて… ほかにも働き方改革を進めていますので、ただ、その一因として部活動指導員の配置がやはり考えられるところではあります。そういった把握をしています。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"今、データで２２分の短縮というふうにおっしゃいましたでしょうか。そのデータをお聞きしまして、この部活動指導員のおかげで解消はあまりされていないのかどうか、ご見解を説明を求めました。","respondent":"工藤指導課長","answer":"働き方改革として、学校のほかの取り組みでいきますと、一斉にそこは定時でできるだけ帰りましょうと設けたりしているところがあったりもします。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"そのサイトは全国で７００校ぐらいですか、どちらの学校はわからないのですけれども、時給１,８００円という形で募集がされていました。そういった制度の縛りがあるのかどうかと、時給によって指導員の質等が下がったりしないかどうか、そちらの見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ただいま私がご説明申し上げている部活動指導員とは別に、これは小学校で１校当たり３００時間、そちらの受託業者が募集をしている可能性はあります。都からは上限１,６００円までで、本区においては、近隣の他区と同様に１時間当たり２,５００円の設定です。","id":"exchange-034"},{"speaker":"くにば委員","kind":"提案","question":"そちらについては確認します。ですので、こちらの制度をもっと活用して、品川区で先進的な取り組みとして全学校に導入することを提案しますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今年度導入したばかりの本区の状況ですので、現場の意見なども聞きながら検討は進めてまいりたいと思いますし、他区の状況なども研究してまいります。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"３５７ページ、３６１ページ、順不同でお聞きいたします。経営者体験として、ファイナンス・パークなるものを実施しておりますが、この事業の概要について説明を求めました。","respondent":"大関教育総合支援センター長","answer":"実際に子どもたちが自分の生活設計を、保険に入るなどの活動をスチューデント・シティの隣りにブースがありますファイナンス・パークで体験をします。家計簿の実際の運営というような経験をする中で、親子の絆が深まったというような、そのような感想も聞いております。","id":"exchange-036"},{"speaker":"松澤委員","kind":"意見","question":"大変すばらしい取り組みだと思います。担い手不足に悩んでいます技術者の声も生かせる取り組みかと思いますが、体験学習の幅を広げるという意味で、お考えを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ファイナンス・パークなどの施設の取り組みとはまた別で、匠の皆様方、今後とも協力をお願いしたいというふうに各校からは聞いております。見学など、これまでもお願いしてきた経緯がありますので、今後ともそういった部分は大切にしていきたいと考えています。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"幅が広がることを要望して質問を終わります。区固有教員との記載がありましたが、区固有教員と職員、これの違い、また仕事内容に違いがあるのか説明を求めました。","respondent":"工藤指導課長","answer":"区独自で採用している教員ですので、職務内容につきましては都費の教員と全く変わるところはございません。そういった認識です。","id":"exchange-038"},{"speaker":"松澤委員","kind":"質問・要望","question":"各学校に区固有の教職員が配置されることを要望いたしまして質問を終わります。３つ目、校内無線ＬＡＮ整備の進展状況もお願いいたします。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"東京都のプログラミング教育モデル実施校および品川区としてのルネサンス推進事業予算で、今年度まではもう既に配備しています。次年度以降の予定につきましては… こちらを設置してございまして、台数でいきますと、それからパソコン教室のほうには１,７００台ほどのタブレットを今配置している状況があります。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問・要望","question":"やっぱりあってほしいという願いがありますので、多額の予算がかかってしまいますが、全校配布を要望いたしましてこの質問を終わらせていただきます。そういった中、教育委員会としましては、そういった各学校の熱中症対策などで、お考えがありましたら教えていただけますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"どのような状況であれば決断をもって中止すべき、あるいは時間を短くする、水分補給をこまめにするなどという指導を丁寧に進めているところです。各校、状況も違いますので、学校の配当予算の中でテントを増設するなどの工夫は各学校が進めているとろです。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問・要望","question":"これからますます子どもたちの勉強しやすい環境が皆様のお力で整うように要望いたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"小芝委員","kind":"質問","question":"品川区内では、それぞれの学校でおやじの会があると聞いておりますが、品川区では、おやじの会との関係はあるのでしょうか。あくまでＰＴＡの方もいれば、そうでない方もいる組織ですので、なかなか区と接することは少ないと思いますが、お伺いいたします。","respondent":"有馬庶務課長","answer":"そういったＰＴＡの活動の中からおやじの会というものが派生的に出てきていろいろ活動されているというようなことで聞いております。そういった中ですので、直接、区教育委員会とおやじの会で何か委託事業を結んでいるとか、そういったことはございません。","id":"exchange-042"},{"speaker":"小芝委員","kind":"質問・要望","question":"品川区にはぜひともおやじとの会との接点を持っていただきまして、地域発展に努めていただきたいと考えております。改めてましてご所見をお伺いできますか尋ねました。","respondent":"有馬庶務課長、工藤指導課長","answer":"学校で行うファミリーフェスタ、このようなところでいろいろご尽力いただいて、大変活躍していただいていると考えています。学校のそういった活動を通じて… あわせまして、品川区では全校でコミュニティ・スクールの取り組みを行っているところです。地域が協働して、今後も引き続き進める必要があろうかと思いますので、そのような取り組みの中でも進めてまいたいと考えています。","id":"exchange-043"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、３４７ページの副読本印刷についてお聞きします。この副読本の構成と、副読本を通してどのような教育がなされているのかお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"ご紹介いただきました３年生で配付をする『わたしたちの品川』、そういった身近な地域の内容をあわせて学ぶため副読本として作成しています。","id":"exchange-044"},{"speaker":"小芝委員","kind":"質問","question":"当初予算の印刷費が１冊当たり２,０６３円かかってしまって、ほかの副読本は１冊当たりおおむね２００円から５００円の間なのですけれども、別の冊子をつくるからこの経費になるということなのか教えていただけますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"副読本の中には、理科教材などでリーフレット形式のように簡単な印刷物の副読本もあります。３,０００部程度の印刷物になりますため、どうしても１冊当たりの単価は検定教科書とは異なって上がってしまうという実情があります。","id":"exchange-045"},{"speaker":"小芝委員","kind":"質問","question":"品川区の歴史に残る画期的な改革であったと思いますが、創設から今日に至るまでの感想といいますか、ご所見をお伺いできますでしょうか。市民科で教えることのない道徳の項目があれば、それも含めた形で市民科のバージョンアップを図るべきと考えておりますが、ご所見をお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"その当初のねらいはこれからも続けてまいりたいと思います。例えば、国際理解ですとか、そういった部分をさらに拡充していくような市民科としてこれからも大切な核として各学校で学ばせたいと考えています。","id":"exchange-046"},{"speaker":"小芝委員","kind":"質問・要望","question":"生徒たちの意欲に満ちた眼差し、姿勢を見まして、その実学を学ぶ環境に深く感銘を受けたのを覚えております。生徒たちの好奇心を引き出す教育の向上に努めていただきますことを要望いたしまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"東京都は今そういう動きをしていて、東京都全体の流れになっているのですけれども、品川区はどうなのでしょうかと聞かれています。リターナブルなステンレスストロー、そこの点について、なぜステンレスストローが禁止されてしまったのか教えてほしいと求めました。","respondent":"篠田学務課長","answer":"学校給食におけるストローの取り扱いについてです。一見、見た目ではわからないところがあったということもあり、禁止をしたといった経緯があったというふうに聞いておるものです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、そういう一律の扱いはどうなのかなというところと、それでお子さんがショックを受けたということがありました。教育委員会の方で、あの演説を最初から最後までご覧になった方はいらっしゃいますか。","respondent":"大関教育総合支援センター長","answer":"彼女はとても環境を気にしていて、会場まで自分でヨットに乗って来たというところも私は存じ上げております。環境について考えていく、品川をよくするため、これからの大切な題材の一片を教員の一人として見せていただきました。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜあのように怒っていたのか、大人たちはみんな、これからの１０年間で二酸化炭素を５０％削減すると決めたのです。もう一度しっかりと真剣に考えていただきたい、これが今回の質問の趣旨ですけれども、ご答弁をお願いします。","respondent":"篠田学務課長","answer":"ご指摘いただいたとおり、それぞれ学校で必要な対応をとっていくということになっていたのですけれども、改めて徹底をしてまいりたいと思います。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"確認","question":"積算根拠を確認しましたら、専門的講師による市民科等授業１時間につき８,０００円掛ける１日２時間で６校分ということでした。上半期の実績を確認したら、まだ１件も申請がないということでしたが、それについてお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"ご質問いただきました専門家、まちの人々に学ぶ授業だけでは足りない学校等から相談を受けた場合に対応するという内容を今年度予定しています。１学期の時点ではまだ活用がございませんでしたが、１校、まずそれで一部予定しております。","id":"exchange-051"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこでお伺いいたします。給食費の無償化にかかる費用は、今も大体このような金額、大体８億５,０００万円を超える金額であると認識しておいてよろしいか尋ねました。","respondent":"篠田学務課長","answer":"無償化にかかる経費の関係です。それから就学援助額等の実績等を踏まえますと、今の試算では、９億５００万円ほどの金額がかかるという形になってあります。","id":"exchange-052"},{"speaker":"おくの委員","kind":"質問","question":"それからもう１つ、給食費無償化を実質的にカバーしているといわれている就学援助についても少しお伺いいたします。いかがか尋ねました。","respondent":"篠田学務課長","answer":"こちらはいずれにしてもそれぞれの制度の中で必要な方に対応しているものと考えていますので、それを踏まえた形で私どもも対応しているものです。要は、必要であれば申請をしていただけるような形でお配りをしているものです。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"それからもう１つお伺いいたします。お伺いいたします。","respondent":"篠田学務課長","answer":"学務課しかわからない形で対応しますということで周知をしていますので、その辺は特段問題がないものというふうに考えてあります。お子さんが同時に３人以上、その方にご通知を送らせていただいて、ご申請をいただくという形になってあります。","id":"exchange-054"},{"speaker":"おくの委員","kind":"質問・要望","question":"やっぱり相手のあることですから、なかなか難しいという、漏れ落ちるということはあり得る。その線でやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"松本委員","kind":"確認","question":"午前中も体罰についての質問があったかと思いますが、平成３０年度品川区立学校における体罰等の実態把握について確認できればと考えています。議事録を確認いたしますと、重複しない範囲で私も伺いたいのですけれども、こちらをお願いいたします。","respondent":"工藤指導課長","answer":"質問紙調査を行うに当たりましては、通常、学級での指導がありますので、担任が配付をし、担任が回収を行っているところです。","id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"あるいは、１回用紙を持ち帰っていただいて、封筒に入れて提出するみたいなこともほかの自治体ではやっているようなのです。そういったところもぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"今ご提案もいただいたところですが、一応この用紙は、教室で配付ですが、つけ加えますと、２つに折って出しなさいというところではあります。ただ、学校のほうで、特に子どもの意見がとりやすいという方法は考えてまいりたいと考えております。","id":"exchange-057"},{"speaker":"松本委員","kind":"確認","question":"組み体操について、当区議会の議事録を確認しますと、平成２８年度予算特別委員会におきまして、たけうち委員から質問がなされております。確認ですけれども、この当区の区立学校におけるタワー型、ピラミッド型の組み体操の実施校数をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"今年度の実施状況ですが、まず前提となる組み体操を実施する場合は、そちらはすべての学校が守っております。３段ピラミッドをやる予定、あるいは実施した学校が２校、そういうような組み体操が４校というような実施状況です。","id":"exchange-058"},{"speaker":"松本委員","kind":"確認","question":"通知が出たということを確認できてよかったです。ある程度の段数とか下げていらっしゃるということですけれども、その状況での骨折等、けがの発生についてもお伺いできればと思います。","respondent":"大関教育総合支援センター長","answer":"３０件程度はけががある中で、過去３年間で、４件ありました。今年度が１件、確かに１件、組み体操の練習中に転んだことによる骨折はあります。","id":"exchange-059"},{"speaker":"松本委員","kind":"質問","question":"今年の６月ぐらいなのか、何人かの児童・生徒で１人の児童・生徒を、そういうことをするものが最近出てきているというふうに伺っております。この人間起こしについては、実態は把握されておりますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"学級の集団関係を強めるというような目的で演技の中に一部取り入れる学校はこれまでもあったかと思いますが、特にこのトラストフォールについて、これまで調査等はしてございません。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問・要望","question":"今の信頼関係を築くということがどうも目的だというふうなところなのですけれども、とにかくこれは子どもたちの安全を最優先していただければというところで、要望させていただきまして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"横山委員","kind":"質問","question":"１点目に、市民科・各教科充実経費についてお伺いいたします。小学校５年生の国語の教科書に、品川区では、メディアリテラシーの授業をどのように実施していますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"あるいは３・４年生は、５年生以上になりますと、「正しい情報についての理解」という単元があります。Ｂという意見、Ｃという真実、どういうふうに判断すべきかということを市民科の中で学んでいる実情があります。","id":"exchange-062"},{"speaker":"横山委員","kind":"提案","question":"メディアリテラシー教育の強化を要望いたしますが、区のお考えをお聞かせください。子どもたちがお家でお話をしたくなるような工夫など、学校から家庭への働きかけをお願いいたしますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"想像力をしっかりと子どもたちに育み、どういうふうに情報を選択していくかという部分は、とても大切だと教育委員会でも認識しております。","id":"exchange-063"},{"speaker":"横山委員","kind":"質問・要望","question":"確認をさせていただきたいのですが、グループウエアの電子データとして、すべての備品、教材教具を掲載しているということでよろしいでしょうか。学校地域コーディネーターに調整をお願いできるような仕組みになったらいいのかと思うのですけれども、どうなっておりますか尋ねました。","respondent":"篠田学務課長、工藤指導課長","answer":"システム上の登録関係のお話ですけれども、購入価格が１０万円以上の物品に関しましては、すべて備品として財務会計システムに登録されます。それが一番実質的に有効な活用方法なのだろうという形で… 予定されている機能といたしましては、ボランティアあるいは有償スタッフを安定的に供給できるような人材支援バンク機構であるとか、あるいは。","id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"教育長が、昨年１回、しながわ働き方ルネサンスのリーダーである教育長みずからが働き方改革に取り組んで意識改革が進んでいることがわかりました。ぜひそのあたり、研修の充実ですとかを、要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問・要望","question":"双方向型の授業や、アクティブ・ラーニングが求められている中、教育の質の向上や時代が求める新しい学びの実現に有効なものと期待されております。１位が佐賀県の８７.１％、午前中に松澤委員から質問がありましたので承知しておりますが、各校の整備率を教えてほしいと求めました。","respondent":"篠田学務課長","answer":"現実には、これをＩＣＴ推進校以外の学校にも、順次増やしていこうという形で今後対応していく予定です。来年度以降もこれらについては、できるだけさらに充実をさせていきたいと考えているところです。","id":"exchange-066"},{"speaker":"湯澤委員","kind":"意見","question":"大型提示装置の整備率が最下位だった秋田県が１位で、整備率が１位であった佐賀県が４３位という、皮肉な結果が出ております。ＩＣＴ教育に対する保護者たちの意見、子どもたちの反応はどういったものか、あわせてお聞かせほしいと求めました。","respondent":"工藤指導課長","answer":"「当てはまる」あるいは「どちらかといえば当てはまる」と回答している品川区の児童・生徒の平均正答率は高い傾向にあるという結果が出てあります。それについては、今後、保護者の方のご意見なども引き続き私どもでお聞きしながら進めていきたいと考えています。","id":"exchange-067"},{"speaker":"湯澤委員","kind":"質問","question":"２０１８年度の過労死等防止対策白書によりますと、教職員の１人当たりの平均勤務時間は、通常期で１１時間１７分とのことでありました。クラスによっては担当教師が操作を難しいと感じ、ほとんど使いこなせていない、そういったことに対しての対応策などを考えていたら説明を求めました。","respondent":"工藤指導課長","answer":"ＩＣＴ推進校で１人１台のタブレット、学習を行う上での１つのツールである、まさにその観点であるというふうに考えてあります。そのやり方も含めて検討するべきであるというふうには認識していますので、検討し、学校に指導してまいりたいと考えています。","id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そして教師たちの負担軽減、また保護者たちにも理解を求められるよう、より一層の調査研究を引き続きよろしくお願いしたいと思います。こちらの事業内容と成果をお知らせください。","respondent":"大関教育総合支援センター長","answer":"大体２か月ぐらいで、学校で学習を学ぶために必要なある程度の日本語の支援ということで、通えるような支援を行っているところです。１クールで大体の子は大丈夫ですし、９年間のスパンの中でどのタイミングで入ってくるかは個々に差はありますが、支援しています。","id":"exchange-069"},{"speaker":"湯澤委員","kind":"質問","question":"対象となっている子どもたちは何人ぐらいいて、増加傾向にあるかどうか。それから、指導に関しまして問題や課題があれば教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"例年、年間トータルの延べの件数ですが、初期段階のレベルの３か月クールだけで終わるお子さんで５０名前後、さらにＪＳＬ２といいまして、放課後の高等学校受験まで含む内容は、やはり５０件近く、両方トータルしますと１００人ぐらいのお子さんに対応しております。","id":"exchange-070"},{"speaker":"湯澤委員","kind":"提案","question":"そこで、外国人英語講師と日本人英語専科指導員では、指導内容にどういった違いがあるのでしょうか。ほとんど日本語が理解できない外国人と日本人英語専科指導員がペアになって指導を行うことなども提案しますが、ご見解をお願いいたしますとの意見を述べました。","respondent":"工藤指導課長","answer":"その中で、委員ご指摘のように、やりとりの中で学ぶところもあろうかと考えています。３年生以上につきましては、授業づくりが進むという観点で、英語専科指導員は３年生以上に配置をしています。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした状況を区はどう認識されるでしょうか。伺います。","respondent":"大関教育総合支援センター長","answer":"品川区立学校教育要領も区の学校で適切に、各学年、発達段階に応じた内容を一斉指導の中では取り組んでいる実態があります。そのほか、個別の指導、対応が必要なケースにつきましては、ご家庭との共通理解を得ながら個別に対応しているのが本区の実態です。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"この日本の現状は世界から見ても遅れていると、こうした認識はあるのかどうか、もう一度伺います。","respondent":"大関教育総合支援センター長","answer":"委員がご指摘されるのは、リプロダクティブ・ヘルス／ライツという観点からの世界の近年の動きの部分を特に強調されているかと思います。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その前に、どのように妊娠するか、こうしたことを教えることが必要ではないでしょうか。そして都の性教育の手引き、こういったところからどのように妊娠をしていくのか、これは何歳で教えるということになっているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"どちらにもならないということが大切だという社会的な面も、それは性教育の中で触れる内容ですが、性行為自体を指導内容にしているのは高校生段階と学習指導要領では定められております。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"９歳から１２歳、このことを教えるべきですし、世界でも明らかにされている。ぜひ思春期の前の段階にこうした妊娠をどのようにしてしまうのかということを教えていくべきではないか尋ねました。","respondent":"大関教育総合支援センター長","answer":"人間関係ということを、これはまず男女の性の別は問わずに、そこに対する対応をしております。望まぬ妊娠を防ぐための個別の具体的な対応につきましては、一斉指導ではなくて個別の対応を丁寧に進めているところです。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"続いて、子どもたちの歯の健康について伺います。これはいつから変わったのか伺うのと、歯を磨くことがなぜ大切か、小中学校で直接児童たちに教える機会はあるのか尋ねました。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"今、具体的には歯科医師会と連携しまして、８年ほどモデル事業ということで幾つかの学校で昼食後の歯磨き事業に取り組んでまいりました。昨年度から全校で、必ず何らかの形ですべての学校で歯磨きに取り組めるような形で… あるいは養護教諭による声かけなどのほかに、歯磨き粉のメーカーのご協力を得て、歯科衛生士によるインターネット回線を通じた一斉指導を体育館で行った学校などもあります。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"全校でやるべきではないかと私もずっと求めてきていましたので、いろいろ制約がある中ですけれども、全校でということでうれしく思います。歯を健康に保つことにもつながるという歯の構造部分からもぜひ教えていただきたいというふうに思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"６年生の保健の教科書に出てまいりますが、病気の予防という単元があります。その中で歯の病気、口腔衛生の大切さについては学ぶようになっております。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"歯科衛生士も歯科衛生士学校で学校や幼稚園などで指導するという実習もしますので、直接そうしたわかりやすい模型なども使ってやってくれますので、ぜひ歯科衛生士に実際にやっていただく機会を増やしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問","question":"初めに、いじめ防止対策費からお伺いしたいと思います。この事件について、学校をはじめ、子どもの保育、教育に携わる幼稚園、保育園についてもご所見をお伺いいたします。","respondent":"工藤指導課長、佐藤保育課長","answer":"毎月の校長連絡会におきましては、具体的な事例を含めながら資料を提供し、各学校において研修を実施しているところでもあります。ハラスメントの対応等につきましては、ハラスメント窓口を設け、また。 園長、副園長等がコミュニケーションの円滑化を図るとともに、未然防止に努めております。各職層の役割について継続的研修を行うことで、お互いを尊重し合う職場風土の構築に努めております。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうしたことによる先生方の働きやすい環境、学校づくり、これを求めました。この４番目の目標はどのように捉え、今後どのように教育、保育の環境に展開されようとお考えか尋ねました。","respondent":"大関教育総合支援センター長、佐藤保育課長、工藤指導課長","answer":"ＳＤＧｓの取り組みの部分ですが、学力保障をできるための、学ぶための体制づくりという部分は重要な観点だと考えています。… 保育園においての子どもの権利を理解した保育等の実施ですが、各園で、毎年、園運営の全体計画を作成しております。… 子どもたちと向き合う時間にする、またそういったことを持続できるような取り組みとして、働き方改革をさらに進めたいと考えています。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"幼稚園の先生が子どもの人権に関する権利条約をきちんと学ぶことが大事であり、現状はどのようにされているのか、まずお伺いします。教育環境をつくっていただきたい、このように要望いたしますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長、佐藤保育課長","answer":"人権教育の大切さは、これは学校教育、幼稚園教育においてもとても大切な核だと認識しております。品川教育の日を学期に１回行う中で、平成２５年度以降、今後ともこれは充実させていかなければならないと考えております。保育園における子どもの人権に関わる件ですが、それに関しましても、教育委員会と同様、非常に大事だと考えています。","id":"exchange-081"},{"speaker":"こんの委員","kind":"確認","question":"そうした通知が教育委員会のほうにも来ていると思いますけれども、児童・生徒に実際にこれは使われていらっしゃるのでしょうか。自宅学習の実績はありますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"高等学校受験に向けまして、特に中学生段階の不登校傾向のお子さんは、ｅラーニングの形で、学校に申請いただくことでＩＤを配付させていただいて、そのお子さんが、自宅だけでなくマイスクール五反田に来てｅラーニングをやっているなどという事例も出てきてあります。","id":"exchange-082"},{"speaker":"こんの委員","kind":"提案","question":"そして学校やマイスクールからも提案がされたのかどうかわからず、結局そのまま時間が過ぎてしまったという大変に悔やまれたケースがありました。行かなくてもできるような環境づくり、こうしたことを積極的に展開していただきたいと要望いたしますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"校長判断でどのように対応すべきかは今後の研究材料だというふうに現段階では捉えております。もう少し情報収集に努めてまいりたいと思います。","id":"exchange-083"},{"speaker":"あべ委員","kind":"質問","question":"そして３６５ページ、３４３ページの区固有教員と、３４７ページの学力定着度調査経費についても少しお伺いしたいと思います。事故防止と苦情防止の両方の観点から、学年に応じた客観的な判断基準を区教育委員会が示すことが必要だと思いますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長、工藤指導課長","answer":"１点目のお尋ね、おおよそ２、３家庭はそういったご相談をこれまで教育総合支援センターで受けております。そのほか、通訳の方を実際に派遣するなどしております。 私ども教育委員会で行う予定ですのは、公立幼稚園および公立学校のすべての５歳児、競技観戦をするものです。実施にあたりましては、委員にご指摘いただいていますように、やはり暑さ対策が重要であるという観点で考えてあります。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"２つですけれども、今、人数は何人ぐらいいらっしゃいますでしょうか。改めて、公表の目的と、非公表にすることを求めたいと思いますが、いかがか尋ねました。","respondent":"工藤指導課長、大関教育総合支援センター長","answer":"は区固有教員の状況から説明します。そういったところで課題がないよう、私どもは学校のほうに注意してまいりますし… 区固有教員による医療的ケア児童への対応というご提案ですが、都立特別支援学校においても、さまざまな状況等含めまして研究してまいります。都教育委員会とのやりとり必要であるというところで、今、具体的な取り組み内容の検討を始めているところです。","id":"exchange-085"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、３４５ページ、いじめ防止対策費に関連して質問させてほしいと求めました。特に１年生が遊びの延長でいじめ、事実があったのかどうかが、そういった対応があるのかどうかお聞きしたいと思います。","respondent":"大関教育総合支援センター長","answer":"いじめの具体的な対応例ということでお尋ねいただきました。１年生あるいは２年生程度の低学年のお子さんですと、入れてくれなかった、入った時点で１件ずつ丁寧に学校と一緒に子どもへの対応はやっております。","id":"exchange-086"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３年の特に若い先生といいますか、１年生だとなかなか授業態度が、そういう対応をしていただいているということで私は理解できました。心のケアについてお知らせをしてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"子どもへの対応だけでなく、担任からの相談を受けて、担任へのアドバイスをしているケースも結構あります。保護者対応という部分の苦労をどのように、管理職も支えて、そして教育委員会としても支援をしていくことが今後も重要だと認識しております。","id":"exchange-087"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３４９ページ、オリンピック・パラリンピック教育推進事業についてお伺いいたします。５年生を対象にバスで区内オリ・パラ競技場予定地をめぐって、先般、先を見据えて今後どうなっているのかお知らせしてほしいと求めました。","respondent":"工藤指導課長","answer":"来年度、大会の実施に向けて、またその機運を盛り上げる意味でもさまざまな取り組みを計画していきたい。今後のレガシーとしても考えていきたいと思うところもありますので、さまざまなご提案をいただきながら進めていきたいと考えています。","id":"exchange-088"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３６３ページ、学校給食放射性物質検査費についてお伺いいたします。放射性物質不検出、ストロンチウム検査も不検出ということで、他区の現在の取り組みがおわかりになればお知らせをしてほしいと求めました。","respondent":"篠田学務課長","answer":"平成２３年からほとんどの区で実施されておったのですけれども、品川区を除きますと、実施をされているのは１０区ほどというふうに伺っております。正式な形ではないですけれども、一応１０区程度でやっていると聞いておるところです。","id":"exchange-089"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後、安心安全に対する給食というのは、私もすごくわかります。来年度に関しましては、廃止の検討を要望させてほしいと求めましたが、ご見解を。","respondent":"篠田学務課長","answer":"平成２３年度からずっと継続して９年間、給食食材の放射能検査を実施しているのですけれども、１回も検出されたことはないという状況があります。そういったことも今後の展開に向けては十分考えていく必要があるのだろうというふうには認識しています。","id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私も確認し損なったところがあるのですけれども、そこの確認をとりそこなっていたので、教えてください。そこら辺をどう捉えているのかをお聞きしたいと思います。","respondent":"大関教育総合支援センター長、横山品川図書館長","answer":"テクニカルアドバイザーによる学校の授業支援についてのお尋ねです。これはオリンピック・パラリンピック教育とは別に、オリ・パラ以降につきましても、特にそれで影響を受けるものとは考えておりません。図書館の長期基本計画に対する位置づけですが、社会教育の部分は委員ご指摘のとおり、そのような形で進めさせていただこうと考えています。","id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと、こういった事業を続けていってほしいと求めましたが、その辺を教えてください。一番最初に文教委員会に所属して、図書館の中身は大体理解はしていたのですけれども、ちょっとその辺がどうなのかという確認をしたという思いです。","respondent":"工藤指導課長","answer":"委員からご指摘ございました、例えばオリンピアン・パラリンピアンの派遣につきましても、都から派遣をいただくという事業で行ってあります。","id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この辺のところで確認をしたいと思っています。一般の申し込みは７０何名とあったのですけれども、その応募枠がどのぐらいあったのか、どのような選考体制をとっているのか説明を求めました。","respondent":"工藤指導課長","answer":"本事業そのものは、品川国際友好協会が実施しているものですけれども、応募資格としては、派遣時の８年生および９年生を派遣するものです。学校のほうからは、この選考の基準で選ぼうとしても、やはり決めかねる、非常に難しいというお声は聞いているところはあります。","id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ホームステイですから、受け入れする先方の家庭の問題もあるし、できれば１人でも２人でも増やしていっていただきたいという感覚があります。当然、発表会とかをやっているのでしょうけれども、その辺の状況はどうなのか尋ねました。","respondent":"工藤指導課長","answer":"行く前のところから自分が語学研修で学んだ上で、それで学校内では率先してさまざまなことに取り組みたいという意欲を出す生徒が多くあります。その子だけではなく、周りにも波及する、そういった姿勢は各学校で見られているところです。","id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう１点、就学事務費の関係です。どのようにその成果が出ているか、うまく伝わっていると思うのですけれども、そこの確認をさせてください。","respondent":"若生学校施設担当課長","answer":"４月には広報紙に掲載、保護者、お子さんにお届けしたところです。区内１５の中学校区単位で地域説明会、学区域の変更に関する内容をご説明する説明会、私どもとしては認識しています。","id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回、通学区域と学校選択と２つが重なっているので、なかなかわかりにくいと思います。わかりやすくやっているのだけれども、さらにこれからもわかるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３４２ページからの教育指導費の中から、宿題についてと、学校スタンダードについてお聞かせほしいと求めました。２人の小学生の子どもさんをもつお母さんから、合っているかどうかの丸つけまでしなければならないことだということでお話を聞きました。","respondent":"大関教育総合支援センター長","answer":"発達段階に応じて、繰り返し定着していくために、ときには家庭学習も大切な学習場面の１つだというふうに認識しております。課題としましては、学年保護者会などの機会を利用して丁寧に拾っていく部分は今後とも学校と共有してまいりたいと考えています。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう状況になっているというのがかなり負担になっているという、そういう状況があるのではないかという思いがしています。言われたことだけをこなす子ども、言われなければ何もできない子どもを育てることになり、こういう点ではいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"それは子どものうちにしっかりと学んでいくことで、将来、社会に出たときの力強さに結びついていくことだと考えています。学校の授業とは別に、やはり自宅で、そこに対して保護者の方にも可能な範囲でのご協力はお願いしているのが学校の立場です。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"子どもも親も大変負担になっているという点では、改めてそういう点からも見直していただきたいということを要望しておきたいと思います。小学校、中学校それぞれで何校ぐらいでこの学校スタンダードはつくられているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"いずれの学校においても、学校生活におけるルールや決まりは定めているものと考えております。そういったものも入学前の説明会で丁寧にお伝えしている段階から、自分たちの話し合いで解決することの大切さなどを書いている中学校もあります。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、なぜこのようなことを改めて強制するのかということなのですけれども、本当に動物の調教のようだなというのが私の感想なのですけれども。自分の頭で考えない子ども、それから指示待ちの人間をつくっていくのではないかと思いまして、改めて見直していただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと款が違うのですけれども、保育園はどうでしょうか。当初の目的と、それに対しての評価、そして現在の目的は変わっているのでしょうか、いないのか尋ねました。","respondent":"佐藤保育課長、工藤指導課長、篠田学務課長","answer":"給食の放射能の検査の関係ですが、今後予算等の検討をしてまいりますので、教育委員会と連携をとって、さまざま検討をしてまいりたいと思います。ただ、記述で専門性が必要なところについては教員がやるという部分も必要だと考えていますが、そういった実態に合わせながら。… 最初に、これまでの実績等も十分に踏まえながら考えていく必要があるということで、検討をしていきたいということでお答えをしたものです。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、その辺の考え方はどうなのでしょうか。そうなった場合、この学校選択そのものの仕組みをいろいろ考えていかなければならないのではないかというふうに考えますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"当然、学校としても当然それらの保護者の方にきちんと答えられるように、これはもう従前と同じように今後も引き続き対応していくものです。","id":"exchange-102"},{"speaker":"安藤委員","kind":"確認","question":"３６３ページの学校給食放射性物質検査費について関連質問です。そういうものが出ていないということが確認されることが、安心を確認するということになりますので、いかがか尋ねました。","respondent":"篠田学務課長","answer":"他区の状況を見ましても、当初は、２３区で言えばほんどの区で実施されていたのが、今は半分以下になってきているというような状況もあります。","id":"exchange-103"},{"speaker":"安藤委員","kind":"意見","question":"ぜひ保護者の声をしっかり聞いて、昨今の先ほど紹介しましたような社会情勢もあります。よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"平成１１年に増額をされて以降、複数のこういう団体から増額の要望の声をお聞きしましたけれども、これについての考え方をお聞きしたいと思います。続いて、３５１ページの特別支援教育費について伺います。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"やはり医学の進歩等があって、知識等、当時と比べるといろいろと対応すべきものは増えているのだというようなお話をいただきますけれども。平成１１年以降、実は平成１１年当時と比べると… これは国や都が調査している６.５％平均いる中のうち、その数値とほぼ本区における対応は同じ状況となっております。","id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"本来であれば、今、介助員、学習支援員の支援を受けて通級指導学級に行っている子も、もともとは１００％通常の学級で教育を受ける環境があった。どうしても通常の教室から取り出さなければいけないのかと、こういう質問をしたときに、どのようなご答弁になるかお聞きしたい。","respondent":"工藤指導課長","answer":"特別支援教室の場合は、その場合、他校に行くよりも自校でその子どもに合った適切な指導を受けられる。個に合った指導を受ける、そういった体制であるというふうに私どもは認識しているところではあります。","id":"exchange-106"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３４５ページ、順にお伺いしていきたいと思いますので、よろしくお願いいたします。学校におけるインフルエンザ対策についてお伺いいたします。","respondent":"篠田学務課長","answer":"今期のインフルエンザシーズンを迎えるに当たっての教育委員会の認識です。２クラスが学級閉鎖になるという状況ですので、明らかに昨年までよりも２か月ぐらい早いようなペースで学級閉鎖等が発生していると認識しています。","id":"exchange-107"},{"speaker":"鈴木（博）委員","kind":"質問","question":"学級閉鎖は１小学校の３クラスのみのようですが、今後、学級閉鎖等が増加することが予想される憂慮すべき状況に既になっていると思われます。品川区の学校では、どのような対策や備えを家庭や学校で行ったらよいのかというような内容の授業は、現在行われているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"学校では、保健だよりなどを通じてご家庭にも働きかけを行ってありますが、インフルエンザだけに特化した学習内容の単元は授業としてはございません。なお、６年生の保健で、教科書を用いて病気の予防について学ぶ際に、インフルエンザについては触れる可能性はあります。","id":"exchange-108"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ぜひ授業等を利用して周知啓発をお願いしたいと思います。皆勤賞というものが現在も残っているかどうかもあわせてご説明をお願いします。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"これまでの経験則的に、おおむね学級在籍者数の２割のお子さんがお休みになると学級閉鎖を検討して、実際に学級閉鎖になる例が多くなってあります。ただ、実際には… 皆勤賞という制度があるかというお尋ねですが、区教育委員会として公式に皆勤賞という制度はございません。個別にお子さんがご自身の目標として、学校全体あるいは区教育委員会として皆勤賞を表彰するようなことはございません。","id":"exchange-109"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"Ｑ４、児童生徒に症状がない場合もしくは軽度の発熱等だった場合もインフルエンザの検査をしたほうがいいのでしょうか。どのように学校側に指導や周知を行っているのか、いま一度、ご説明をお願いしたいと思います。","respondent":"篠田学務課長","answer":"委員からお話があったような不適切な検査等を行わないようにというような指導は今までも行ってきているところですけれども、引き続き、指導してまいりたいと考えているところです。","id":"exchange-110"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"文部科学省の見解も十分に踏まえた上で、実効性のある感染症対策が実施されることを期待して、次の質問に移りたいと思います。青少年の自殺に対する教育委員会の現状認識、学校現場での自殺予防教育の現状をご説明ください。","respondent":"大関教育総合支援センター長","answer":"自殺予防教育ですが、委員ご案内のとおり、本区の若年層における自殺予防対策は、教育委員会としても重要な課題の１つであると認識しております。悩みの解消方法について、そのような単元、あるいはＳＯＳの出し方などを通じて予防を図っているところです。","id":"exchange-111"},{"speaker":"鈴木（博）委員","kind":"質問","question":"教育総合支援センターは、保健予防課などとともに、教職員等のゲートキーパー研修を担当されているとお聞きしています。ゲートキーパー研修の実効性について、教育委員会が特に気をつけている点について、ご説明を簡潔にお願いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"平成２９年は４２人、平成３０年度は４７人が受講し、今年度も５３人が既にゲートキーパー研修を受講しております。ＰＴＡにも多く研修会に参加していただいておりますので、関係課とも協力してご案内してまいりたいと考えています。","id":"exchange-112"},{"speaker":"鈴木（博）委員","kind":"意見","question":"その多くは防ぐことができる社会的な問題であるという認識で、今後も引き続き、精力的なご努力をお願いしたいと思います。時間がありませんので、食物アレルギーに関しては、エピペンの使用があったかどうかだけ、一言、お答えをお願いいたしますとの意見を述べました。","respondent":"篠田学務課長","answer":"昨年度に関しましては、エピペンを使用するようなアレルギーの症状が発症したお子さんはいらっしゃらなかったです。","id":"exchange-113"},{"speaker":"鈴木（博）委員","kind":"意見","question":"エピペンの使用がなかったということは非常によかったと思います。エピペンは練習をしないとできなくなるので、練習を繰り返してお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"本多委員","kind":"質問","question":"３３８ページから全体にかけて、教員について、３４２ページ、教育指導費、プール、水泳指導について、３４７ページ、市民科について伺います。こうした背景について、その経緯を伺うのと、教師の日制定にある趣旨について、どう受け、どう感じるのか、答えるよう求めました。","respondent":"工藤指導課長","answer":"ただいま委員からご紹介いただきました９月４日、教師の日にというところは、報道でも私ども存じ上げているところです。その趣旨を踏まえながら、またいずれは教員採用選考等の倍率が増えていくことが見込まれるのであればというところで感じておるところです。","id":"exchange-115"},{"speaker":"本多委員","kind":"質問・要望","question":"あわせて聞きます。ぜひ注視をしてほしいと求めましたので、そういった新しい動きの情報収集とか、その辺についてだけ、答えるよう求めました。","respondent":"工藤指導課長","answer":"ただいまご案内いただきました内容についても、私ども、報道等を通じて把握しているところではあります。私どもも本区の教育行政に生かしていける部分があるかという観点からも検討をする部分も含めて国の動きを注視していきたいと考えています。","id":"exchange-116"},{"speaker":"本多委員","kind":"質問・要望","question":"今の文部科学大臣や内閣の動きですと、一気に進むと思いますので、ぜひ注視をしてほしいと求めました。３４２ページの教育指導費、設備維持は問題ないと思いますけれども、その辺についての見解を説明を求めました。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"現在、品川区でプール指導をしているのが、夏期休業中です。この間、そういった限定された期間の話ですので、今までどおりの形で今後も続けていけるのかと考えているところです。 授業の中でのプールの指導は、体育の中で８時間から１０時間程度は扱っております。その際、複数で見る必要がありますので、小学校へ配置しているテクニカルアドバイザーなどが担任と一緒にプール指導に当たるケースもあります。","id":"exchange-117"},{"speaker":"本多委員","kind":"質問","question":"２つ目は、国歌「君が代」につきましては、『古今和歌集』や雅楽より生まれた点、長い歴史があって国歌制定がされました。２点説明を求めました。","respondent":"大関教育総合支援センター長","answer":"現状の歴史などの学習に加えて、新たに次年度以降、改訂した市民科の教科書の活用の仕方の中で工夫してまいりたいと思います。自分の取り組み目標の中において、あるいは、指導の仕方については研究してまいりたいと思います。","id":"exchange-118"},{"speaker":"本多委員","kind":"質問・要望","question":"やはりそういう日本の国際理解教育を進める中で、日本というものをしっかりと教えてほしいと求めました。それで今、国歌は、音楽でやっていることは承知しておりますが、経緯、歴史などもあり方として教えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"こちらに出場することに対する教育委員会としての全国大会出場に関する支援はどのような項目で、どのような形が行われたのでしょうか。こちらの全国大会出場に関する支援は、助成というのでしょうか、教育委員会ではどのような形で行う予定か尋ねました。","respondent":"篠田学務課長","answer":"今回、委員ご案内のとおり、１０月１４日に全国大会が開かれます。こちらはＮＨＫホールで開かれるのですけれども、こちらもそこまでの交通費を区で負担をするものです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"財政課になるのでしょうか、そちらのお考えを伺います。それからもう１つ、働き方改革ですが、今回の臨時国会で、教育職員の給与に関する特別措置法の改正案が文部科学省から提出されると伺っております。","respondent":"若生学校施設担当課長、品川財政課長、工藤指導課長","answer":"進めていく中では、指導を行ったところでございまして、再発防止等に努めているところです。今後こういったことがないように… まだまだ進めなければいけない部分があります。そのような考えです。 その辺のところは法改正を含めて都教育委員会とも連携を進めているところもありますが、現状では国の動き、あるいは都の動きを注視しています。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つは、今回学区のいろいろな変更がありましたけれども、そこの確認が１つ。今年度と約２億円という予算が計上されていますが、そのあたりの充実が必要と考えますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"２点目の特別支援教室の対応の児童が増えている状況、学習支援員の必要なお子さんはやはり多くなっているところです。これはやはり共生社会の実現のために必要な支援は今後とも充実させたいと考えております。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"確認","question":"特別支援学級の学区については、小学校の学区とは別に、いわゆる学区の縛りがなく特別支援学級を選べるという認識でよろしいのでしょうか。その確認。","respondent":"大関教育総合支援センター長","answer":"学校選択の学区とは別な形で、特別支援学級としての学区を示していますので、それがベースとなっております。は個別に相談を就学相談の中でしています。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"３４２ページ、教育指導費全般についてお聞きしたいと思います。説明を求めました。","respondent":"工藤指導課長","answer":"選択先は、各家庭の方針もありますので、私立を選択するということはあろうとは思っているところです。３校種体制、非常に重要であるというふうに認識していますので、私どもが選ばれるようにというところを考えて進めていくという認識です。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"それを今、課長は、聞かない、知るところではありませんと、これはどういうことですか。では、この人たちのニーズをやっぱり教育者、教育委員会ならば、取り込むべきではないか尋ねました。","respondent":"工藤指導課長","answer":"その学校を設置し、そういった役割を果たすべきというふうに考えてありますので、私ども公教育を選んでいただく。その中身の充実を含めて進めていくという考えです。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問・要望","question":"その子どもたちはまだまだ、成長過程ですから、どうしたらいいかわからない。だから、そういう意味で、教育委員会の手助けをこれからもしっかり考えてやってきてほしいのですが、この見解についてどのように思っておられますか。","respondent":"工藤指導課長","answer":"例えば前半のところで言っていただきました学力の捉え、見通しを持ってというところは、まさにそのとおりであるというふうに認識しています。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"ご存じかどうか、これは見解をお聞きしたいのですが、だんだん狭くなっていきます。こういうことを教育委員会としては、しっかり把握されているのか尋ねました。","respondent":"工藤指導課長","answer":"その人物を重視される観点で言えば、資質能力をしっかり身につけ、新たな課題が見つかった場合。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"今、課長がおっしゃったからお聞きしているのですが、皆さん、平均点、学力が今、品川区は高いとお思いですか。そういうところはどうなのですか、今、もう一度お聞きします。","respondent":"工藤指導課長","answer":"もちろん教科間によってはさまざまありますけれども、例えば数学においては、７年生から８年生にいくにつれて、やはりＣ層、Ｄ層が増えてしまいます。現在、今年度の結果についてもそういった分析を進めているところですので、いずれまた報告したいと考えています。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"改善されていないではないですか。教育委員会がもっと身近にいるのですから、多くの生徒の点数とか学力を把握して、しっかり上の高校に送ってあげられるように今後努力してください。","respondent":"中島防災課長","answer":"ご報告いたします。先ほど、４時４８分、東京２３区、震度３の地震がありましたが、品川区の震度計におきましては震度１ということでございました。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問","question":"３４５ページの教職員支援経費に関連して、１年生への支援員配置について伺います。保健室や図書館登校をしている子どもの数と、どういう支援を区では行っているのか伺います。","respondent":"大関教育総合支援センター長","answer":"さまざまなご家庭の考え方ということで、逆に、朝起きることが難しいというケースも近年は教育相談室に保護者から相談を受けるケースなどもあります。個別の対応をして、必要に応じて特別支援教室を活用していただくケースもありますし、そのような丁寧な対応をしています。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問・要望","question":"保健室登校などをしている子どもの数がわかりましたらご答弁をほしいと求めました。その支援についても、もう一度お願いいたします。","respondent":"大関教育総合支援センター長","answer":"当然、１学期間は乗り切っても、２学期ぐらいには累積では３０日になってしまうような実態が結果的にはあります。そういったことへの支援ということは、マイスクール八潮、五反田、浜川の活用などをしていただいているところです。","id":"exchange-131"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間の事例について、不登校などの現象と、いじめや家庭環境などの原因の細かな分析が必要だと思いますが、いかがでしょうか。中学校在学中の不登校による欠席を高校入試のマイナス材料にしないようにすべきだと思いますけれども、これも伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"不安傾向、ここがクロスすると、やはり不登校のケースがあるということで高くなっております。ご自分だけでは難しい、また、なかなか起こしてくれる環境にもないようなご家庭だと難しかったりなどということも中にはあろうかと思います。","id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校に行かなくてもよいのか、行かないと将来どうなってしまうかなど、また、日々の事態にどう対処すればいいのか不安になってしまうと思います。不登校の相談窓口や親の会設立への支援が必要ではないかと思いますけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"先ほどご説明が漏れておりましたが、そういった情報は積極的に不登校の相談の保護者や本人に対しても示しています。そのような人生の先輩を招いて体験談を聞いたり、どのようなことがポイントだったのか、そのようなことを話すなどという機会も設けたりしています。","id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問・要望","question":"区民の方からご要望いただいて、なかなかまだ進まない状況があるようにも聞いているので、その辺の事情を教えてください。全て無事に終わったかどうかの確認と、それをどのような形で使っていくのか等、説明を求めました。","respondent":"篠田学務課長、横山品川図書館長、有馬庶務課長","answer":"給食費の補助ということで、あくまで制度は別物ですので、ここら辺はそちらと連動した形で変更をするものではございません。… ブラインドをつけることを今検討しているところなのですが、あと、遮光フィルムの設置もあわせて検討しているような状況です。… 体育館の空調ですけれども、今年度予定しておりました工事は全て完了しております。","id":"exchange-134"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういうことでわかっていた上で今後どうするのかとお聞きしたいのですけれども、今後、これは要望に留めておきます。スポットクーラーについては、リースですけれども、これはもうそろそろ一端お返しするのか尋ねました。","respondent":"有馬庶務課長","answer":"今年度全部はできなかったので、その学校については、来年、再来年で早急に整備をしていこうと考えております。申しわけないのですけれども、冬の間は従来どおり、ストーブ等で対応していただこうというふうに考えております。","id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"その上で、昨日、体育館だけではないのですけれども、停電時の非常用発電機の件で質疑させていただいて、教育委員会の学校のほうの設備ということですので、教育委員会として何か停電時に対応等のお考えがあるかどうか説明を求めました。","respondent":"有馬庶務課長","answer":"これを空調のほうに電源を回すということは、今のところ、なかなか難しいという結論になっております。一応、どういう方法がいいのかということはいろいろこれからも検討をしていきたいと考えているところです。","id":"exchange-136"},{"speaker":"たけうち委員","kind":"質問・要望","question":"なかなか課題が多いかと思いますが、いろいろな方法でぜひ早急に防災課ともまたさらに連携をとっていただいて検討いただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"意見","question":"教育というのは、そういう形の中で教育委員会は努力もされていると思うので、こういう評価をちゃんといろいろなところで言うべきだと思う。ここら辺の感覚をぜひもう一度お話をいただきますとの意見を述べました。","respondent":"工藤指導課長","answer":"常日ごろから地域と連携した取り組みを進めている、また支援をしていただく、あとは学校を支援する学校支援地域本部の仕組み。常に課題等を共有しながら同じ方向性を向いている、これからもそういった取り組み、地域も含めた取り組みを進めていきたいと考えているところです。","id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここら辺は地域クラブも含めていろいろ連携してほしい。あまり７～９年生は、地域との関係は少し考えていただきたいと思っていて、そこら辺のところをご見解をいただきたい。","respondent":"工藤指導課長","answer":"そういったところを課題として、それを改善に向けて私どもも取り組んでいきたいというふうに考えているところです。小学校・中学校でのコミュニティ・スクールとの連携のあり方も、今後、そういったところも踏まえて体制整備の充実に努めてまいりたいと考えています。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"意見","question":"私もそういう方とは何回か、そういう方が担任になったときがあるけれども、それはやっぱり大変です。もう少しそういう期間を少し長くしたり、そういうことをしていくという方向が私はいいと思うのだけれども、そこら辺の考えを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"現状ですが、１年目に初任者研修、その後、２年目、３年目もあわせまして、若手教員研修という形で、今、取り組んでいる実態があります。関係機関との連携ですとか、そういったものを年間でも６０時間以上行ったりしていますので、今後とも充実してまいりたいと思います。","id":"exchange-140"},{"speaker":"大沢委員","kind":"質問・要望","question":"３４９ページ、英語教育、それと３５３ページの図書館ということで伺います。それとも何とかという研究機関が決めるのか、あるいは業者が決めているのか、どこが判断しているのか説明を求めました。","respondent":"横山品川図書館長","answer":"品川図書館におきましては、ヤング・アダルトのコーナーをつくっておりまして、こちらは児童図書の担当者が選書ほか配架をしております。区独自の制度です。","id":"exchange-141"},{"speaker":"大沢委員","kind":"質問・要望","question":"アメリカだと１３から２０歳と非常に幅があるような形でありますが、魅力のあるヤング・アダルトコーナーをつくってほしいと求めました。それと次に、在日あるいは在留外国人に対する図書館の受け入れに対する考え方を説明を求めました。","respondent":"横山品川図書館長","answer":"外国の方の対応につきましては、品川図書館ほかに外国語資料等を置きまして、そちらをご案内しています。対応につきましても、これからの対応につきましては、実務で対応できるような職員を育成するような形で検討を進めていきたいと考えています。","id":"exchange-142"},{"speaker":"大沢委員","kind":"質問・要望","question":"おそらく図書館、グローバルに、どのところでも対応できるような受入態勢はつくってほしいと求めました。英語教育現場の中で、品川区はスラングについて、どのような取り扱いをされているか説明を求めました。","respondent":"工藤指導課長","answer":"コミュニケーションをとることが大事であるというふうに認識していますので、９年生、特に８年生はオンラインレッスンなどを行っておりますので。","id":"exchange-143"},{"speaker":"大沢委員","kind":"質問","question":"帰国子女なりが２か月ぐらいお友達と話せれば、「やばい」とか、そういうような言葉だと思います。まさにスラングとして受け入れるわけですから、言葉に対する好奇心をくすぐりながら、そこらについて感想を説明を求めました。","respondent":"工藤指導課長","answer":"ご指摘いただいたところです。そういった意味のいわゆる教養の部分であっても、やりとり等を通じながら、それを習得していっていただきたいと考えているところがあります。","id":"exchange-144"},{"speaker":"大沢委員","kind":"質問","question":"これで質問は終わりますが、返す返すですけれども、さらなる品川区の公教育の発展、進化を期待して、私の質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/955943?Template=document&Id=1478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":123949,"voices":345}},{"id":"r01-20191016-4","meetingId":"r01-c-settlement","date":"2019年10月16日","dateIso":"2019-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を114件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"委員長の許可を得られましたので、途中、スライドを３枚、供覧しますので、よろしくお願いいたします。子宮頸がんとはどのような病気なのか、ご説明をお願いいたします。","respondent":"福内健康推進部長","answer":"正常な状態からすぐにがんになるのではなく、異形成と言われる、がんになる前の状態を何年か経てから、がんとなります。子宮頸がんの発生には、その奥に、ＨＰＶ、ヒトパピローマウイルスの感染が関連しております。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子宮頸がんは、我が国では年間１万９００人が発病し、２,９００人が亡くなっています。この子宮頸がんの現在の治療とその成績はいかがか尋ねました。","respondent":"福内健康推進部長","answer":"進行すると、子宮はもとより、卵巣やリンパ節まで広い範囲を全て切除する手術が必要となります。２００９年から２０１０年の診断例の５年生存率で治療成績を見ますと、早期のがん１期では９３.２％、進行期４期では２３.９％です。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"意見","question":"この円錐切除術を、現在、我が国では、年間９,０００人を超える女性が受けているのです。あわせて、低迷する子宮がん検診に対する国および品川区の認識をご説明くださいとの意見を述べました。","respondent":"福内健康推進部長","answer":"がん検診受診に対する取り組みは、国においては、がん検診のあり方に関する検討会において、受診率向上について議論されております。二十歳からの子宮がん検診のご案内により若年層の啓発にも取り組むほか、これは３月１日から３月８日ですが、がん検診のご案内を発信しています。","id":"exchange-003"},{"speaker":"鈴木（博）委員","kind":"質問","question":"前がん状態や、がんを診断できる感度は５０％から７０％と言われており、５人に１人は見逃されている可能性があります。子宮がん検診は大切ながん対策ですが、その効果と限界について、区はどのようにご認識されているのか尋ねました。","respondent":"福内健康推進部長","answer":"検診の限界としては、検査の精度は１００％ではなく、がんが見逃される場合もあります。死亡に至らないものも含まれており、こうした病変を見つけてしまうことで、結果的に必要以上の検査や治療が行われることもあり得ます。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ちなみに我が国では１６例です、２０６６年には１０万人当たり１例未満と、先進国の中で最初に子宮頸がんを撲滅する国になると言われています。現在のＨＰＶワクチンの接種数と最近の傾向についてお知らせくださいとの意見を述べました。","respondent":"福内健康推進部長","answer":"平成２５年から、小学校６年生から高校１年生の女子を対象に定期接種が開始されました。少しは増えているような状況です。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"意見","question":"身体の一部が勝手に動く不随意運動など多様な症状が、厚生労働省はＨＰＶワクチンの定期接種としての積極的勧奨を６か月をめどに一時停止しました。この症状に対する国際的な評価はいかがなものか、ご説明をお願いいたしますとの意見を述べました。","respondent":"福内健康推進部長","answer":"国においては、厚生科学審議会予防接種・ワクチン分科会で検討が続いております。国際的には、ＷＨＯ、世界保健機関が、ワクチン接種者における慢性疼痛等の症状は、ワクチン製剤そのものには関連しないと結論づけているところです。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ＨＰＶワクチンについて、全ての品川区民、特に若い女性の区民に必要な情報を届けてほしい。対象者は無料接種ができるという事実に基づく客観的な情報を、区民に積極的に提供することを切に望みますが、区のご見解はいかがか尋ねました。","respondent":"福内健康推進部長","answer":"ＨＰＶワクチン接種に関する正しい情報を発信することは重要と考えております。厚生労働省が作成いたしました、ＨＰＶワクチン接種の意義と効果に関するパンフレットへリンクを貼るなど、区民への啓発に努めているところです。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これらの接種漏れの人々に、ＨＰＶワクチン接種費用の助成を検討すべきと考えますが、区のお考えはいかがでしょうか。これらの接種漏れの人々への子宮がん検診の勧奨について、区はどのようにお考えか尋ねました。","respondent":"福内健康推進部長","answer":"ＨＰＶワクチンの積極的な接種勧奨につきましては、国で慎重に検討するとしており、今後の動向を見守ってまいります。子宮頸がん検診につきましては、特に若い方たちにも情報が行き届くよう、これまで以上に普及啓発に努めてまいります。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、若い女性の命と未来を奪う子宮頸がんを予防するために、ＨＰＶワクチンの接種と子宮がん検診の重要性を中学校、義務教育学校後期課程の生徒に学習させることこそ、真のがん教育だと確信いたしますが、区のご見解はいかがか尋ねました。","respondent":"本城教育次長","answer":"子どもたちがみずからの健康について考え、学ぶ機会は、大切であると認識しています。今後の研究課題の一つとなりますが、区の保健所とも連携するとともに、これからも医学の進展や社会の動向等を注視してまいりたいと考えております。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ＨＰＶワクチンの大切さ、区民への正確な情報提供の必要性を強く訴えて、私の質問を終わりたいと思います。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"一方、私立保育園では発災時の対応がどのように決められているのでしょうか。園の中で初動体制や役割分担などはどのようになっているのか、お伺いいたします。","respondent":"福島子ども未来部長","answer":"それに沿って、また月に１度、避難訓練を行っているところです。持ち出し品等も一覧表に従いましてリュックに入れる等、準備を進めているところです。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そして、保育士の方たちは把握しておられるのでしょうか。そして、保護者の方たちには、ご自身のお子さんがどこに避難しているのか、どのようにしてわかるのか尋ねました。","respondent":"福島子ども未来部長","answer":"園が所在する町会に割り振られた避難場所に行くことになっておりまして、もちろん園の保育士もそのように認識しております。当初の段階で保護者に重要事項説明書というものをお渡ししておりますし、一斉メールなどを使いまして、保護者に知らせることになっております。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"確認","question":"保育園における避難訓練が確実に行われているかどうか、区は確認されているのでしょうか。万が一のとき、保育園の先生方はＡＥＤの適切な使用ができるのかどうかもお伺いします。","respondent":"福島子ども未来部長","answer":"ＡＥＤにつきましては、区として補助金を交付しておりまして、私立園６６園中、６４園が設置済みです。残りの２園は、園内にはないのですが、同じ敷地内にＡＥＤを設置しています。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"災害のときは、保育園にいる子どもたちの命を守れるよう、区の支援、そして指導をしっかりとやっていただけるよう要望します。続きまして、児童の安全、ゾーン３０についてお伺いします。","respondent":"藤田防災まちづくり部長","answer":"平成２４年度より、各小学校において通学路の緊急合同点検を実施するなど、さらなる通学路の安全・安心の確保に努めてきたところです。防犯カメラの設置など、具体的に実施メニューについて検討し、通学路の安全・安心を確保していこうというものです。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ゾーン３０の整備効果についてお聞きいたします。区内のゾーン３０の指定箇所の数と、ゾーン３０の効果をお知らせほしいと求めました。","respondent":"藤田防災まちづくり部長","answer":"このうち、死亡や重傷事故の発生件数も２６.８％の減少、死亡事故においては３８.９％の減少というような形での効果があると認識しています。１２.２％の速度の抑制の効果があったという報告もございまして、それから速度の抑制について、効果があると認識しています。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ヒヤリハットを含めたゾーン３０を、ぜひとも区から公安委員会に対して地区を要望して、安全に取り組んでほしいと求めました。空き家の現状と成果、有効活用に対する取り組みをお知らせください。","respondent":"中村都市環境部長","answer":"空き家の現状ですけれども、現在、区が認識しております空き家としましては、６４４戸です。そして、この空き家の対応についてですけれども、まず情報提供あるいは区が認知しているものにつきまして現地調査を行います。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"区の活動に理解をいただいて、眠っている資産を少しでも活用できるように取り組みを進めるべきだと私は思っております。空き家の活用に対する今後の課題、今後の見込みについてお知らせくださいとの意見を述べました。","respondent":"中村都市環境部長","answer":"いろいろと有効活用に向けた検討を進めているですけれども、やはり所有者とともに利用・活用の方法について考えて、調整に当たっているです。所有者の意向とニーズといったものについて、マッチングがうまくできるように、引き続き取り組んでまいりたいと考えております。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"総務費で、町会・自治会の支援に関する質問をさせていただきましたけれども、できるだけ重複を避けて質問させてほしいと求めました。品川区町会および自治会の活動活性化の推進に関する条例を制定するきっかけは何だったのか、制定の経緯と検討の経過などを説明を求めました。","respondent":"久保田地域振興部長","answer":"条例制定の経緯と検討経過についてお答えいたします。この２年間の調査研究の中で、町会・自治会の役割の重要性を再認識する一方で、課題を抱えていることも判明いたしました。","id":"exchange-018","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問","question":"町会・自治会長５名を加えた委員会を立ち上げたということで、２年にわたって検討を加えてきた集大成がこの条例であることを、再認識いたしました。効果があったとすれば、どのようなものがあったのか、説明を求めました。","respondent":"久保田地域振興部長","answer":"条例制定による効果としましては、区の責務を明確にしまして、活動や運営に関する支援策を積極的に進めてきたことが挙げられるところであります。","id":"exchange-019","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、条例制定を契機に品川区ではさまざまな新規施策を始めております。例えばシナモロールの加入促進はがき等の活用といった具体的な取り組みについても説明を求めました。","respondent":"久保田地域振興部長","answer":"オリンピック・パラリンピック啓発事業に対する支援、さらには活動物品を保管する場所の賃借料に対する補助金なども開始したところであります。今後もこうした取り組みを有効に活用いたしまして、加入促進支援をはじめ、活動の活性化に向けた支援を積極的に進めてまいります。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２名だと、テストイベントのとき、行きたかったという町会の方もいましたので、ぜひとも、それは要望させてほしいと求めました。役員の高齢化や若者の加入促進といった課題も常に頭の隅に置いていただきまして施策を進めていただきたいという要望を述べまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"芹澤副委員長","kind":"質問","question":"２点目、そして３点目、順次お伺いします。１点目、区内の働き手の確保についてお伺いいたします。","respondent":"伊崎福祉部長","answer":"介護人材の区内の現状と今後の動向の見込みです。品川区をはじめ２３区については同様な状況と聞いておりますが、他の自治体では、人材不足のために事業の継続が困難という話も聞いております。","id":"exchange-022"},{"speaker":"芹澤副委員長","kind":"意見","question":"そういった意味で、事前に品川区内で人材を育成して事業者に届けていくという品川介護福祉専門学校の制度は、大変すばらしいものだと思っています。品川介護福祉専門学校のこれまでの卒業者の就職状況、あとは離職状況を説明を求めました。","respondent":"伊崎福祉部長","answer":"言いかえると、３年以内に離職した場合は返還していただくこととなります。この返還している人数が、平成２５年度以降、指定施設に就職した１２４人中８人ということで、離職率としてはかなり低い数字と認識しております。","id":"exchange-023","title":"町会・自治会支援"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"なぜ品川介護福祉専門学校に入校を決めたのかというところを、アンケートという形で分析をしていくべきだと思いますが、お考えをお聞かせください。いろいろな営業に回っていらっしゃるというお話も伺っていますが、営業に特化して、改めてこちらもご答弁をお願いいたします。","respondent":"伊崎福祉部長","answer":"３点目の、今後も１８歳人口が減っていく中で、品川介護福祉専門学校の魅力を十分に高校あるいは高校生に伝えていく必要があると考えております。これまでも、そういった体制を強化して、これからも全国各地の高校生が利用してくださるように努力していきたいと考えております。","id":"exchange-024"},{"speaker":"芹澤副委員長","kind":"意見","question":"例えば、５年もしくは３年の中で何十人は、区内の人材の確保については非常に有効な施策になるかと思います。インドネシアとの協定、契約について、またご意見を説明を求めました。","respondent":"伊崎福祉部長","answer":"どのような形で取り組むのが適切かどうかということを、今、検討しています。働く上での安心材料となると考えておりますので、プロジェクトチームでの検討も含め、いろいろな手法を考えていきたいと考えております。","id":"exchange-025"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"それと関連して、障害者スポーツ施設についてお伺いいたします。その中にパラアリーナの機能を入れていただくということはできませんか尋ねました。","respondent":"本城教育次長、安藤文化スポーツ振興部長","answer":"１５競技３５名の選手を延べ４４校で、１２競技２２名の選手を延べ３１校で、体験や講演を行ってきたところです。東京２０２０大会終了後につきましては、引き続き実施いたしまして、進めてまいります。 今後、財団の方針を注視しつつ、我々も継続の可能性を探っていきたいと考えています。アリーナを計画する際には、パラアリーナを参考として、可能な限りどなたでも利用できるような体育館を目指していきたいと考えています。","id":"exchange-026"},{"speaker":"芹澤副委員長","kind":"質問","question":"これから東京２０２０大会が閉幕すれば、当然ながらその予算もなくなっていくわけですから、もちろんできないと考えています。大変人気のキャラクターであると伺っております。","respondent":"安藤文化スポーツ振興部長","answer":"しかしながら、委員ご指摘のとおり、今、観光は、水辺を中心としてすごく盛り上がっていて、東京都においても非常に注目されているところです。今後の観光大使を考えた場合には、品川区にゆかりの坂本龍馬等、勘案して検討していきたいと考えています。","id":"exchange-027"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"ちなみに、京都の宇治市では、観光大使が１５人いると伺っております。要望させていただきまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その上で改めて質問をします。この辺のところで、区としての対応をどのようになさったか、改めて確認させてほしいと求めました。","respondent":"堀越企画部長","answer":"いわゆるミラーサイト的なものを、ヤフーのサーバーに設置していただくという、区のサーバーの負荷軽減を図るということの対応など。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そのころ、まだＬ字放送は入っていなかったので、「これはどうなっているのですか」ということをお聞きした記憶が残っています。これは要望にします。","respondent":"堀越企画部長","answer":"地域のつながり・支え合いは、今後も住み続けたいと区民の皆さんに思ってもらうために、これをさらに進めていく必要があると考えています。単身世帯が増えている中、このような掲載順としたもので、長期基本計画の中に品川区らしさを出したものだと考えているところです。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"下町情緒らしいところを、これからも活かしていってほしいと求めましたので、ぜひよろしくお願いしたいと思います。今後の水辺の展開と、地域・企業との連携等について、お考えをお知らせほしいと求めました。","respondent":"濱野区長","answer":"したがって、行政としても、協働・連携については力を入れていきたいと考えています。水を契機としたお付き合いが始まっていると思っておりまして、品川区の水辺ということをしっかりと盛り上げていきたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これからもぜひ進めていってほしいと求めましたし、また詰めていってほしいと求めましたので、どうぞよろしくお願いいたします。大都市事務などの支出も多い中、２３区、また東京都と連携した対応が必要だと考えますが、この点につきましてもお考えをお知らせください。","respondent":"品川財政課長","answer":"それから老朽化した公共施設の更新経費、それから災害による復旧・復興など、今後の財政需要に対応するためには必要不可欠なものと考えております。未来を見据えた積極的な施策の実現や課題解決に向けて、今後も活用方法を検討していきたいと考えております。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区民の皆さんに還元していただきたいと考えていますので、この点、よろしくお願いしたいと思います。この点につきまして、区のお考えをお聞きしたいと思います。","respondent":"品川財政課長","answer":"一方で、前年度も、児童相談所関連経費、それから改築需要集中期への対応など、議論がかみ合わず先送りされた項目もあります。こういったところも財調で何とかできないかというところも含めまして、積極的に普通交付金の算定額を増やしていきたいと考えております。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次に、組織づくりという点ではどのようにお考えになっているか、お聞きしたいと思います。もう既に検討もなさっているとは思うのですが、この検討状況についてご説明ほしいと求めました。","respondent":"堀越企画部長","answer":"長期基本計画の、これらの課題にしっかりと取り組んでいくという考え方のもとに、具体的に必要な組織改正については検討していくという形になります。令和２年度中に検討して、令和３年度からの実施という方向性で、検討しています。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺も含めて、来年度からどう考えているのかということも考えたのですが、東京２０２０大会の後というお話もわかります。この点につきましても、どのように考えているか、お答えをお願いしたいと思います。","respondent":"榎本総務部長","answer":"東京２０２０大会の対応ですとか、この３年間、増員をしています。窓口業務や事務改善の導入状況に合わせて、効率的に業務が進められるようにすることで、後で説明します働き方改革につなげていきたいと考えています。","id":"exchange-035","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"平成３０年７月には、行政内部でどのような組織でどのように検討されているのか、改めてお聞きいたします。和氣副区長の担任事項とされていますが、どのように関与し、議会や区民の意見をどのように反映させていくのかお知らせください。","respondent":"中村都市環境部長","answer":"さまざま検討を行っている段階の中では、庁内検討におきまして、報告や案件を図りながら進めてきているです。あわせて今後も検討状況につきまして、議会や区民の皆様に報告・お知らせをしながら、ご意見をお聞きして進めていきたいと考えております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"レベルが高くて、経費が少なくできる方法も考えてほしいと求めましたが、その辺はいかがお考えでしょうか。それからＪＲを挟んだＣ地区の一帯の開発のことも考えていただきたいと思うのですが、その辺につきましてもお考えをお知らせください。","respondent":"堀越企画部長、中村都市環境部長","answer":"そういうものを検討する中においては、それからさまざまな施設の運営方法等、さまざま手法を検討していきたいと思ってあります。それから、今、委員からご指摘がありました、周辺地区との関係についても… 補助２６号線を挟んでイトーヨーカドーの隣りの地区は、協議会が発足して、これから具体的な検討がさらに進むものと考えております。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次に、障害者施策、福祉について確認させてほしいと求めました。この辺と、３年計画の半分が経った時点での現状、また今後の見通しについてご説明ほしいと求めました。","respondent":"伊崎福祉部長","answer":"保健と医療との連携というテーマにつきましては、現在、関係機関の協議の場の設置に向けて準備を進めているところです。障害児の支援につきましては、新しい総合支援施設の中で、品川児童学園での支援の充実に努めているところです。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中で、障害者団体の方から、また利用する方から、私どもにもいろいろお話が、当然区にも入っていると思いますが、希望、要望が出ております。この辺につきましては、どのように区として考え、指定管理の方と調整していくのか、お答えをお願いいたします。","respondent":"伊崎福祉部長","answer":"障害児者総合支援施設は、１０月に開所したばかりでございまして、対象の範囲を拡大していきたいと考えております。現在、指定管理者では、施設のサービスの利用を考えている方と面談を行い、ニーズの把握を行っていると聞いております。","id":"exchange-039","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後に、教育についてお伺いします。これまでの取り組みの状況を改めてお聞きするとともに、これからの品川区の教育に関する基本的な考えをお聞きしたいです。","respondent":"中島教育長","answer":"これらを進める中で、現在、全校で取り組んでいる品川コミュニティ・スクールの体制というのが重要になってくるだろうと思います。そういう今後の方向性を考えております。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私もグローバル人材に求められる能力というのを調べた中で、異文化ビジネスへの対応、積極性との解説もありました。これからまだコミュニティ・スクールの連携という問題もあると思うのですが、その辺、学校間の連携についてお話をほしいと求めました。","respondent":"中島教育長","answer":"今年は昨年度のような大きなフェスタは実施いたしませんけれども、いろいろと工夫をしながら、内容を発展させてきている状況があります。この持続可能な学校づくりを進めるためにも、品川コミュニティ・スクールに向けて、全力で支援してまいりたいと考えます。","id":"exchange-041"},{"speaker":"つる副委員長","kind":"提案","question":"本年の第１回定例会の一般質問で既に提案していますが、品川区でも本年９月に教育委員会として教職員研修で実践されたと伺っています。カードゲーム「２０３０ ＳＤＧｓ」を活用した研修を改めて提案しますが、教職員研修での評価を伺うとともに、検討状況をお知らせくださいとの意見を述べました。","respondent":"堀越企画部長、本城教育次長、榎本総務部長","answer":"ＳＤＧｓの考え方は、今後、長期基本計画をもとに区政が目指す方向性と重なるものと認識しています。そういった考え方を受けまして、対応表や… 教育委員会では、ＳＤＧｓの理解や学校教育に活かすことを目的とする教員研修を９月１３日に実施したところです。当日は、カードゲーム体験があり… カードゲーム「２０３０ ＳＤＧｓ」の区職員の研修への活用についてですけれども、これまではまだ区の研修では実施しておりませんでした。","id":"exchange-042"},{"speaker":"つる副委員長","kind":"提案","question":"ＳＤＧｓのゴール１２である「つくる責任とつかう責任」の達成に向け、懇談をさせていただき、講演依頼などの提案もさせていただきました。","respondent":"久保田地域振興部長、中村都市環境部長","answer":"中小企業センター１階を活用したパネル展示などを含め、さらに効果的なＰＲ方法などについて検討していきたいと考えているところであります。来年度は消費者センターが新たに参画いたしますので、まずはこうした中で… 職員表彰の表彰状への活用といったものも考えられますし、あるいは職員の名刺といったものでも、あわせて検討してまいりたいと考えております。","id":"exchange-043"},{"speaker":"つる副委員長","kind":"質問","question":"既に品川区内の学校によっては、ＳＤＧｓに関して授業を実践されている教員もいらっしゃると伺っています。子どもたちがＳＤＧｓを学べるコーナーの設置や、図書館のホームページ、図書館広報紙「Ｌｉ Ｌｉ Ｌｉ」でも掲載してはいかがか尋ねました。","respondent":"本城教育次長","answer":"子どもたちが持続可能な開発目標について学べるように図ってまいりたいと考えているところです。今後、委員ご提案の専門コーナーの設置や、ＳＤＧｓの理解を一層進めることができるよう取り組んでいきたいと考えているところです。","id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問・要望","question":"区としての独自の支援策や東京都へ対象に含めるよう、暑さ対策も含め、求めてまいりました。さらに、暑さ対策として冷却材などを配布してはいかがか尋ねました。","respondent":"福島子ども未来部長","answer":"各園に申し入れてありますし、また、区としましてどのような支援ができるか検討してまいります。ボランティアのしな助との連携ですけれども、その辺につきましては、関係する部と今後協議してまいりたいと思います。","id":"exchange-045"},{"speaker":"つる副委員長","kind":"提案","question":"交流しやすいように、広いスペースの確保を求めますが、いかがでしょうか。コロンビア選手団との大会前の交流試合、大会後の交流として、子どもたちや区民とのイベントを実施してはいかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"事前キャンプは、大会前に最適な環境で事前のトレーニングを行うことにより、本番で最高のパフォーマンスを発揮する目的で行うものと認識しています。スポーツの効果や価値の再認識につながることから、交流できるイベントなどの実現に向けて検討していきたいと考えています。","id":"exchange-046"},{"speaker":"つる副委員長","kind":"質問","question":"そこで、ボッチャを区民スポーツとして位置づけ、各地域での取り組みをより一層推進し、区民大会を開催してはいかがでしょうか。日本ボッチャ協会とも連携し、区内でボッチャの国内・国際大会などを誘致してはいかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"ユニバーサルスポーツフェスタなどのイベントにおいて実施するほか、普及活動に取り組んでいるところです。今後、集客が見込めるイベントの開催時の設置など、費用対効果も勘案しながら検討してまいります。","id":"exchange-047"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今年度、品川区議会公明党として２０１０年以来、一貫してその必要性を求めてきた居住支援協議会が設置されます。区民住宅の月平均利用料は１５万円との認識ですが、１戸当たりの維持管理費について、その算出根拠も含めてお知らせください。","respondent":"中村都市環境部長","answer":"この第７条におきまして、入居者を確保できないときには、住宅確保要配慮者に賃貸することができるとも示されているところです。これは管理戸数７５８で割りますと、平均、月に約４万円ということになります。","id":"exchange-048"},{"speaker":"つる副委員長","kind":"質問","question":"結婚を機に、他区へ転出を余儀なくされているご相談を伺う中で、新婚世代など若い世代の定住策として利用促進を促すことも考えられます。区としての区民住宅の利用促進策をどう展開するのかお知らせください、また、新婚世帯など若い世代に区民住宅の提供を検討してはいかがか尋ねました。","respondent":"中村都市環境部長","answer":"要望されているニーズに対して、さまざまに対応できるような用意をしていくことも、また必要かと考えております。目指していますけれども、新婚世代の方など若い世代へ代々つなげていくための取り組みといったものにつきましても検討していきたいと考えております。","id":"exchange-049"},{"speaker":"つる副委員長","kind":"質問","question":"それぞれ引き続き積極的なご検討を期待いたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問","question":"台風１９号の際に、かつてないほど多くの区民の方々が避難所に避難されたと伺いました。そこで改めて、今回の２つの台風について、品川区の被害状況と対応、また今回の状況を踏まえた今後の課題についてご所見をお願いします。","respondent":"曽田災害対策担当部長","answer":"被害確認後は状況把握や応急対策を実施し、罹災証明２９件を発行したところです。台風１５号については、災害対策組織のあり方や計画運休への対応、さまざまな教訓を認識しております。","id":"exchange-051"},{"speaker":"こんの委員","kind":"意見","question":"台風１５号では、残暑の中、停電の長期化により多くの方が熱中症となり、熱中症の疑いで亡くなる高齢者の方もいらっしゃいました。こうしたことを防ぐためのエアコン、冷暖房機の使用について、現在の非常用電源が活用できるのかどうか、あわせて説明を求めました。","respondent":"曽田災害対策担当部長","answer":"非常用発電機は３.９kW、聞慣れない交流の種類の違いによりまして、一部の体育館を除き使用することができないということになっております。この一部の体育館でも非常用電源を使う場合には、大規模な工事が必要となるといった状況となっております。","id":"exchange-052"},{"speaker":"こんの委員","kind":"提案","question":"エアコンが使用可能となるよう、非常用発電機の新設や増設、また既存の電源の拡充などを要望いたします。太陽光発電機を提供する企業が提案している、あらゆる方策によって、停電時でもエアコンを稼働できる暑さ・寒さ対応を強く要望しますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"暑さ・寒さに対応するため、まずエアコンを使用することが最適な手段なのかを検討する必要があると考えております。しかしながら、引き続きエアコンの稼働も含めた、ご提案のさまざまな方策について検討してまいります。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問","question":"基本は自助ですが、各家庭における電源確保についてはどのようにお考えでしょうか。具体的な備えの促進としては、発電機などを備える区民に対し支援策を検討するなど、災害時における在宅への促進策を考えてみてはいかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"これらの対策が整う中で電源対策を検討すべきであり、その検討の中で、あるいはホームページの活用について参考とさせていただきたいと考えています。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"基本は在宅避難といったことですので、さまざまな災害を教訓に、さらなる品川区の防災・減災対策の強化・促進を要望して、次の質問にまいります。次は、インフルエンザ予防接種についてお尋ねします。","respondent":"福内健康推進部長","answer":"インフルエンザは例年１２月から３月ごろ流行するため、今後の流行状況については注意深く見守っていく必要があると考えております。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"向上策の一つとして、自己負担額２,５００円の軽減を要望します。それぞれご見解をお願いします。","respondent":"福内健康推進部長","answer":"全国的な接種率はおおむね５割程度であり、区といたしましては、接種率向上のため、今後とも予防接種の有効性等について啓発に努めてまいります。","id":"exchange-056"},{"speaker":"こんの委員","kind":"提案","question":"これまで品川区議会公明党は、全ての子どもがインフルエンザの予防接種を受けやすくする環境整備を求め、接種費用助成を提案してきたところ。全ての乳幼児が接種しやすい環境整備が必要であり、具体的には、接種費用助成の対象に乳幼児も加えた事業の展開を求めますとの意見を述べました。","respondent":"福内健康推進部長","answer":"罹患による合併症を減らす一定程度の効果があると認識しており、乳幼児へのインフルエンザワクチン接種の効果はあると考えております。直ちに対象拡大を判断することは難しい状況ですが、今後の学級閉鎖等の報告数の推移や小中学生の接種費用助成の状況を踏まえてまいります。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"これまで、３歳児健康診査の視力検査の方法について改善を求めてきました。子どもの片眼弱視を見逃さない検査方法が求められますが、家庭で実施されている検査は、片眼弱視を正確に発見できているのか疑問に感じるところです。","respondent":"福内健康推進部長","answer":"家庭での検査が実施できない場合や、左右のどちらか一方でも絵カードが２つ認識できない場合、検診会場にて再度の検査を行っています。絵カードによる検査方法は、幼児期における、発達段階によっては絵カードの実施も難しいお子さんがいる点では課題があると捉えております。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"今おっしゃった課題を解消するためには、これまで求めてきました自動判定機能付きフォトスクリーナーの導入を求めますが、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"検診会場での薄暗い場所の確保や、新たな検査を導入することによる検診所要時間の増加の対応などの課題もあります。その後の十分な視力を獲得する上で重要と認識しておりまして、情報提供に努めつつ、検討を進めてまいります。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、品川区を低空飛行する羽田新飛行ルートの撤回を求めて、決定発表前と後の品川区の姿勢をそれぞれ伺いたいと思います。品川区に伺いますが、地元の理解は得られたとの国の判断、そして来年からの実施は不当な決定だと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"区でもこれまで要望してきたところで、国はこれまでさまざまな説明会を行ってきております。そういった中で、さまざまな意見を聞いた中での、国の責任においての判断という受けとめ方をしています。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"品川区は地方自治というものをどう理解しているのか伺いたいと思います。地元の理解が得られた、来年実施は不当ではないかと、品川区がどう思っているのか伺いました。","respondent":"中村都市環境部長","answer":"これまで区といたしましては、環境影響に対するさらなる対応、またルートを固定化しないといったものを求めてまいりました。国は引き続き検討すると述べているところです。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"ところが品川区はどうでしょうか。その責任を区は感じていないのか、伺いたいと思います。","respondent":"中村都市環境部長","answer":"区としての意見も、これからも引き続き国に対して求めていかなくてはいけない、求めるべきと考えております。こういったものも踏まえた国の判断という認識です。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういうのはもうやめるべきだと思いますが、いかがでしょうか。区は調査、予測、ちゃんと予見して、必要なデータを入手して国と交渉に挑むべきだと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"これは、国の説明が具体的で十分であると区としても考えておりませんけれども、引き続き、さらなる対応を求めていくです。したがって、こういった対応についても、引き続き国に対して求めていくという考えです。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区は７月３０日の連絡会で、「首都圏空港との調整などにより、この要望は決定後の今も同じか伺いたいと思います。そして、決定後、その要望を国に伝えたのか、伺いたいと思います。","respondent":"中村都市環境部長","answer":"国に求めた検討は、決定の前でも後でも検討できることです。国も引き続き検討するとしていますので、区も、決定後も引き続き求めてまいるという考えです。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"決定後も、その要望は今も同じか。それは決定後、国に伝えたのか、ご説明ください。","respondent":"中村都市環境部長","answer":"「引き続き検討」というのは、区としても、国が決定後も同じように、検討をずっと継続するという解釈です。そして、具体的に国がしっかりと対応案について示していただけるように、引き続き求めてまいります。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"本会議の部長答弁では、「ルートを固定化することがない取り組みを引き続き求めていく」とありました。つまり、国への要望とは、品川区上空、都心上空を飛ばないルート案の検討を国に求めるというのが品川区の立場なのかご答弁ください。","respondent":"中村都市環境部長","answer":"国に検討していただきたい内容を、国が検討する必要があるけれども、その内容の一部を例示として示したものです。引き続き、ルートを固定化しない検討について求めてまいります。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"国への要望は、品川区の上空を飛ばないルートなのかを聞いているのでお答えほしいと求めました。つまり、「固定化しない」とは、品川区を低空で飛ばないルートを国に求めるということか、しっかりとご説明ください。","respondent":"中村都市環境部長","answer":"ルートを固定化しない取り組みにつきましては、国に検討を求めるために、国に伝えたものです。あくまでルートを固定化しない取り組みとして、こういった言葉で国に求めたです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"さまざま求めている中で、つまり品川区の上空を低空で飛ばないルート案が入っているのか、いないのか、そこをお答えください。つまりは品川区議会の「容認できない」と同じ立場に立つべきだと私は思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"これは、品川区上空あるいは都心上空を飛行しないというものに１対１で対応するというところまでは考えておりません。具体的に区として示すことはできませんけれども、これは１種類ではなくて、やはり考えております。","id":"exchange-068"},{"speaker":"中塚委員","kind":"意見","question":"区議会の決議は伝えていると言いましたが、「品川区が容認できない」となぜ言えないのか。「固定化しない」は言えるのだけれども、「容認できない」がなぜ言えないのか、しっかりと説明を求めました。","respondent":"中村都市環境部長","answer":"したがいまして、１種類に限定して申し上げることはできないと思います。１つの例示として、こういった方法もとれるのではないかと、国に対して検討を促すために発言したと考えております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"固定化しないといっても、さまざまあると言うけれども、「品川区の上を飛ばないルートを求める」とは結局は言わない。しっかりとご説明ください。","respondent":"中村都市環境部長","answer":"このまま国が検討をやめてしまうということは、もう区としては考えられないことですので、引き続き強く求めていかなければいけないと考えております。こういったさまざまな取り組みを、区としても国に対して行っていく必要があると思いますので、しっかりと対応してまいります。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"現行計画は容認できないことを、現行計画の撤回を、国に求めるべきなのです。区長は明確にお答えほしいと求めました。","respondent":"中村都市環境部長","answer":"国も、この決定に当たっては、しっかりと声を受けとめる、また対応するとしておりますので、この約束がしっかり果たされるかどうか。これを、これからしっかりと、区としましても、国を見ていかなければいけないと考えております。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"濱野区長、品川区は「容認できない」とは言わない。この態度でいいのか尋ねました。","respondent":"中村都市環境部長","answer":"区としての考えをしっかり国に伝えなければいけない。伝えてまいります。","id":"exchange-072"},{"speaker":"中塚委員","kind":"提案","question":"私は何度も策定委員会で、低空飛行による区民の被害予測や計画撤回に向けた国との交渉などを明記すべきだと提案しましたが、断られました。長期基本計画に品川区の対応をしっかり記すべきではないのか、伺いますとの意見を述べました。","respondent":"中村都市環境部長","answer":"首都圏空港機能強化、羽田の新飛行ルート案ですけれども、これは国が進める事業です。国が進める事業について、区の計画として定めるという性質のものではないと考えております。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"「固定化しない」とは言うが、今回の質疑を通じても、品川区を低空飛行しないルートへの変更は、何度聞いても最後まで、国に求めるとは言わない。計画撤回を強く求めて私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、開発優先の区政から、住民が主人公、暮らし・福祉最優先の区政への転換を求め、超高層再開発、区庁舎建て替えについて質問いたします。今年度の予算額と、この１０年間の合計額、そのうち一般財源が占める割合は何割なのか伺います。","respondent":"中村都市環境部長","answer":"これは、国費が入るということになってから大体５％ぐらいという流れです。地域の中の調和というところで、開発におけるまちづくりがしっかりと進められていくように、検討の委託費というところで出しています。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"で、４０代夫婦・子ども２人の４人世帯の保険料は１０年間で２倍に上がったことを指摘し、せめて子どもの均等割保険料を無料にせよと求めました。なぜ、子どもの均等割無料化には一般財源を使わないのか、伺います。","respondent":"福内健康推進部長、中村都市環境部長","answer":"子どもに係る均等割軽減措置を含め、その制度上の課題につきましては、国が責任を持って対応すべきものと考えています。区といたしましては、子どもの均等割の無料化を国に求めてありますが、引き続き… １つ答弁漏れがございました。過去１０年間において、区が行うまちづくりの委託に関して、単費で行っているということで５億５,１００万円、これは単費１０年です。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"区が自由に使える一般財源を使うというのに、社会の宝であり希望である子どもが健やかに過ごすための２億円に、なぜ区はお金を出さないのでしょうか。先ほど、区の今までの答弁も紹介しましたけれども、改めてその理由を伺いたいと思います。","respondent":"福内健康推進部長、中村都市環境部長","answer":"区ではこれまでも一般財源から国民健康保険会計に繰り入れをし、負担しておりますが、これまで以上の一般財源の投入は難しいと考えております。一方で、保険料は、国民健康保険の財政運用を支える根幹でもありますので… 区として委託して支出しているものですので、これは必要な経費、予算であると認識しております。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"その実施を早急に求めたいと思います。これでよいと思っているのか、伺います。","respondent":"中村都市環境部長","answer":"そして、高度利用地区を図っていくという区域であるとも認識しております。実際には建設が２棟の仕様ということになっておりますけれども、この２棟の間隔をできるだけ離して、区の指導にも基づいて努力しています。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜでしょうか。以上３点、それぞれの理由を伺います。","respondent":"中村都市環境部長","answer":"検討段階という中で、あるいは共同検討を進めるＪＲとの一定の協議といったものをしっかりと整理していかなければいけない、さらに。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"委託の目的や項目の公開というのがどんな混乱を生じさせるのでしょうか。現庁舎の課題を公開するとどんな混乱を生じさせるのか尋ねました。","respondent":"中村都市環境部長","answer":"区として判断をしっかりしまして、そして整理ができた段階で報告あるいは説明をしていくということが、やはり一番合理的な考え方だと考えております。私は２０階といった、しっかりと説明ができる段階になりましたら、適切な方法をもって周知させていただきたいと考えております。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"伺います。ゆえに、検討目的や項目、現庁舎の課題まで黒塗りにするなど、徹底した隠蔽を行ったのではないのか、伺います。","respondent":"中村都市環境部長","answer":"やはり検討の中では敷地をしっかりと整理して、また皆さんに便利に利用していただく区庁舎へつなげるというところで考えていかなければいけないです。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"伺います。そこに区民のニーズはあるのか、伺います。","respondent":"中村都市環境部長","answer":"あるいは区の利益といったものは、考え方としてはまとめたとしても、やはり具体的な金額といったものまでそこで検討するということはできません。しかるべき整理をして、そして適宜報告していく、あるいは説明するというところの前段階ということのほかに他意はございません。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"それも貴重な区民の財産であり、それは切実な区民要望実現のための活用が検討されてしかるべきだと思います。住民が求める区役所機能をはじめ、あるべき庁舎の姿など、開催すること。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"教えてください。説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"事故に限らず、やはり免許をそのまま持ち続けるのがいいのかどうかはご家族としっかりお話をしていただいて判断すべきことだと考えます。その選択肢をなくすことは私はいけないと思いますので、しっかりこのことについては啓発していきたいと考えています。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"この衝突被害軽減ブレーキをご存じですか。そして、この事故を防ぐため、人間の弱点を補助・支援するシステムを車に装備するべきだと思いますが、ご見解を説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"今、十数年前からさまざまな技術について革新が重ねられてきて、現在に至っているということで認識しています。５２.９％と、大変効果があるというものだと、私どもも認識しています。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問","question":"品川区の事業に関わっている全ての自動車に、この安全システムの装備をするべきと思いますが、ご見解をお聞かせください。衝突被害軽減ブレーキの装備を推奨し、この安全装置の普及・啓発等をするべきだと思いますが、ご見解を説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"そういう面では、今、この事業についてしっかりと推奨していくべきだと考えています。区といたしましても、さまざまな場面で警察と連携いたしまして、交通安全のキャンペーンなどでも啓発に取り組んできたところです。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"質問にまだお答えいただいていないのですが、区の直轄の職員ではないですが、死亡事故もあります。その辺について、もう一度ご見解を説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"国際基準も含めてありますので、そうした動きに合わせて、区としてもしっかりと検討していかなければいけないと考えています。今、付かない状態ですので、買い替えのタイミングでこういったものに切り替えていくというようなことも考えてあります。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問・要望","question":"まして働く人を守ってやるというのは、やはり区の上に立っている人たちの務めではないでしょうか。なぜこうなるのか尋ねました。","respondent":"中村都市環境部長","answer":"管理ができていないと考えられるマンションの数は、東京都のマンションの管理の促進条例に基づきまして、届け出などの制度もあります。こういった届け出がされたところで、しっかりと把握して対応してまいりたいと考えております。","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"もしも是正要請先が不明であったり、見つかっても支払い能力がない方しかいない場合はどうするのですか。放置するのか尋ねました。","respondent":"中村都市環境部長","answer":"１棟、２棟であれば、なかなか管理も難しいというところはご指摘のとおりだと思います。予防という観点から、しっかり届け出をしてもらった上で、区としても管理を促していきたいと考えております。","id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"これから管理ということですが、本当に大丈夫なのでしょうか。それとも、そういう場合、他の自治体が実施しているように公費負担をして、行政代執行をして強制撤去するのか尋ねました。","respondent":"中村都市環境部長","answer":"これは今後の検討課題になると思いますけれども、区としても現状把握、そして今後の対応に努力してまいりたいと考えています。これは空き家の活用ができるかどうかの検討もしなければいけませんが、最終的には、選択肢の最終的なものの中には入ってくると考えております。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"本当に分譲マンションは区分所有ですから、５分の４まで賛成者がいればいいですけれど、それ以下だったら壊すことも何もできない。だって、個人だったら、逃げていっていいのですから。","respondent":"中村都市環境部長","answer":"やはり建つことはできませんので、やはり土地の価格というのは同等か、少なくともそれ以上です。こういったところに基づきまして、原因者負担を求めていくということになろうと思います。","id":"exchange-091"},{"speaker":"須貝委員","kind":"意見","question":"では壊すのはどうするのだ。その辺についてもう一回お答えくださいとの意見を述べました。","respondent":"中村都市環境部長","answer":"東京都と連携して、しっかりと、まずは予防に努めてまいりたいと考えております。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"ですから、そのたびに１階に降りて、また自分の３４階の部屋に戻らなければいけない。これまでどおり在宅避難をさせるのか尋ねました。","respondent":"曽田災害対策担当部長","answer":"は平素から備蓄物資を準備しまして、当初必要なものを蓄えておく。マンション内の役立つような組織を事前につくりまして、区としてもできることはしたいと思いますが、それはやはり限定されることになると思います。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"この方たちが避難する場所があるのですか。そして、収容できるだけの広さがあるのか尋ねました。","respondent":"曽田災害対策担当部長","answer":"それほど生活に負担があるという方につきましては、無理にそこにとどまらずに、最寄りの区民避難所に来ていただきたいと考えております。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問","question":"もし、ここで避難するのは、タワーマンションは長期間避難場所とするのは適当ではありませんと、明確にお示しすべきではないですか。それは確保できているのですかとなって、あれだけの人数が、１つのマンションでも千人単位でいるわけですよね。","respondent":"中村都市環境部長","answer":"ただ、これは区民の皆さんの正常な経済活動の一環として、建築基準法に基づき許可を出していると。その所有者が行うというところに基づきまして、今、基準法はそういった仕組みになっているです。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"なぜ無電柱化と無電信柱化は進まないのでしょうか。大震災がいつ起こるかわからないという状況下にもかかわらず、何で対応が遅いのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"１９世紀の最後ぐらいに、２０世紀に入ると、実際には海外と日本の歴史的な背景は大分違うのかと考えています。まちづくりの中では無電柱化を進めていくべきと考えてございまして、方針を立て、計画的に事業を進めていきたいと考えているところです。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"本来なら、区としては、まちの中を最優先して先にやるべき仕事ではないでしょうか。自覚を持って、品川区もやっていただきたいと私は思いますが、今の２点について説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"それを設置しまして、日常のメンテナンスも被害時にも、安全安心な道路環境が確保できると考えている方法です。その辺を、整合性を図りながら、できるところから無電柱化の工事を進めていきたいと考えています。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問・要望","question":"幾つか質問させていただきましたが、やはり区民の安全を最優先にして、一時も早く遂行していただきたいと私は思います。以上で、品川改革連合の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"落下物対策は、その取り決めのとおり検査が実施されているかの確認はどのようにとると説明されているのでしょうか。機種はどうか尋ねました。","respondent":"中村都市環境部長","answer":"初めに、８０デシベルの根拠ですけれども、これはシミュレーターに基づくものではないということで、国からの説明では、実測に基づくです。今までの取り組みについては、区も国に対して説明を求めてきたところで、引き続き国に対しては意見を申し上げたところです。","id":"exchange-099"},{"speaker":"吉田委員","kind":"質問","question":"明確な根拠はないように伺ったのですけれど、そのように理解してよろしいでしょうか。要するに、機種や重量などは明らかにされないまま、現実に飛んでいる飛行機でテスト飛行とするということでよろしいのか尋ねました。","respondent":"中村都市環境部長","answer":"ただ、８０デシベルは１,０００フィートにおけるサンプルですので、国としても可能な限りのところで正確な数値の把握に努めたのかと考えております。その内容については、まだ区としても把握できず、国としても説明されていないです。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問","question":"その辺のことについて伺ったのですが、区としてはもう少しきちんとした説明を受けられていると思いますが、ご説明をお願いいたします。どれぐらいの機種でどれぐらいの重量によってこういう騒音だったとか、そういうことが示されるべきだと思いますが、その辺について見解を伺います。","respondent":"中村都市環境部長","answer":"飛行に際して測定局も設けるですので、しっかりと測定して、また情報提供をしていただくというふうに対応していただきたいと考えております。わかり次第、教えていただくように、区としても伝えてまいりたいと考えております。","id":"exchange-101","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"質問・要望","question":"何か見解があったら伺いたいと思います。その要因をどのようにお考えか伺います。","respondent":"榎本総務部長、伊崎福祉部長","answer":"予定価格の決定、契約手続というところは、経理課が行っても主管課が契約を行っても同じものです。同じく随意契約の場合については、経理課に協議があるものもありますけれども… ご指摘いただきました障害者福祉課の事例を例としてご説明いたします。現在はつつがなく事業は実施しております。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問","question":"先ほど、所管の中で、そういう契約金額の算定を、どのような体制で行われているかを伺ったのですが、その点について、答えるよう求めました。","respondent":"伊崎福祉部長","answer":"お話をさせていただいた上で、当然、見積書をとらせていただきます。事務費等がかかりますので、その分も加算した金額で、見積もりを確認しています。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"所管に委任するところは委任すべきだと思いますが、区としての何らかのチェック体制が必要だと思いますが、その辺について見解を伺います。この意見への対応として、福祉部としてどのような確認体制の強化が図られたのか伺いたいと思います。","respondent":"榎本総務部長、伊崎福祉部長","answer":"随意契約だから１者ということではなくて、随意契約でも２者以上から見積もりをとるというのが原則になっています。２者以上、１者随意契約でできるという形に、規定上はなっております。 具体的な確認体制ということですが、当然、担当者、係長、課長、あと金額をチェックする者という組織の流れの中で、きちんと確認しているということ。それから、監査でのご指摘に基づいて、先ほど申し上げたような対応をとっているです。","id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときの契約の中に、経理課には行かずに所管課の中で全て手続が進んでいると伺ったのですが、その確認は間違っているのでしょうか。もしくは別途ガイドラインを定めるなり、そういう手続が必要ではないかと思うのですが、いかがか尋ねました。","respondent":"榎本総務部長、伊崎福祉部長","answer":"要は、契約の締結権限が、１つのところだけのルートで決まってしまうと、事業者にとっては、そこを狙うという。そういうことのないように、契約権限の配分なり契約手続の配分をして… 見積書の徴取につきましては、特に障害者福祉サービスについては、請け負える事業者というのが、ある程度、限られてきておりますので、そういった意味で、１者見積もりとしていることが多くあります。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"だからプロポーザルという手段が、今、求められています。やるところがないために１者随意契約というのは、その辺について見解があったら、また伺いたいと思います。","respondent":"榎本総務部長、伊崎福祉部長","answer":"経理課への協議ということで、協議については金額も、全てを含んだ協議という形で運用しています。 障害者福祉サービスにつきましては、事業の内容等々、さまざまあります。比較的、何法人かでの対応が可能なものについては、今… 基本的には、いろいろなレアケースが考えられる手続につきましては、経理課に協議があると認識しております。","id":"exchange-106"},{"speaker":"吉田委員","kind":"質問","question":"経理課に協議をされるというのは私も伺っております。その辺についてどのように認識されているか伺いたいと思います。","respondent":"伊崎福祉部長、榎本総務部長","answer":"確かに、監査でのご指摘をいただきました事業の実施当初は、そういった面のご指摘はいただいていたかと認識はしております。多様な参入が可能なやり方ができるようにということで、今、転換を図っているところです。 ほとんど運用上ありませんので、特に第３号についての細目というか、定めておりません。主管課契約に関しましては、経理課協議の上、主管課で完結するという取り扱いをしています。","id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"それについてきちんと整備していただくように求めたいと思います。それから、やはり基本は２者以上の見積もり、プロポーザルによる事業者の決定を求めたいと思いますが、再度ご見解を伺います。","respondent":"榎本総務部長","answer":"基本的には、契約は地方自治法上、一般競争入札、指名競争入札、随意契約、せり売りという４つしかない形になっています。要は、まずは、随意契約の場合でも２者以上から見積もりをとるという形の原則を徹底していきたいと考えています。","id":"exchange-108"},{"speaker":"大沢委員","kind":"提案","question":"経常収支比率は７１.９％、人件費比率は１４.６％であり、引き続き健全財政が維持され、区政運営が行われていることを確認いたしました。予算編成をはじめとする区政運営が区民福祉の一層の向上に寄与することを強く求めるものでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"引き続き、区民の福祉・生活の向上に努められることを要望いたします。東京２０２０大会開催までの機運醸成、令和２年度品川区の予算・事務事業に反映され、品川区議会自民党の意見表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"若林委員","kind":"提案","question":"住宅施策に関する提案などを十分に検討し、来年度の予算編成や、改訂される長期基本計画へ反映されるよう求めます。１９号の風雨による全国各地での甚大な被害と教訓をもとに、区民の安全安心へ邁進されることを強く求め、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民負担の軽減へ、区独自に２億円でできる子どもの国民健康保険料無料化を求めましたが、冷たく拒否しました。法律で定める８０人に１人の基準になるよう、職員増を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問・要望","question":"もっと一人一人の児童・生徒に向き合い、学校教育の原点である学力を身につけさせ、社会で生き抜ける教育をしていただきたい。以上で、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"田中委員","kind":"提案","question":"災害時のトイレの備えについて、区民をはじめ、区内企業へも対策を促し、協力を求めるよう、施策を強化すべきです。各款別審査で指摘・提案させていただいた意見を予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/955943?Template=document&Id=1480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":108175,"voices":257}}]);
